var e={"tool.look":`Observer`,"tool.build":`Construire`,"tool.remove":`Démolir`,"action.rotate":`Pivoter`,"action.undo":`Annuler`,"action.redo":`Rétablir`,"action.inventory":`Inventaire`,"action.alt":`Détails`,"action.close":`Fermer`,"action.save":`Sauvegarder`,"key.hint":`{key}`,"status.0":`En attente`,"status.1":`En marche`,"status.2":`Pas d’entrée`,"status.3":`Sortie pleine`,"status.4":`Aucune ceinture à portée`,"status.5":`Aucune recette`,"status.6":`Aucune cible`,"status.2.hint":`Apportez les ingrédients avec une pince ou posez-les à la main.`,"status.3.hint":`Récupérez la production avec une pince ou le bouton « Prendre ». Liquide : posez des tuyaux ou un réservoir.`,"status.4.hint":`L’extracteur n’atteint aucune ceinture — rapprochez-le de la bande de roches : le fantôme en main rougit quand aucune ceinture n’est à portée.`,"status.5.hint":`Choisissez une recette ci-dessous.`,"status.6.hint":`Une pince a besoin d’une machine ou d’un gravitapis devant et derrière.`,"machine.recipe":`Recette`,"machine.input":`Entrée`,"machine.output":`Sortie`,"machine.contents":`Contenu`,"machine.empty":`Vide`,"machine.held":`En main`,"machine.take":`Prendre`,"machine.put":`Poser {item}`,"machine.remove":`Démolir`,"machine.time":`{s} s`,"inv.title":`Inventaire`,"inv.craft":`Fabrication manuelle`,"inv.queue":`File`,"inv.missing":`Manque`,"inv.craftOne":`×1`,"inv.craftFive":`×5`,"inv.cancel":`Annuler`,"inv.empty":`Vide`,"goal.title":`Objectif`,"goal.skip":`Replier l’objectif`,"goal.ask.go":`Afficher`,"goal.show":`Voir les objectifs`,"goal.done":`Tous les objectifs sont atteints ! La suite, c’est votre propre usine autour d’une étoile vivante.`,"goal.mine":`Extrayez {n} quartz à la main`,"goal.mine.hint":`{touch, select, yes {Touchez un rocher bleu de la ceinture près du repère : le rayon de la vedette extraira le quartz tout seul. Touchez à nouveau le même rocher pour l’arrêter.} other {{pad, select, yes {Visez un rocher bleu de la ceinture près du repère et appuyez sur {pad_confirm} : le rayon de la vedette extraira le quartz tout seul. Visez le même rocher et appuyez à nouveau sur {pad_confirm} pour l’arrêter.} other {Cliquez sur un rocher bleu de la ceinture près du repère : le rayon de la vedette extraira le quartz tout seul. Cliquez à nouveau sur le même rocher pour l’arrêter.}}}}`,"goal.grinder":`Posez un polissoir à côté du récepteur`,"goal.grinder.hint":`Barre des bâtiments → polissoir → un emplacement près du récepteur. Puis « Observer », {touch, select, yes {touchez-le} other {{pad, select, yes {visez-le et appuyez sur {pad_confirm}} other {cliquez dessus}}}} et choisissez « Lentille ».`,"goal.grabber":`Reliez la ligne avec des pinces : la première lentille`,"goal.grabber.hint":`Une pince prend derrière et pose devant, dans le sens de sa flèche. La première : gravitapis → polissoir. La seconde : polissoir → réserve (caisse).`,"goal.lenses":`Attendez {n, plural, one {# lentille} other {# lentilles}} de la ligne`,"goal.lenses.hint":`Rien à faire : la ligne produit une lentille toutes les {sec} s. Elle s’arrête ? {touch, select, yes {Touchez la machine marquée d’un badge} other {{pad, select, yes {Visez la machine marquée d’un badge et appuyez sur {pad_confirm}} other {Cliquez sur la machine marquée d’un badge}}}} : sa fenêtre dit ce qui ne va pas.`,"goal.obsidian":`Un harpon aux rochers orange, puis {n, plural, one {# plaque} other {# plaques}} de la ligne`,"goal.obsidian.hint":`Le troisième harpon va dans le cadre entre la ceinture et le polissoir à plaques, sortie (le point lumineux) droit dedans : il charge le polissoir lui-même, sans gravitapis. Dès qu’il attrape un rocher, le cadre s’éteint et la ligne produit les plaques toute seule : attendez-en {n}. Lumière : un arc de plus et un lumiduc.`,"goal.expand":`Un second polissoir — pour les plaques, près des rochers orange`,"goal.expand.hint":`Fabriquez un polissoir dans l’« Inventaire » ({plates} plaques, {quartz} quartz) et posez-le dans le cadre près de la ceinture orange, côté base. Recette : « Plaque d’obsidienne ». Le harpon se place entre lui et la ceinture : un gravitapis ne peut pas traverser une ceinture.`,"goal.progress":`{have} / {need}`,"toast.saved":`Sauvegardé`,"toast.loaded":`Monde chargé`,"toast.noItem":`Pas de « {item} » dans l’inventaire — fabriquez-en dans l’inventaire`,"toast.newWorld":`Nouveau monde`,"hud.mining":`Extraction`,"hud.debug":`FPS {fps} · UPS {ups} · tick {tick} · machines {entities} · hash {hash}`,"hotbar.label":`Bâtiments`,"a11y.game":`Terrain de jeu de Heliohold`,"machine.rate":`Consomme {rate} {item}/s`,"machine.drills":`≈ {n, plural, one {# harpon} other {# harpons}} en entrée`,"action.pause":`Pause`,"action.resume":`Reprendre`,"hud.paused":`En pause`,"toast.recipeCopied":`Recette copiée — {pad, select, yes {{pad_tabPrev} + {pad_rotate} sur un assembleur} other {Shift+clic sur un assembleur}} pour la coller`,"goal.light":`Amenez la lumière du récepteur au polissoir`,"goal.light.hint":`Tirez un lumiduc de la parabole du récepteur jusqu’à un côté du polissoir — ou placez le polissoir tout contre le récepteur : la lumière passe sans lumiduc. Il s’allume : la lumière est arrivée. Un Arc I donne {arc} ph/s (photons par seconde) — de quoi alimenter un seul polissoir.`,"goal.collectors":`De la lumière pour la base : {n} ph/s ({arcs, plural, one {# arc} other {# arcs}})`,"goal.collectors.hint":`Fabriquez un « Arc I » dans l’« Inventaire » et lancez-le sur l’anneau près de l’étoile. Chaque arc donne {arc} ph/s ; un récepteur prend jusqu’à {cap}.`,"goal.mix":`Mélangez de l’ambre`,"goal.mix.hint":`Mélangeur : des couleurs différentes sur les entrées latérales → de l’ambre devant. La même lumière des deux côtés se consume. Ne fusionnez pas les couleurs dans un même lumiduc : elles interféreraient.`,"goal.focus":`Fabriquez des résonateurs`,"goal.focus.hint":`Un résonateur exige une lumière blanche d’intensité {b} : un focaliseur augmente l’intensité de 1. Un long lumiduc faiblit toutes les {fade} cases.`,"machine.light":`Lumière : {amount} ph, couleur {color}, intensité ≥ {b}`,"machine.flux":`Flux : {n} ph/s`,"machine.lightBuf":`En tampon : {n} ph`,"color.1":`écarlate`,"color.2":`émeraude`,"color.4":`azur`,"color.3":`ambre`,"color.6":`cyan`,"color.5":`magenta`,"color.7":`blanc`,"status.7":`Pas de lumière`,"status.8":`Lumière faible`,"status.9":`Interférence`,"status.10":`Mauvaise couleur`,"status.7.hint":`Tirez un lumiduc depuis un récepteur ou placez la machine tout contre sa sortie. La lumière s’accumule par portions à chaque cycle.`,"status.8.hint":`Intensité insuffisante : un réseau de plus de {fade} cases faiblit — raccourcissez-le ou ajoutez un focaliseur.`,"status.9.hint":`Une couleur, un réseau : des lumiducs qui se touchent fusionnent. Séparez les réseaux de couleurs différentes par une case vide ; un lumiduc en main surligne ce qu’il va rejoindre.`,"status.10.hint":`La recette demande une autre couleur — branchez la bonne sortie du prisme ou du mélangeur.`,"goal.beam":`Envoyez la lumière en rayon`,"goal.beam.hint":`Un port sur un lumiduc change la lumière en rayon, un miroir le dévie, un port en face le reçoit. Un port sans récepteur gaspille la lumière.`,"goal.plates":`Un harpon de plus pour la ligne de plaques : {n, plural, one {# plaque} other {# plaques}}`,"goal.plates.hint":`Un harpon coûte {lenses} lentilles et {plates} plaques : les lentilles sont dans la caisse de la ligne — « Prendre » dans sa fenêtre. Fabriquez un harpon dans l’« Inventaire » et posez-le dans le cadre près du polissoir à plaques, sortie vers lui. Une fois posé, le cadre s’éteint et la ligne tourne à plein régime : attendez {n} plaques. Le polissoir demande {light} ph/s de lumière : s’il en manque, lancez un arc de plus.`,"action.sound":`Son`,"action.soundOn":`Activer le son`,"action.soundOff":`Couper le son`,"stats.title":`Statistiques`,"stats.min1":`1 min`,"stats.min10":`10 min`,"stats.perMin":`{n}/min`,"stats.empty":`Rien n’a encore été produit.`,"goal.completed":`Objectif accompli`,"goal.mine.why":`Des dormeurs sur l’alimentation de secours. Seule une usine peut les sauver, et elle commence par le quartz.`,"goal.grinder.why":`Sentinelle, sans lentilles, aucune machine des archives ne se monte. Le polissoir les taille dans le quartz.`,"goal.light.why":`La lumière de l’arc doit atteindre les machines. Le lumiduc est la première veine : c’est par elle que la lumière coulera aussi jusqu’aux dormeurs.`,"goal.grabber.why":`Une usine qui attend vos mains ne sauvera pas les dormeurs. Des pinces, et la ligne tourne toute seule.`,"goal.lenses.why":`Un stock de lentilles, c’est du temps gagné pour les dormeurs.`,"goal.expand.why":`Il faut rapiécer le module, puis bâtir le portail du retour. L’un comme l’autre se font avec des plaques.`,"goal.obsidian.why":`À la main, les plaques prendraient une éternité. Une ligne les produit seule, et il nous reste un portail à bâtir.`,"goal.plates.why":`Les plaques entrent dans tout : machines, rustines, futur portail. Pleine lumière, pleine vitesse.`,"goal.collectors.why":`Un portail engloutira beaucoup de lumière. Chaque arc est un morceau de la future sphère autour du Berceau.`,"goal.mix.why":`Après le raid, c’est clair : la base doit se défendre. L’ambre charge la Lance, {n} par Lance. Nous le mélangerons nous-mêmes.`,"goal.focus.why":`Un résonateur garde la lumière stable. On en fait la Lance et des machines plus récentes — et une lumière stable éblouit moins l’Essaim.`,"goal.beam.why":`La colonie a besoin de lumière au-delà des ceintures : de nouvelles roches et de la place pour les machines l’y attendent. Un rayon porte la lumière loin, sans faiblir, et passe au-dessus des ceintures.`,"goal.spectrum_m.why":`Un spectre est un échantillon de la lumière d’une classe d’étoiles. Les archives débloquent des plans selon les classes lues : la première, M, ouvre la Résonance.`,"goal.spectrum_m.hint":`Assembleur : la recette « Spectre M » — une lentille rubis, une plaque et de la lumière rouge. Apportez les spectres au Centre par gravitapis et pince, ou à la main.`,"goal.spectrum_m":`Livrez {n, plural, one {# spectre} other {# spectres}} M au Centre`,"goal.resonance.why":`La Résonance rend les extracteurs deux fois plus rapides : l’usine grandit plus vite — et la lumière atteint plus tôt les dormeurs.`,"goal.resonance.hint":`Recherchez « Résonance ». Une voile sur un lumiduc accélère les extracteurs proches ; les pylônes portent l’effet plus loin (jusqu’à {link} cases). Les harpons doivent se trouver dans une zone de {zone}×{zone}.`,"goal.resonance":`Recherchez la Résonance et accélérez {n, plural, one {# harpon} other {# harpons}}`,"goal.spectrum_k.why":`La deuxième classe d’étoiles : K, orange. Chaque classe lue débloque de nouveaux plans dans les archives — et rapproche le portail.`,"goal.spectrum_k.hint":`Recherchez « Spectroscopie » et ajoutez un second assembleur. K : une lentille ambre, une pince et la lumière ambrée du mélangeur (rouge + émeraude). Si une pince ne suit pas l’assembleur, remplacez-la par une pince rapide (« Logistique »). Inutile de porter à la main : une pince du banc vers une caisse, un gravitapis de la caisse à l’assembleur ; remplissez la caisse de pinces voisine avec « Tout poser ».`,"goal.spectrum_k":`Livrez {n, plural, one {# spectre} other {# spectres}} K au Centre`,"goal.liquid.why":`La lumière condensée est l’étape suivante vers la classe G, celle du Berceau lui-même. Sans lumière liquide, impossible de lire son spectre.`,"goal.liquid.hint":`Recherchez « Lumière liquide ». La glace vient des météorites : {touch, select, yes {touchez une météorite} other {{pad, select, yes {visez une météorite et appuyez sur {pad_confirm}} other {cliquez sur une météorite}}}} et traversez les éclats. Placez un condenseur sur la lumière azur d’un prisme et donnez-lui de la glace. Le liquide doit pouvoir s’écouler : un tuyau contient {cap} u — posez {pipes} tuyaux depuis le condenseur (plus tard, un réservoir ou un assembleur de spectre G).`,"goal.liquid":`Produisez {n} u de lumière liquide`,"goal.spectrum_g.why":`La classe G — comme le Berceau lui-même. Trois classes lues, et le Centre pourra décomposer sa lumière jusqu’aux raies les plus ténues.`,"goal.spectrum_g.hint":`Recherchez « Classe G ». Recette : un résonateur, de la lumière liquide et de l’ambre d’intensité {b} (après un focaliseur).`,"goal.spectrum_g":`Livrez {n, plural, one {# spectre} other {# spectres}} G au Centre`,"goal.mine.done":`Quartz en soute. Première pierre d’une colonie qui ne figurait dans aucun plan. J’ai noté l’heure.`,"goal.grinder.done":`Un polissoir ! J’ai passé mon examen de formation sur un de ces engins. Choisissez la recette « Lentille » et donnez-lui lumière et pierre.`,"goal.light.done":`Ça brille ! Si la lumière est arrivée au polissoir, elle arrivera aux dormeurs. Pas tout de suite, mais elle arrivera.`,"goal.grabber.done":`Première lentille sortie de la ligne. L’usine est vivante : elle travaille même quand vous regardez ailleurs.`,"goal.lenses.done":`{n, plural, one {# lentille} many {# lentilles} other {# lentilles}} — la ligne tourne sans vous.`,"goal.expand.done":`Un deuxième polissoir, pour les plaques — c’est avec elles qu’on colmatera le module. Posez un harpon à côté, sortie droit dedans.`,"goal.obsidian.done":`Les plaques arrivent. De quoi colmater le module — et faire grandir une colonie.`,"goal.plates.done":`Ça, c’est de la cadence ! Avec une ligne pareille, on va bientôt me sortir de sous la cloison. Je plaisante : les dormeurs d’abord.`,"goal.collectors.done":`{n} photons par seconde — de quoi alimenter {grinders, plural, one {# polissoir} many {# polissoirs} other {# polissoirs}}.`,"goal.mix.done":`L’ambre — une couleur qu’aucun prisme ne donne. Elle sort de vos mains.`,"goal.focus.done":`Résonateurs prêts — la lumière est prise dans une oscillation pure.`,"goal.beam.done":`Le rayon est arrivé. La lumière n’est plus liée aux lumiducs.`,"goal.spectrum_m.done":`Le Centre a lu son premier spectre ! Encore {n} spectres M, et il recherchera la Résonance.`,"goal.resonance.done":`Harpons en résonance — deux fois plus rapides.`,"goal.spectrum_k.done":`Deuxième classe lue. Le Centre gagne un second anneau et des rayons.`,"goal.liquid.done":`La lumière coule dans les tuyaux comme du miel. Maman n’y croirait pas.`,"goal.spectrum_g.done":`Trois spectres lus. Le Centre est prêt pour le Signal profond.`,"intro.title":`Semeur « Hirondelle »`,"intro.p1":`Vous pilotez le semeur « Hirondelle » : quarante dormeurs, un vieux mécanicien et l’IA ORA. Trouver une étoile vivante. Bâtir près d’elle un portail du retour.`,"intro.start":`Décoller`,"card.pick":`Choisissez un objet ou une recette — vous verrez ce que c’est et à quoi ça sert.`,"card.byHand":`À la main`,"card.cat.ore":`Pierre`,"card.cat.intermediate":`Matériau`,"card.cat.building":`Bâtiment`,"card.cat.ship":`Module de vaisseau`,"card.have":`{n} en stock`,"card.made":`Obtention`,"card.used":`Sert à`,"lock.lab":`Débloqué par le Centre : {tech}`,"toast.locked":`{item} est verrouillé — le Centre le débloque : {tech}`,"inv.items":`Objets`,"inv.craftHint":`clic — détails et fabrication ; clic droit — en fabriquer un`,"lab.title":`Centre de recherche`,"lab.tier":`rang {n}`,"lab.lore":`Les Centres se bâtissent d’après un plan de l’archive du vaisseau. Chacun lit les spectres à la lumière — un lumiduc vers n’importe lequel de ses côtés. La file et la progression sont communes, mais chaque Centre a sa propre science et lit sa propre unité\xA0: plus de Centres, plus de vitesse. Chaque classe spectrale lue ouvre des technologies et allume un anneau de sa couleur.`,"lab.spectra":`Science dans tous les Centres`,"lab.delivered":`total {n}`,"lab.putSpectra":`Répartir la science entre les Centres (les plus proches d’abord)`,"lab.current":`Recherche en cours`,"lab.idle":`Choisissez une technologie : « En tête » ou « Ajouter » dans la liste ci-dessous ou dans l’arbre. Le Centre ne lance rien seul — la science attend dans ses emplacements.`,"lab.tree":`Arbre des technologies`,"lab.request":`{spectra} {have}/{need} → {tech}`,"tech.queued":`en file · {n}`,"tech.state.done":`recherchée`,"tech.state.current":`en cours`,"tech.state.queued":`en file`,"tech.state.available":`disponible`,"tech.state.locked":`verrouillée`,"tech.cost":`Coût : unités × une pièce de chaque palier`,"tech.requires":`D’abord : {list}`,"tech.enqueue":`Ajouter`,"tech.dequeue":`Retirer`,"tech.first":`En tête`,"fluid.amount":`{n} u · {name}`,"machine.fluid":`{name} : {n} u`,"machine.net":`{name} dans le réseau : {n} / {cap} u`,"machine.boost":`résonance +{n} %`,"machine.resonance":`Réseau de résonance : {n} % de la demande couverte`,"etude.title":`Expériences`,"etude.lore":`De courts casse-têtes sur une lumière familière : pièces limitées, une seule tâche. Plus c’est rapide, économique et compact, mieux c’est.`,"etude.parts":`{n, plural, one {# pièce} other {# pièces}}`,"etude.area":`surface {n}`,"etude.best":`Meilleur résultat :`,"etude.start":`Lancer l’expérience`,"etude.solved":`Expérience réussie !`,"etude.goal":`Produisez avec des machines : {item} × {n}`,"etude.again":`Encore une fois`,"etude.pure_tone.name":`Couleur pure`,"etude.pure_tone.task":`Trois sources de blanc, un prisme et un banc : ne donnez au banc que du rouge et faites {n} lentilles rubis. Score — pièces, surface, temps. Les rayons aident à économiser des lumiducs.`,"lab.waiting":`Une unité = une pièce de chaque palier. En attente : {spectra}. Des spectres en trop d’autres classes n’accélèrent rien.`,"hint.prism.3":`Les machines en sortie ne prennent pas de lumière : leur production n’a nulle part où aller, ou une autre entrée leur manque. Donnez-leur du travail — le prisme reprendra seul.`,"hint.drill.6":`La sortie du harpon ne mène nulle part — pivotez ({pad, select, yes {{pad_rotate}} other {R}}) vers un gravitapis, une machine ou une réserve.`,"hint.crafter.7":`Pas assez de lumière : le réseau la partage entre tous ses consommateurs (les voiles aussi en boivent). Ajoutez des arcs sur l’enveloppe, un deuxième récepteur, ou séparez le réseau.`,"menu.title":`Menu`,"menu.tagline":`Une usine autour d’une étoile vivante`,"menu.continue":`Continuer`,"menu.newWorld":`Nouveau monde`,"menu.back":`← Retour`,"menu.difficulty":`Difficulté`,"menu.seed":`Graine du monde`,"menu.randomSeed":`Graine aléatoire`,"menu.start":`Commencer`,"difficulty.calm":`Contemplation`,"difficulty.calm.desc":`Pas d’Essaim. Juste la lumière, les ceintures et la construction.`,"difficulty.standard":`Standard`,"difficulty.standard.desc":`Les nids s’éveillent sous l’éblouissement et envoient des vagues — toujours avec préavis. Tourelles, barrières et réparations sauvent la base.`,"difficulty.abyss":`Abîme`,"difficulty.abyss.desc":`Nids plus proches, vagues plus fréquentes et plus féroces, planètes sous les ruches. Pour les vétérans.`,"settings.title":`Paramètres`,"settings.tab.general":`Général`,"settings.tab.graphics":`Graphismes`,"settings.tab.sound":`Son`,"settings.tab.controls":`Commandes`,"settings.tab.access":`Accessibilité`,"settings.lang":`Langue`,"settings.quality":`Qualité`,"settings.quality.low":`Basse`,"settings.quality.medium":`Moyenne`,"settings.quality.high":`Haute`,"settings.quality.ultra":`Ultra`,"settings.quality.hint":`{touch, select, yes {« Basse » coupe le halo (bloom) : pour les téléphones modestes et les longues parties sur batterie. « Ultra » affiche à pleine netteté et chauffe davantage le téléphone.} other {« Basse » coupe le halo (bloom) : pour les cartes graphiques modestes et les portables sur batterie. « Ultra » affiche à pleine netteté et sollicite davantage la carte graphique.}}`,"settings.showFps":`Afficher les FPS`,"settings.muted":`Muet`,"settings.master":`Volume`,"settings.effects":`Effets`,"settings.ambience":`Ambiance`,"settings.voices":`Voix des personnages`,"settings.keys.hint":`Cliquez sur la touche d’une action, puis appuyez sur la nouvelle touche. Esc annule.`,"settings.keys.press":`Appuyez…`,"settings.keys.fixed":`Toujours : flèches — vol ; molette — zoom ; maintenir et glisser — regarder autour ; clic gauche — poser ou ouvrir ; clic droit — reposer l’objet en main, main vide — démolir ; clic molette — prendre le bâtiment sous le curseur ; Shift+clic droit / Shift+clic gauche — copier et coller une recette ; Shift — plus de détails dans l’infobulle ; 1–0 — bâtiments de la barre, Shift+1–0 — ses onglets ; / — chercher un bâtiment ; Tab — inventaire, dans une fenêtre — parcourir ses boutons ; Ctrl+F — chercher dans le sac ou une recette ; Ctrl+Z / Ctrl+Y — annuler et rétablir ; Ctrl+C / Ctrl+V — plan ; Ctrl+S ou F5 — sauvegarder, F9 — charger la dernière sauvegarde manuelle ; Esc — fermer une fenêtre ou pause.`,"settings.keys.reset":`Touches par défaut`,"settings.uiScale":`Échelle de l’interface`,"settings.reduceFlashes":`Moins de flashs et de clignotements`,"settings.shapesAlways":`Toujours afficher les formes des couleurs — pour distinguer la lumière sans la couleur (daltonisme)`,"settings.access.hint":`Chaque couleur de lumière a sa forme : écarlate ▲, émeraude ●, azur ◆, ambre ■ — comme les signes sur le dos de l’Essaim.`,"key.rotate":`Pivoter`,"key.pipette":`Pipette`,"key.remove":`Démolir`,"key.inventory":`Inventaire`,"key.lab":`Recherches`,"key.alt":`Mode Alt`,"key.pause":`Pause`,"key.sound":`Son on/off`,"key.stats":`Statistiques`,"key.blueprint":`Plan`,"status.13":`Pas de paire`,"status.13.hint":`Posez la deuxième arche devant, à portée du pli (la recherche l’allonge). Un pli de fret a besoin d’une sortie ; les plis de lumière et de tuyau, d’une arche tournée face à la première.`,"status.14":`Surchauffe`,"status.14.hint":`La machine surchauffe : elle ralentit et perd de la lumière en éblouissement. Éloignez-la de l’étoile (r ≥ 7,5) ou ajoutez un radiateur à glace.`,"status.15":`Éteint`,"status.15.hint":`La machine est à l’arrêt : étourdie par la grêle ou sous le quart de son intégrité. Réparez-la — ou attendez, l’étourdissement se dissipe.`,"status.16":`Perd de la lumière`,"status.16.hint":`Une partie de la lumière n’a nulle part où aller et devient éblouissement. Utilisez la sortie en trop ou envoyez-la dans un absorbeur.`,"status.17":`Pas de glace`,"status.17.hint":`Apportez de la glace avec une pince : 1 pour {burn} secondes de refroidissement.`,"hud.glare":`Éblouissement {v} ph/s`,"bp.title":`Plans`,"bp.lore":`Un bon bloc construit ? Inutile de le refaire. Tracez un cadre autour : le plan va dans votre main et dans la bibliothèque. {touch, select, yes {« Pivoter » le tourne, un toucher choisit l’endroit, « Poser » construit.} other {{pad, select, yes {{pad_rotate} pour pivoter, {pad_place} pour poser.} other {R pour pivoter, clic pour poser.}}}} Il se construit depuis l’inventaire ; ce qui manque est ignoré.`,"bp.copy":`Copier par cadre`,"bp.copyHint":`Tracez un cadre autour des bâtiments pour les copier. {pad, select, yes {{pad_back} annule.} other {Esc annule.}}`,"bp.library":`Bibliothèque`,"bp.empty":`Vide pour l’instant : copiez une partie de votre base.`,"bp.count":`{n, plural, one {# bâtiment} other {# bâtiments}}`,"bp.use":`Utiliser`,"bp.share":`Code`,"bp.delete":`Supprimer le plan`,"bp.import":`Ajouter depuis un code`,"bp.add":`Ajouter`,"bp.bad":`Ce n’est pas un code de plan, ou il est endommagé.`,"bp.skipped":`Bâtiments inconnus ignorés : {n}`,"bp.shared":`Code du plan copié — collez-le à un ami.`,"bp.name":`Plan {n}`,"bp.copied":`Copié : {n, plural, one {# bâtiment} other {# bâtiments}}. {touch, select, yes {Touchez un endroit et appuyez sur « Poser ».} other {{pad, select, yes {{pad_rotate} pour pivoter, {pad_place} pour poser.} other {R pour pivoter, clic pour poser.}}}}`,"bp.pasted":`Construits : {n}`,"bp.pastedPart":`Construits : {n} sur {all} ; le reste est bloqué ou manque d’objets.`,"etude.goal.light":`Livrez {n} ph de la bonne lumière au récepteur`,"etude.goal.item":`Livrez {n, plural, one {# pièce} other {# pièces}} au récepteur`,"etude.goal.fluid":`Livrez {n} unités de lumière liquide au récepteur`,"etude.through_wall.name":`À travers le mur`,"etude.through_wall.task":`Le polissoir est enfermé dans un double anneau de murs, avec 7 cases entre eux — aucun pli ne franchit les deux d’un coup. Quartz, lumière blanche et récepteur sont dehors. Faites passer fret et lumière en deux sauts, avec une escale entre les anneaux, et livrez {n} lentilles.`,"etude.amber_duet.name":`Duo d’ambre`,"etude.amber_duet.task":`Changez le blanc en ambre d’intensité 3 (cramoisi + émeraude, puis un focaliseur) et livrez {n} ph au récepteur derrière le mur. Seul un rayon traverse le mur — par la fenêtre.`,"etude.liquid_light.name":`Lumière liquide`,"etude.liquid_light.task":`Un mur à deux fenêtres : glace à droite, lumière à gauche. Le rayon bleu passe par une fenêtre, le liquide par tuyau dans l’autre (une fenêtre = une case : rayon et tuyau ne la partagent pas). Livrez {n} unités de lumière liquide ; le cramoisi et l’émeraude en trop vont aux absorbeurs.`,"goal.tunnel":`Posez un gravitapis des harpons au polissoir`,"goal.tunnel.why":`Une seule vedette, des milliers de roches. Le gravitapis les transporte sans vous, et vous avez mieux à faire.`,"goal.tunnel.hint":`Prenez un gravitapis, {touch, select, yes {touchez la case} other {{pad, select, yes {maintenez {pad_place} sur la case} other {cliquez sur la case}}}} à la sortie du harpon et glissez jusqu’au polissoir. Pas assez ? Fabriquez-en dans l’« Inventaire » avec du quartz et une plaque.`,"goal.tunnel.done":`Le gravitapis tourne ! Au Havre, on n’en a pas posé depuis quarante ans — la lumière est rationnée, pas de place pour ça.`,"goal.haze":`Ciel clair : {n, plural, one {# prisme} other {# prismes}} en marche, fuites ≤ {glare} ph/s`,"goal.haze.why":`Les fuites sont la lumière que la base perd : sorties dans le vide, rayons égarés, surchauffe. Les nids les voient, ainsi que les ateliers au travail. Les fuites sont le plus simple à corriger.`,"goal.haze.hint":`La ligne « fuites » sous le badge « Éblouissement » montre les machines en cause. Utilisez les sorties en trop ou menez-les à un absorbeur par un lumiduc.`,"goal.haze.done":`Le ciel est clair — les étoiles réapparaissent.`,"goal.spear":`Recherchez la « Lance » et chargez-la`,"goal.spear.why":`Toujours plus de météorites — et l’Essaim est déjà venu inspecter la base. La Lance frappe en lumière focalisée : elle fend les météorites et repousse les raids.`,"goal.spear.hint":`La lance demande une intensité ≥ {b} : après un focaliseur. {shot} ph par tir : à {slow} ph/s — un tir toutes les {every} s, à {fast} ph/s — chaque seconde. Portée {range} cases.`,"goal.spear.done":`La lance est chargée. Regardez : une comète fonce vers la base — elle transporte beaucoup de glace.`,"goal.cooling":`Anneau chaud : {n, plural, one {# récepteur} other {# récepteurs}} près de l’étoile sans surchauffe`,"goal.cooling.why":`La colonie a besoin de plus de lumière, et c’est près de la couronne qu’il y en a le plus. Mais les machines y surchauffent : de la glace dans le radiateur — et la chaleur est à vous.`,"goal.cooling.hint":`Recherchez le « Refroidissement ». L’anneau chaud se trouve entre la couronne de l’étoile et l’enveloppe I : un récepteur y capte plus de lumière, mais chauffe. Posez un radiateur à glace tout contre les récepteurs ({n} cases autour) et chargez-y de la glace avec le bouton de sa fenêtre. Le radiateur consomme de la glace tant que le récepteur a chaud : la glace vient des météorites et, à long terme, d’un chalut près de la ceinture de glace et d’un gravitapis avec une pince vers le radiateur (le chalut se débloque dans l’arbre) : le radiateur brûle de la glace tant que le récepteur a chaud.`,"goal.cooling.done":`J’ai passé la moitié de ma vie près du métal brûlant — sans glace, on n’y serre même pas un boulon. L’anneau a refroidi !`,"goal.blueprint":`Copiez une zone ({n}+ bâtiments) et posez la copie`,"goal.blueprint.why":`Une colonie se bâtit sur des années — par blocs répétés. Un bon secteur n’a pas besoin d’être refait : un plan le répète.`,"goal.blueprint.hint":`{touch, select, yes {« Plus » → « Plans » → « Copier par cadre » : tracez un cadre autour des bâtiments, « Copier », puis touchez un endroit et « Poser ».} other {{pad, select, yes {Bouton « Plans » ({pad_hud} atteint les boutons à l’écran), maintenez {pad_place} et tracez un cadre, {pad_rotate} pour pivoter, {pad_place} pour poser.} other {Bouton « Plans » ou C — tracez un cadre, R pour pivoter, clic pour poser.}}}}`,"goal.blueprint.done":`Plan enregistré. Les archives des « Semailles » s’enrichissent — pour la première fois de notre travail, pas de celui de l’Institut.`,"goal.node":`Nid de l’Essaim : nettoyez-le ou endormez-le`,"goal.node.why":`Un nid de l’Essaim près de la base est une menace permanente. Vous pouvez le nettoyer par la force — ou cacher la base : un nid qui s’est réveillé une fois s’endort pour de bon après {calm} min dans l’ombre. Les deux voies donnent de l’antilumière.`,"goal.node.hint":`Posez une lance à {range} cases du nid (flèche) et donnez-lui une lumière focalisée (intensité {b}+) : {shots} tirs pour la reine. La lumière passe par rayon : port → miroirs → port. La reine lâche des gardes contre votre vaisseau — surveillez le bouclier.`,"goal.node.done":`Le nid ne menace plus la base : nettoyé, il brille en protoétoile ; calmé, il dort.`,"status.11":`Pas de liquide`,"status.11.hint":`Raccordez un tuyau de lumière liquide ou libérez l’évacuation : la recette veut du liquide en entrée, ou de la place pour lui en sortie.`,"status.12":`Pas de réseau`,"status.12.hint":`Aucun pylône ni tuyau à proximité — posez-en un plus près.`,"machine.heat":`Chaleur {n} %`,"machine.heatLoss":`perd de la lumière en éblouissement — éloignez-la de l’étoile ou ajoutez un radiateur`,"machine.glare":`Perd {n} ph/s → éblouissement`,"machine.ice":`Glace : {n}`,"cfg.title.modulator":`Rythme`,"cfg.modulator.0":`Constant ▬▬▬`,"cfg.modulator.1":`Pulsé ▮ ▮ ▮`,"cfg.modulator.2":`Double ▮▮ ▮▮`,"cfg.modulator.3":`Décalé ▮ ▮▮ ▮`,"cfg.title.polarizer":`Angle du filtre`,"cfg.polarizer.1":`0°  |`,"cfg.polarizer.2":`45°  /`,"cfg.polarizer.3":`90°  —`,"status.18":`Mauvais rythme`,"status.18.hint":`La recette veut une lumière d’un autre rythme : posez un modulateur et choisissez le rythme dans sa fenêtre.`,"status.19":`Mauvais angle`,"status.19.hint":`La recette veut une lumière d’un autre angle : posez un polariseur et choisissez l’angle dans sa fenêtre.`,"status.20":`Mauvaise phase`,"status.20.hint":`La recette veut l’autre phase de la lumière : placez un déphaseur sur son trajet.`,"cfg.title.shutter":`Mode de l’obturateur`,"cfg.shutter.0":`Ouvert sur signal`,"cfg.shutter.1":`NON : fermé sur signal`,"status.21":`Aucun destinataire`,"status.21.hint":`Aucun port récepteur du même canal avec de la place pour le fret à moins de {range} cases.`,"status.22":`Aucun drone`,"status.22.hint":`Mettez des drones dans les emplacements du port (un assembleur les fabrique avec des lentilles, un résonateur, des plaques et un spectre F).`,"cfg.title.drone_port":`Rôle du port`,"cfg.role.0":`Construction`,"cfg.role.1":`Envoi`,"cfg.role.2":`Réception`,"cfg.channel":`Canal {n}`,"drone.title":`Canal`,"drone.home":`Drones au port : {n}`,"drone.trips":`Trajets au total : {n}`,"drone.put":`Poser des drones ({n})`,"bp.pastedGhost":`Construits : {n}, et {g} en fantômes : les drones les achèveront dès que les objets arriveront`,"bp.ghosted":`Fantômes : {g} — les drones de construction les achèveront à mesure que les objets arrivent`,"goal.spectrum_f":`Livrez {n, plural, one {# spectre} other {# spectres}} F au Centre`,"goal.spectrum_f.why":`Le rythme est la troisième propriété de la lumière après la couleur et l’intensité : le même vert, qui clignote selon un motif. Les nids et l’étoile clignotent ainsi — il est temps de comprendre ce que cela signifie.`,"goal.spectrum_f.hint":`Recherchez « Rythme », placez un modulateur entre le prisme et l’assembleur et choisissez « Pulsation » dans sa fenêtre. Le spectre F, ce sont deux lentilles émeraude sous un vert pulsé.`,"goal.spectrum_f.done":`Quatrième classe lue. Les drones porteront le fret à votre place.`,"goal.drone":`Lancez le premier trajet d’un drone`,"goal.drone.why":`Les drones transportent fret et glace, et achèvent les chantiers pendant que vous faites autre chose.`,"goal.drone.hint":`Recherchez « Drones ». Deux ports : l’expéditeur (rôle et canal dans sa fenêtre) contient drones et fret, {charge} ph de lumière par trajet ; le destinataire utilise le même canal. Le rôle « Collecte » rapporte des éclats de glace.`,"goal.drone.done":`Le drone vole ! Un plan peut désormais se construire tout seul.`,"goal.ghost":`Faites achever par les drones {n, plural, one {# bâtiment fantôme} other {# bâtiments fantômes}}`,"goal.ghost.why":`Un plan qui se construit tout seul : les drones achèvent les fantômes pendant que vous filez vers les ceintures et les nids.`,"goal.ghost.hint":`Un port « Construction » avec des drones et les objets des bâtiments dans ses emplacements. {touch, select, yes {Collez un plan : ce qui manque devient fantôme — les drones l’achèvent quand vous apportez les objets.} other {Ctrl+Shift+V colle un plan en fantômes ; un collage normal à court d’objets laisse aussi des fantômes.}}`,"goal.ghost.done":`Le chantier avance sans vous. Collez vos plans à l’avance.`,"goal.spectrum_a":`Livrez {n, plural, one {# spectre} other {# spectres}} A au Centre`,"goal.spectrum_a.why":`La polarisation, c’est la direction dans laquelle la lumière oscille. Les motifs de l’Essaim sont orientés différemment, comme adressés à quelqu’un. Un polariseur fixe l’angle, mais prend la moitié de la lumière.`,"goal.spectrum_a.hint":`Recherchez « Polarisation ». A, c’est une lumière cyan à 45° : un mélangeur, un polariseur réglé sur 45°, un assembleur.`,"goal.spectrum_a.done":`Cinq classes. La lumière connaît le rythme et l’angle — il est temps de lui apprendre à compter.`,"goal.logic":`Montez un circuit : un obturateur et une lampe, {n, plural, one {# basculement} many {# basculements} other {# basculements}} de l’obturateur`,"goal.logic.why":`La lumière vaut un, l’obscurité zéro : l’usine sait raisonner. Et Sonia est sûre qu’une lampe peut aussi répondre.`,"goal.logic.hint":`Recherchez « Logique optique ». Un obturateur laisse passer la lumière tant qu’un signal brille sur son entrée latérale ; une lampe affiche le résultat. Faites un NON rebouclé sur lui-même et vous obtenez un clignotant.`,"goal.logic.done":`La lumière calcule. Un obturateur fermé est une vanne parfaite, sans éblouissement.`,"goal.spectrum_b":`Livrez {n, plural, one {# spectre} other {# spectres}} B au Centre`,"goal.spectrum_b.why":`La phase est la cinquième propriété de la lumière : le décalage d’une onde. Deux ondes décalées de π s’annulent — et pour l’Essaim, ce décalage veut dire « oui ».`,"goal.spectrum_b.hint":`Recherchez « Phase » — elle demande les spectres G, F et A : F et A se partagent les lentilles émeraude, un deuxième banc émeraude accélère. Le spectre B est une lumière bleue en phase π : un déphaseur sur son trajet. Un interféromètre montre l’annulation.`,"goal.spectrum_b.done":`Six classes lues — il ne reste que la dernière, O.`,"achv.title":`Succès`,"achv.count":`{n} sur {all}`,"achv.hidden":`Un succès caché — à vous de le trouver.`,"achv.at":`à {min} min de jeu`,"achv.toast":`Succès : {name}`,"achv.group.story":`Histoire`,"achv.group.mastery":`Maîtrise`,"achv.group.challenge":`Défis`,"achv.first_light.name":`Première lueur`,"achv.first_light.desc":`La lumière a atteint une machine.`,"achv.first_spectrum.name":`Premier spectre`,"achv.first_spectrum.desc":`Le Centre a lu un spectre M.`,"achv.liquid_dawn.name":`Lumière en tuyau`,"achv.liquid_dawn.desc":`La lumière liquide a coulé dans les tuyaux.`,"achv.dark_out.name":`Le nid est tombé`,"achv.dark_out.desc":`La reine est morte — une protoétoile s’est allumée à la place du nid.`,"achv.first_pulse.name":`Pulsation`,"achv.first_pulse.desc":`Le rythme est la troisième propriété de la lumière, après la couleur et l’intensité.`,"achv.sky_carriers.name":`Coursiers célestes`,"achv.sky_carriers.desc":`Le premier trajet d’un drone.`,"achv.logic_gate.name":`La lumière calcule`,"achv.logic_gate.desc":`Le premier circuit à obturateur fonctionne.`,"achv.awakening.name":`Le Lien`,"achv.awakening.desc":`La Fibre longue est tirée — le Havre capte l’« Hirondelle ».`,"achv.red_horizon.name":`Horizon rouge`,"achv.red_horizon.desc":`Un avant-poste près d’une protoétoile de la Crête écarlate.`,"achv.spm_60.name":`Un spectre par seconde`,"achv.spm_60.desc":`{n} spectres par minute.`,"achv.spm_300.name":`Spectrographe`,"achv.spm_300.desc":`{n} spectres par minute.`,"achv.spm_1000.name":`Observatoire`,"achv.spm_1000.desc":`{n, number} spectres par minute.`,"achv.machines_100.name":`Cent machines`,"achv.machines_100.desc":`{n} bâtiments dans le monde.`,"achv.machines_500.name":`Toute une ville`,"achv.machines_500.desc":`{n} bâtiments dans le monde.`,"achv.clean_100.name":`Ciel clair`,"achv.clean_100.desc":`{min} minutes sans éblouissement avec cent machines en marche (gravitapis et lumiducs exclus).`,"achv.clean_1000.name":`Une base sans éblouissement`,"achv.clean_1000.desc":`{min} minutes de ciel clair avec mille machines en marche.`,"achv.tunnel_trio.name":`Cité des plis`,"achv.tunnel_trio.desc":`Fret, lumière et liquide traversent des plis en même temps.`,"achv.blueprint_50.name":`Bureau d’études`,"achv.blueprint_50.desc":`Un plan de {n} bâtiments collé.`,"achv.swarm.name":`Nuée`,"achv.swarm.desc":`{n} drones en vol à la fois.`,"achv.sings.name":`Le calculateur clignotant`,"achv.sings.desc":`Obturateurs basculés {n, number} fois.`,"achv.prima.name":`Prima`,"achv.prima.desc":`Fibre longue en {h} h {m} min de jeu.`,"achv.no_hands.name":`Sans les mains`,"achv.no_hands.desc":`La Fibre longue avec au plus {n} objets fabriqués à la main.`,"achv.silent_hall.name":`Lumière constante`,"achv.silent_hall.desc":`Une heure sans qu’aucune machine clignote « Pas de lumière », avec dix machines ou plus en marche.`,"achv.abyss_awakening.name":`Abîme`,"achv.abyss_awakening.desc":`La Fibre longue dans un monde « Abîme ».`,"achv.clean_awakening.name":`Voie propre`,"achv.clean_awakening.desc":`La Fibre longue sans jamais éblouir le ciel au-delà de {glare} ph/s.`,"etude.locked":`S’ouvre après l’objectif « {goal} »`,"tech.learned":`Recherche terminée : {name}`,"tech.learned.opens":`Recherche terminée : {name} · débloqué : {list}`,"menu.system":`Système stellaire`,"system.cradle":`Le Berceau`,"system.cradle.desc":`Une étoile jaune de classe G et six ceintures. Là où tout commence.`,"system.red_ridge":`La Crête écarlate`,"system.red_ridge.desc":`Une naine rouge : moitié moins de lumière, des ceintures serrées et riches. La lumière blanche ne vient que des protoétoiles-braises dans les interstices.`,"goal.ridge_light":`Captez {n} ph/s de lumière avec des récepteurs`,"goal.ridge_light.why":`La lumière d’une naine rouge est deux fois plus faible — collectez plus près.`,"goal.ridge_light.hint":`Sans lumière blanche, les polissoirs (lentilles et plaques) ne marchent pas, et la naine rouge ne donne que de l’ambre : le blanc vient des protoétoiles, chacune avec sa petite sphère. Les arcs sur la sphère de la naine donnent de l’ambre ; le kit contient 48 lentilles et deux bancs — assez pour l’objectif azur et 4 arcs, ensuite les lentilles de votre propre polissoir.`,"goal.ridge_light.done":`La lumière est réunie. Mais ici, pas de bleu.`,"goal.ridge_blue":`Fabriquez {n, plural, one {# lentille azur} other {# lentilles azur}} avec des machines`,"goal.ridge_blue.why":`La lumière bleue n’existe qu’auprès des protoétoiles : bâtissez un avant-poste.`,"goal.ridge_blue.hint":`Les protoétoiles blanches se trouvent dans les interstices entre les ceintures — la flèche de l’objectif mène à la plus proche. Chacune a sa petite enveloppe de {slots} arcs : posez des arcs et un récepteur à côté — il captera le blanc. Il fait chaud près d’une protoétoile : le bouclier de la vedette ne s’y recharge pas — posez les arcs depuis le bord extérieur et ne vous attardez pas.`,"goal.ridge_blue.done":`L’avant-poste tourne : la lumière bleue a atteint l’usine.`,"settings.haptics":`Retour haptique`,"toast.autoQuality":`Trop peu d’images par seconde : graphismes réduits à « {q} » (moins de halo).`,"touch.hint":`Glissez pour vous déplacer, pincez pour zoomer. Un toucher montre un fantôme, « Poser » confirme. Maintenez une machine pour sa fenêtre, touchez à deux doigts pour annuler.`,"forge.title":`Forge stellaire`,"forge.stars":`étoiles allumées : {n}`,"forge.lore":`Une forge ancienne près du trou noir. Elle prend les sept spectres, l’antilumière et trois marques des systèmes — et maintient le spectre complet jusqu’à ce qu’une étoile s’allume.`,"forge.chord":`Spectre complet : sept classes et l’antilumière`,"forge.relics":`Reliques des systèmes`,"forge.relic.in":`déposée`,"forge.relic.have":`dans votre sac : déposez-la`,"forge.relic.none":`aucune : obtenez-la en achevant l’objectif d’un système`,"forge.put":`Déposer depuis le sac`,"forge.progress":`Maintien du spectre`,"forge.status.0":`La Forge attend le spectre complet.`,"forge.status.1":`Le spectre tient : chaque impulsion prend un spectre de chaque classe et de l’antilumière.`,"forge.status.2":`L’étoile attend. Allumez-la !`,"forge.status.noRelics":`Reliques nécessaires : {have}/{need}. Les objectifs des systèmes les rapportent : Crête, Saphir, Jumeaux, Voile, Pulsar.`,"forge.status.starved":`Le spectre a rompu : il manque « {item} ». La progression baisse.`,"forge.rule":`Une impulsion toutes les {sec} s. Une impulsion manquée coûte {drain} de progression, sans jamais la remettre à zéro.`,"forge.eta":`Encore ≈ {time} à tenir.`,"forge.min":`{n} min`,"forge.sec":`{n} s`,"forge.ignite":`Allumer l’étoile`,"finale.nameTitle":`Nommer l’étoile`,"finale.nameLead":`Elle s’est allumée. Comment l’appeler ?`,"finale.nameOk":`Nommer`,"finale.creditsTitle":`Générique`,"finale.credits.0":`Les étoiles s’éteignaient. Vous avez demandé — et l’une d’elles s’est allumée.`,"finale.credits.1":`Chaque arc de votre sphère est une lumière que l’on a demandée.`,"finale.credits.2":`La lumière blanche, ce sont sept couleurs vues d’un seul coup.`,"finale.credits.3":`La forge est rechargée : la prochaine étoile demandera davantage.`,"finale.credits.4":`Votre constellation vous attend dans le menu principal.`,"finale.credits.5":`Une usine autour d’une étoile vivante.`,"finale.card.time":`heures de jeu`,"finale.card.npm":`pic de spectres par minute`,"finale.card.machines":`machines`,"finale.card.stars":`étoiles dans la constellation`,"finale.continue":`Continuer`,"finale.toast.lit":`L’étoile « {name} » est allumée !`,"menu.stars":`Constellation ({n})`,"menu.starsTitle":`Votre constellation`,"menu.starLine":`{h} h · pic {npm} spectres/min · {machines} machines`,"system.sapphire":`Saphir`,"system.sapphire.desc":`Une géante bleue : bien plus de lumière, mais aussi de chaleur — machines et bouclier surchauffent. Au-delà de la ligne des glaces s’étend une ceinture de givre d’hélium.`,"system.horizon":`Horizon`,"system.horizon.desc":`Un trou noir et son disque d’accrétion — une ceinture rapide et ultra-riche, dans la chaleur. La Forge stellaire : c’est ici que s’allume le final.`,"goal.si":`Produisez {n, plural, one {# spectre} other {# spectres}} O avec des machines`,"goal.si.why":`Classe O — les étoiles les plus chaudes. La clé du portail est le spectre complet, de M à O, et sans la dernière classe, impossible de l’assembler.`,"goal.si.hint":`Recherchez la « Classe O ». O, c’est une lumière magenta à double rythme en phase π (intensité {b}+) plus de l’antilumière : elle tourne en petite ceinture autour d’un nid de l’Essaim nettoyé ou endormi — prenez-la au chalut.`,"goal.si.done":`Sept classes — le spectre complet. Les Forgerons l’arrachaient aux étoiles par la force ; nous l’avons bâti nous-mêmes.`,"goal.sap_cool":`Recherchez « Cryogénie » et posez {n, plural, one {# cryoradiateur} other {# cryoradiateurs}}`,"goal.sap_cool.why":`L’étoile géante fait surchauffer les machines près de la couronne : sans refroidissement, la lumière se perd en éblouissement.`,"goal.sap_cool.hint":`Ouvrez le Centre et mettez la « Cryogénie » en file (les spectres sont dans le kit de départ). Le cryoradiateur refroidit les machines près de la géante.`,"goal.sap_cool.done":`Les machines ont refroidi : vous pouvez bâtir plus près de l’étoile.`,"goal.sap_frost":`Récoltez {n} × givre d’hélium au chalut`,"goal.sap_frost.why":`Le givre est le carburant du cryoradiateur : sans lui, la chaleur revient.`,"goal.sap_frost.hint":`La ceinture de givre est au-delà de la ligne des glaces (flèche). Un chalut près de la ceinture — un gravitapis — une réserve ; le radiateur prend le givre d’une pince.`,"goal.sap_frost.done":`Le givre arrive tout seul.`,"goal.sap_la":`Livrez {n, plural, one {# spectre} other {# spectres}} B au Centre`,"goal.sap_la.why":`Sous la lumière de la géante, les spectres se font plus vite — mais il fait aussi plus chaud.`,"goal.sap_la.hint":`Le spectre B est une lumière bleue en phase π. Servez-vous de tout ce que vous savez : ici, la lumière est généreuse.`,"goal.sap_la.done":`La géante donne sa lumière sans compter.`,"goal.sap_relic":`Atteignez {n, plural, one {# spectre} other {# spectres}} par minute`,"goal.sap_relic.why":`Le gage de Saphir : la Relique du Givre servira près du trou noir.`,"goal.sap_relic.hint":`Tous les spectres ensemble, au moins {n} par minute — le pic est compté une fois par minute. Ajoutez des drones et des enveloppes extérieures.`,"goal.sap_relic.done":`La Relique du Givre est à vous, sauvegardée dans votre profil.`,"goal.hz_light":`Captez {n} ph/s de lumière avec des récepteurs`,"goal.hz_light.why":`Le spectre complet des sept classes exige ≈ 1 000 ph/s de lumière.`,"goal.hz_light.hint":`Le disque du trou noir est très brillant : une sphère autour donne beaucoup. Posez arcs et récepteurs ; près de la couronne, les machines chauffent — radiateurs indispensables.`,"goal.hz_light.done":`Lumière captée. Maintenant, l’Essaim.`,"goal.hz_node":`Nid de l’Essaim : nettoyez-le ou endormez-le`,"goal.hz_node.why":`Un nid — nettoyé ou endormi — laisse une ceinture d’antilumière : il en faut pour le spectre O comme pour la Forge elle-même.`,"goal.hz_node.hint":`Le nid est derrière la base (flèche). Une lance porte à {range} cases, lumière d’intensité {b}+. Ici, la reine est plus coriace et les vagues plus féroces ; on peut aussi cesser de l’aveugler — un nid endormi laisse la même ceinture.`,"goal.hz_node.done":`Le nid ne menace plus — une ceinture d’antilumière tourne autour.`,"goal.hz_si":`Recherchez « Classe O » et produisez {n, plural, one {# spectre} other {# spectres}} O`,"goal.hz_si.why":`La septième classe complète le spectre.`,"goal.hz_si.hint":`Le spectre O : magenta à double rythme en phase π, intensité {b}+, plus de l’antilumière de la ceinture d’un nid nettoyé ou endormi (chalut).`,"goal.hz_si.done":`Sept classes d’étoiles — le spectre complet.`,"goal.hz_antilight":`Récoltez {n} × antilumière au chalut`,"goal.hz_antilight.why":`{forge} part dans les spectres O et {forge} dans la Forge.`,"goal.hz_antilight.hint":`La ceinture d’antilumière tourne autour d’un nid éteint ou endormi : deux chaluts suffisent. N’oubliez pas la défense.`,"goal.hz_antilight.done":`L’antilumière est là. Reste la Forge.`,"goal.hz_ignite":`Allumez l’étoile dans la Forge`,"goal.hz_ignite.why":`Voilà le but de tout cela : le spectre complet — la lumière blanche — allume une étoile.`,"goal.hz_ignite.hint":`Déposez trois reliques, amenez des gravitapis avec les sept spectres et l’antilumière ({rate, number} de chaque par seconde) et maintenez le spectre complet {hold} s.`,"goal.hz_ignite.done":`Une étoile s’allume !`,"relic.earned":`Relique obtenue : « {name} ». Elle est sauvegardée dans votre profil ; trois reliques, quelles qu’elles soient, ouvrent Horizon.`,"achv.class_o_made.name":`Géante bleue`,"achv.class_o_made.desc":`Un spectre O fabriqué par des machines : le spectre complet est réuni.`,"achv.cold_giant.name":`Refroidir la géante`,"achv.cold_giant.desc":`Les cryoradiateurs de Saphir tournent.`,"achv.frost_bearer.name":`Porte-givre`,"achv.frost_bearer.desc":`La Relique du Givre obtenue à Saphir.`,"achv.star_lit.name":`Allumer une étoile`,"achv.star_lit.desc":`La Forge stellaire a libéré le spectre complet : une nouvelle étoile s’est allumée sur la carte.`,"hint.noLight.first":`La lumière n’atteint pas la machine : posez un arc sur l’enveloppe près de l’étoile, un récepteur à côté, et tirez un lumiduc. Le badge au-dessus de la machine indique ce qui manque.`,"toast.autoQuality.undo":`Annuler`,"forge.need":`Il faut {rate} de chaque spectre et d’antilumière par seconde.`,"forge.relicsHint":`La forge reste inerte sans trois reliques : les objectifs des autres systèmes les rapportent. Elles sont gardées dans votre profil et rejoignent le paquetage de chaque nouveau monde.`,"system.twins":`Les Jumeaux`,"system.twins.desc":`Deux étoiles, l’une ambrée, l’autre bleue, avec des ceintures autour des deux. La lumière blanche naît du mélange des deux ; les cellules de lumière tiennent la nuit.`,"system.veil":`Nébuleuse du Voile`,"system.veil.desc":`Une nébuleuse : pas de roche — seulement des ceintures de brume glacée. Quartz et obsidienne se tirent du brouillard.`,"system.pulsar":`Pulsar de Kepler`,"system.pulsar.desc":`Une étoile à neutrons clignote : toute la lumière arrive rythmée, le spectre F se passe de modulateur. Les ceintures sont des débris de supernova.`,"goal.twin_white":`Fabriquez {n, plural, one {# lentille} other {# lentilles}} avec des machines`,"goal.twin_white.why":`Les polissoirs veulent de la lumière blanche, et ici les deux étoiles n’ont pas la même couleur.`,"goal.twin_white.hint":`La sphère des Jumeaux entoure les deux étoiles : de jour, sa lumière est ambrée, puis bleue — jamais les deux à la fois. Prenez le bleu directement sur la sphère et l’ambre dans une cellule de lumière remplie de jour ; les deux dans un mélangeur, le blanc vers le polissoir.`,"goal.twin_white.done":`Deux étoiles fondues en lumière blanche.`,"goal.twin_blue":`Fabriquez {n, plural, one {# lentille azur} other {# lentilles azur}} avec des machines`,"goal.twin_blue.why":`La lumière bleue n’existe qu’auprès de la seconde étoile : le banc optique doit se tenir à côté.`,"goal.twin_blue.hint":`L’étoile bleue est à 70 cases de l’ambrée. Bâtissez un avant-poste près d’elle, ou tirez un lumiduc : l’intensité baisse avec la distance.`,"goal.twin_blue.done":`La lumière bleue a atteint l’usine.`,"goal.twin_relic":`Tenez {n, plural, one {# spectre} other {# spectres}} par minute, même la nuit`,"goal.twin_relic.why":`Le gage des Jumeaux : la relique servira près du trou noir.`,"goal.twin_relic.hint":`Tous les spectres ensemble, au moins {n} par minute — même en fin de nuit, quand il n’y a plus d’étoiles. La lumière de la sphère change de couleur avec les étoiles ; les cellules de lumière tiennent la nuit.`,"goal.twin_relic.done":`La Relique des Jumeaux est obtenue et sauvegardée dans votre profil.`,"goal.veil_quartz":`Tirez {n} quartz du brouillard avec des machines`,"goal.veil_quartz.why":`Ici, pas de roche — sans quartz, ni lentilles ni spectres.`,"goal.veil_quartz.hint":`La glace (flèche) plus la lumière bleue dans un condenseur donnent de la lumière liquide ; un deuxième condenseur réglé sur « Quartz du brouillard » change glace et lumière liquide en quartz.`,"goal.veil_quartz.done":`Le quartz naît de la lumière.`,"goal.veil_lens":`Fabriquez {n, plural, one {# lentille} other {# lentilles}} avec des machines`,"goal.veil_lens.why":`Les lentilles sont la base de tout spectre ; il y en a désormais assez pour une usine.`,"goal.veil_lens.hint":`Posez les condenseurs en rangées : gravitapis et pinces marchent comme autour de la roche.`,"goal.veil_lens.done":`Les lignes avancent sans sol ferme.`,"goal.veil_relic":`Livrez {n, plural, one {# spectre} other {# spectres}} M et {n} K au Centre`,"goal.veil_relic.why":`Le gage du Voile : la relique servira près du trou noir.`,"goal.veil_relic.hint":`Les spectres se font comme ailleurs, seule la matière première vient du brouillard : un chalut dans la brume glacée, un condenseur, le brouillard en quartz. La lumière est plus rare ici.`,"goal.veil_relic.done":`La Relique du Voile est obtenue et sauvegardée dans votre profil.`,"goal.pulse_light":`Captez {n} ph/s de lumière avec des récepteurs`,"goal.pulse_light.why":`L’étoile est brillante, mais sa lumière arrive par pulsations ; reste à lui trouver un usage.`,"goal.pulse_light.hint":`La pulsation se voit dans les lumiducs sous forme de clignotement. Polissoirs et spectres M/K/G n’en ont cure : ils prennent n’importe quel rythme.`,"goal.pulse_light.done":`Le pulsar alimente l’usine.`,"goal.pulse_fa":`Livrez {n, plural, one {# spectre} other {# spectres}} F au Centre`,"goal.pulse_fa.why":`Le spectre F, c’est le rythme, et ici il vient tout seul : pas besoin de modulateur.`,"goal.pulse_fa.hint":`Une lumière verte pulsée : la sortie verte du prisme garde le rythme de l’étoile. L’assembleur F la prend telle quelle.`,"goal.pulse_fa.done":`Le rythme tout prêt — ça marche.`,"goal.pulse_relic":`Livrez {n} de chacun des spectres M, K et F au Centre`,"goal.pulse_relic.why":`Le gage du Pulsar : la relique servira près du trou noir.`,"goal.pulse_relic.hint":`Trois spectres au rythme du pulsar. Si la lumière se trouble, ne mélangez que des rayons de même rythme.`,"goal.pulse_relic.done":`La Relique du Pulsar est obtenue et sauvegardée dans votre profil.`,"stick.label":`Joystick de vol de la Sentinelle`,"keeper.recenter":`Vers la Sentinelle`,"toast.far":`Hors de portée de la Sentinelle — approche en cours`,"toast.farMining":`Extraction arrêtée : la Sentinelle est trop loin`,"guide.title":`Tutoriel`,"guide.skip":`Quitter le tutoriel`,"guide.skipStep":`Passer l’étape`,"guide.fly":`{pad, select, yes {Volez jusqu’au repère près des roches bleues : stick gauche. {pad_tabPrev} + stick droit pour zoomer, {pad_recenter} recentre sur la vedette. La flèche au bord de l’écran montre la voie.} other {Volez jusqu’au repère près des roches bleues : WASD. La molette zoome, Espace recentre sur la vedette. La flèche au bord de l’écran montre la voie.}}`,"guide.fly.touch":`Poussez le joystick vers le repère près des roches bleues. La flèche au bord de l’écran montre le chemin.`,"guide.fly.why":`N’approchez pas trop de l’étoile : le bouclier surchaufferait. J’ai besoin de vous en état de marche.`,"guide.mine":`Cliquez sur une roche bleue — le rayon de la vedette extraira le quartz tout seul. Il en faut {n}.`,"guide.mine.touch":`Touchez une roche bleue — le rayon de la vedette extraira le quartz tout seul. Il en faut {n}.`,"guide.mine.why":`À la main, c’est long, je sais. Les premières pierres se font toujours à la main, commandant. Les machines viendront après.`,"guide.lay-tunnel.touch":`Touchez le bord {o, select, 1 {supérieur} 2 {droit} 3 {inférieur} other {gauche}} du cadre et, sans lever le doigt, glissez vers {o, select, 1 {le bas} 2 {la gauche} 3 {le haut} other {la droite}} jusqu’au bout.`,"guide.place-grinder":`Posez le polissoir dans le cadre, à côté du récepteur.`,"guide.place-grinder.repick":`Prenez le polissoir dans la barre des bâtiments : il taille le quartz en lentilles.`,"guide.recipe":`Une machine sans tâche n’est que du métal. Ouvrez le polissoir et choisissez la recette « Lentille ».`,"guide.recipe.open":`Sélectionnez le polissoir pour ouvrir sa fenêtre.`,"guide.recipe.why":`Une recette, c’est un ordre de travail. Ici, les machines comprennent vite — pas comme la navigation.`,"guide.place-grabIn":`Posez une pince dans le cadre, entre le gravitapis et le polissoir.`,"guide.place-grabIn.rotate":`Tournez la pince, flèche vers {o, select, 1 {la gauche} 2 {le haut} 3 {la droite} other {le bas}} — vers le polissoir : « Pivoter » ou {pad, select, yes {{pad_rotate}} other {R}}, encore {n, plural, one {# fois} other {# fois}}.`,"guide.place-grabIn.repick":`Prenez une pince dans la barre des bâtiments : elle prend derrière et pose devant, dans le sens de sa flèche.`,"guide.place-grabOut":`La deuxième pince va dans le cadre {o, select, 1 {sous le polissoir} 2 {à gauche du polissoir} 3 {au-dessus du polissoir} other {à droite du polissoir}} : elle sortira les lentilles.`,"guide.place-grabOut.rotate":`Tournez la pince, flèche vers {o, select, 1 {le bas} 2 {la gauche} 3 {le haut} other {la droite}} — à l’opposé du polissoir : « Pivoter » ou {pad, select, yes {{pad_rotate}} other {R}}, encore {n, plural, one {# fois} other {# fois}}.`,"guide.place-grabOut.repick":`Prenez une autre pince.`,"guide.place-storage":`La réserve, une caisse pour les lentilles, se pose dans le cadre devant la flèche de la deuxième pince.`,"guide.place-storage.repick":`Prenez la réserve — une caisse pour les lentilles finies.`,"guide.lay-lights":`Tirez la veine : un lumiduc le long du cadre, du récepteur au polissoir.`,"guide.lay-lights.repick":`Prenez un lumiduc : il porte la lumière du récepteur à une machine.`,"guide.first-lens":`Regardez : le quartz vole, le polissoir travaille. Attendons la première lentille dans la caisse.`,"guide.first-lens.why":`Si une machine s’arrête, un badge apparaît au-dessus — {touch, select, yes {touchez la machine} other {{pad, select, yes {visez la machine et appuyez sur {pad_confirm}} other {cliquez sur la machine}}}}, sa fenêtre dira ce qui cloche.`,"guide.done":`Tutoriel terminé ! La carte d’objectif en haut vous guide désormais.`,"guide.recipe.look":`Appuyez sur « Observer » ({pad, select, yes {{pad_back}} other {Esc}}) : {pad, select, yes {viser avec {pad_place}} other {{touch, select, yes {un appui} other {un clic}}}} sur une machine l’ouvre alors au lieu de construire.`,"landmark.lab":`Épave du module`,"landmark.lab.sub":`l’« Hirondelle » · baie cryo et archives`,"landmark.star":`Étoile du Berceau`,"landmark.star.sub":`la source de lumière`,"intro.t0":`La lumière s’éteint`,"intro.p0":`Les étoiles s’éteignent l’une après l’autre. Et avec elles, les portails qui reliaient les humains.`,"intro.t1":`Vous êtes la Sentinelle`,"intro.next":`Suivant`,"intro.skip":`Passer`,"compass.label":`Objectif hors écran, {n, plural, one {# case} other {# cases}}`,"compass.cells":`{n, plural, one {# case} other {# cases}}`,"menu.play":`Jouer`,"menu.replayGuide":`Refaire le tutoriel`,"lab.noteHow":`{touch, select, yes {touchez} other {{pad, select, yes {appuyez sur {pad_confirm}} other {cliquez}}}} — on vous montre comment l’obtenir`,"guide.place-grinder.why":`Le polissoir taille des lentilles dans le quartz. Tout ce que nous bâtirons aura besoin de lentilles.`,"guide.place-grabIn.why":`La pince prend sur le gravitapis et nourrit le polissoir. Un bras, mais sans coude.`,"tools.more":`Plus`,"tools.hideHud":`Masquer l’interface`,"hud.show":`Afficher l’interface`,"place.title":`Confirmer la pose`,"place.cancel":`Annuler`,"place.build":`Poser`,"place.remove":`Démolir`,"place.copy":`Copier`,"stick.hide":`Masquer le joystick`,"stick.show":`Afficher le joystick`,"stick.flip":`Joystick de l’autre côté`,"settings.stickSide":`Joystick de la Sentinelle`,"settings.stickSide.left":`À gauche`,"settings.stickSide.right":`À droite`,"settings.stickSide.off":`Masqué`,"settings.confirmPlace":`Pose en deux touchers`,"settings.confirmPlace.hint":`Un toucher montre un fantôme et le bouton « Poser » le confirme : votre doigt ne cache jamais l’endroit. Désactivez pour construire immédiatement.`,"settings.bigButtons":`Grands boutons`,"shell.worlds":`Mondes`,"shell.stars":`Constellation`,"shell.about":`À propos`,"shell.exit":`Quitter`,"shell.exit.title":`Quitter le jeu ?`,"shell.exit.text":`Votre monde est sauvegardé — vous reprendrez exactement là où vous en étiez.`,"shell.cancel":`Annuler`,"shell.playWorld":`Jouer : {name}`,"shell.rename":`Renommer`,"shell.delete":`Supprimer`,"shell.delete.title":`Supprimer le monde ?`,"shell.delete.text":`« {name} » et toutes ses sauvegardes disparaîtront pour de bon.`,"shell.deleted":`Monde supprimé`,"shell.timeH":`{h} h {m} min`,"shell.timeM":`{m} min`,"shell.loading":`Le monde s’éveille…`,"shell.loadFailed":`Impossible d’ouvrir la sauvegarde — le monde a été recommencé`,"shell.create.title":`Nouveau monde`,"shell.create.name":`Nom du monde`,"shell.create.randomName":`Nom aléatoire`,"shell.create.advanced":`Avancé`,"shell.create.tutorial":`Tutoriel pas à pas`,"shell.create.go":`Créer le monde`,"pause.title":`Menu`,"pause.resume":`Reprendre`,"pause.save":`Sauvegarder`,"pause.toTitle":`Au menu principal`,"world.name":`{a} sur {b}`,"world.a.0":`Vallée`,"world.a.1":`Rivage`,"world.a.2":`Confins`,"world.a.3":`Havre`,"world.a.4":`Demeure`,"world.a.5":`Dôme`,"world.a.6":`Ceinture`,"world.a.7":`Jardin`,"world.a.8":`Seuil`,"world.a.9":`Baie`,"world.b.0":`de l’Aube`,"world.b.1":`du Rayonnement`,"world.b.2":`des Reflets`,"world.b.3":`du Point du jour`,"world.b.4":`de Midi`,"world.b.5":`des Étincelles`,"world.b.6":`des Prismes`,"world.b.7":`de la Clarté`,"world.b.8":`du Spectre`,"world.b.9":`des Lueurs`,"tip.0":`Un prisme décompose la lumière blanche en couleurs — chaque couleur donne son propre spectre.`,"tip.1":`La caméra s’est égarée ? Le bouton viseur ou {pad, select, yes {{pad_recenter}} other {Espace}} la ramène à la Sentinelle.`,"tip.2":`Le Centre demande des spectres : chaque nouvelle classe ouvre le palier suivant de technologies.`,"tip.3":`L’Essaim ne surgit jamais par surprise : un bandeau avec minuteur et des anneaux autour du nid préviennent à l’avance.`,"tip.4":`La sphère de Dyson grandit par couches : fermez une enveloppe pour +{closed} % par arc ; besoin de plus de lumière ? Bâtissez l’enveloppe extérieure d’un grade supérieur.`,"tip.5":`Les ceintures tournent, les intérieures plus vite. Un harpon fixe exploite toute la ceinture — regardez-la s’éclaircir.`,"tip.6":`Les plans copient des zones entières — construisez une fois, posez partout.`,"tip.7":`Le mode Alt affiche le contenu des machines directement sur le terrain.`,"tip.8":`Une impasse ? L’objectif en haut suggère l’étape suivante, et la flèche montre où voler.`,"tip.9":`Les expériences sont de courts casse-têtes de lumière — les erreurs n’y coûtent rien.`,"tip.10":`Le monde se sauvegarde tout seul à intervalles réguliers, à la sortie et quand le jeu passe en arrière-plan.`,"tip.11":`Chaque étoile que vous allumez reste à jamais dans votre constellation.`,"boot.render":`Préparation de la toile…`,"boot.worlds":`Recherche de vos mondes…`,"boot.ready":`Prêt`,"about.idea":`Le jeu`,"about.idea.text":`Heliohold est une usine autour d’une étoile vivante. Bâtissez autour d’elle une sphère de Dyson, arc après arc, attrapez les roches des ceintures au harpon, fendez les comètes au faisceau, décomposez une lumière aux cinq propriétés et réunissez le spectre complet pour allumer une nouvelle étoile.`,"about.made":`Coulisses`,"about.made.text":`Les bâtiments, le vaisseau, les étoiles et l’Essaim sont rendus dans Blender et assemblés par des scripts ; les portraits des personnages ont été créés avec un modèle génératif, puis retravaillés par des scripts (éclairage, animation). Tout le son est synthétisé en temps réel : le jeu ne contient aucun fichier audio.`,"about.privacy":`Confidentialité`,"about.privacy.text":`Le jeu ne collecte et n’envoie aucune donnée. Les mondes et les réglages sont conservés uniquement sur votre appareil.`,"about.thanks":`Remerciements`,"about.thanks.text":`Aux testeurs des premières versions, pour leur honnête « je n’y comprends rien », qui a rendu le jeu plus clair.`,"gen.title":`Paramètres du monde`,"gen.preview":`Aperçu du système : étoile, ceintures, Centre, nid de l’Essaim`,"gen.preview.legend":`Centre au milieu · étoile avec couronne · cadres jaunes : première ligne · violet : nid de l’Essaim`,"gen.presets":`Préréglage du monde`,"gen.preset.classic":`Classique`,"gen.preset.plenty":`Abondance`,"gen.preset.scarce":`Pénurie`,"gen.preset.deep":`Espace lointain`,"gen.preset.custom":`Personnalisé`,"gen.preset.classic.desc":`L’équilibre voulu : ceintures normales, étoile brillante, l’Essaim en son temps.`,"gen.preset.plenty.desc":`Des ceintures riches et larges, plus de comètes, une étoile plus brillante, un Essaim plus calme, un kit généreux.`,"gen.preset.scarce.desc":`Des ceintures pauvres et étroites, des comètes rares, une étoile terne, un Essaim plus précoce. Chaque roche compte.`,"gen.preset.deep.desc":`Un système vaste : des ceintures éloignées les unes des autres mais plus riches, une étoile plus grosse. Il faudra voyager pour trouver la pierre.`,"gen.preset.custom.desc":`Vos propres valeurs : ouvrez les groupes ci-dessous. Le monde est toujours jouable jusqu’au bout : le générateur vérifie le départ.`,"gen.group.res":`Ceintures et comètes`,"gen.group.star":`Étoile`,"gen.group.dark":`Essaim`,"gen.group.kit":`Kit de départ`,"gen.knob.star_power":`Luminosité`,"gen.knob.dark_freq":`Fréquence des nids`,"gen.knob.dark_delay":`Sensibilité des nids`,"gen.kit.0":`Modeste`,"gen.kit.1":`Normal`,"gen.kit.2":`Généreux`,"gen.code":`Code du monde`,"gen.code.copy":`Copier le code du monde`,"gen.code.copied":`Code du monde copié — partagez-le`,"gen.code.bad":`Code non reconnu. Collez une chaîne du type PHW1-…`,"gen.reset":`Revenir au Classique`,"gen.hint.star_power":`Luminosité de l’étoile : une étoile terne donne moins à la sphère, et les enveloppes extérieures atteignent plus tôt leur plafond.`,"gen.hint.dark_freq":`Nombre de nids de l’Essaim ; le premier nid existe toujours, car le finale en a besoin.`,"gen.hint.dark_delay":`À partir de quel éblouissement les nids s’éveillent : ×2, deux fois plus de lumière ; ×0,5, la moitié suffit.`,"etude.crossed_filters.name":`Filtres croisés`,"etude.crossed_filters.task":`La lumière source est polarisée à 0°, le récepteur ne prend que le 90°. Une lame à 90° bloque tout, mais si l’on en glisse une autre entre les deux ? Livrez {n} ph (réglez l’angle dans la fenêtre du polariseur).`,"etude.phase_cancel.name":`Phase π`,"etude.phase_cancel.task":`Deux sources bleues en opposition de phase ; le récepteur ne prend que la phase π. Réunies telles quelles dans un interféromètre, elles s’annulent. Additionnez les deux flux et livrez {n, number} ph.`,"etude.light_gates.name":`Portes de lumière`,"etude.light_gates.task":`Les signaux A (rouge) et B (vert) clignotent. Le récepteur du haut ne compte la lumière blanche que sur « A et B », celui du bas sur « A ou B, mais pas les deux ». Une lumière longue au mauvais moment remet son compte à zéro. Livrez {n} ph avec des obturateurs (commandés par les côtés) et un interféromètre.`,"cfg.title.level_gate":`Mode du capteur de niveau`,"cfg.level_gate.0":`Ouvert tant que le voisin n’est pas plein (< {full} %)`,"cfg.level_gate.1":`Ouvert tant que le voisin n’est pas vide (> {empty} %)`,"goal.twin_cell":`Posez {n, plural, one {# cellule de lumière} other {# cellules de lumière}}`,"goal.twin_cell.why":`Les Jumeaux ont des nuits : {night} s sans étoiles.`,"goal.twin_cell.hint":`Ici, un jour dure {day} minutes : l’étoile ambrée brille {amber} s, la bleue {blue} s, puis viennent {night} s de nuit. La chronologie se trouve dans le panneau Jour, sous l’objectif. Une cellule de lumière stocke la lumière le jour et la rend la nuit : la lumière entre par l’arrière et sort par l’avant. Elle retient la première couleur reçue et n’en accepte aucune autre. Un lumiduc porte jusqu’à {flux} ph/s : une seule ligne alimente 5 fabricants.`,"goal.twin_cell.done":`Les cellules sont en place. Il reste à traverser la nuit.`,"goal.twin_night":`Gardez {n, plural, one {# fabricant} other {# fabricants}} allumé jusqu’à l’aube`,"goal.twin_night.why":`Une usine qui ne dort jamais.`,"goal.twin_night.hint":`Quand les deux étoiles se couchent, la lumière ne vit plus que dans les cellules. Le panneau Jour indique combien de secondes tiendra la réserve de chaque couleur ; l’objectif compte si les machines sont encore allumées à la fin de la nuit.`,"goal.twin_night.done":`La nuit est passée — l’usine a brillé sans étoiles.`,"toast.dusk":`Nuit : les deux étoiles sont couchées pour {night} s, la lumière n’est plus que dans les cellules`,"toast.dawn":`Aube : l’étoile ambrée s’est levée`,"lab.filter":`Filtre de l’arbre`,"lab.filter.open":`Disponibles · {n}`,"lab.filter.all":`Toutes · {n}`,"lab.filter.done":`Recherchées · {n}`,"lab.filter.empty":`Rien ici — choisissez un autre filtre ou une autre branche.`,"lab.branch":`Branche de l’arbre`,"tech.level":`niv. {n}`,"tech.time":`{s} s l’unité`,"branch.any":`Toutes les branches`,"branch.mining":`Extraction`,"branch.logistics":`Logistique`,"branch.light":`Lumière`,"branch.matter":`Matière`,"branch.resonance":`Résonance`,"branch.logic":`Logique`,"branch.defense":`Défense`,"branch.stars":`Étoiles`,"branch.finale":`Finale`,"bonus.grabber":`+{v} % de vitesse des pinces`,"bonus.research":`+{v} % de vitesse du Centre`,"bonus.hand":`+{v} % de travail manuel`,"bonus.spear":`+{v} % de rechargement des lances`,"bonus.glare":`−{v} % d’éblouissement`,"bonus.drone":`+{v} % de vitesse et de fret des drones`,"bonus.cool":`+{v} % de refroidissement des radiateurs`,"bonus.forge":`+{v} % de vitesse de la Forge`,"bonus.speed":`+{v} % de vitesse des machines`,"bonus.attenuation":`lumiducs : −1 d’intensité toutes les {n} cases`,"bonus.tunnel":`plis jusqu’à {n} cases`,"bonus.swift":`drones rapides`,"bonus.perLevel":`{one} par niveau · total {total} %`,"lock.goto":`Voir dans le Centre`,"goal.research":`Fabriquez {n, plural, one {# Reflet} other {# Reflets}} et recherchez le Prisme`,"goal.research.hint":`Le Centre a besoin de lumière\xA0: un lumiduc depuis la ligne vers n’importe lequel de ses côtés. Un polissoir à part avec la recette «\xA0Reflet\xA0» (quartz + plaque)\xA0: «\xA0Poser\xA0» quartz et plaques dans sa fenêtre, «\xA0Prendre\xA0» le résultat. Dans la fenêtre «\xA0Recherches\xA0», au Centre — «\xA0Remettre ici\xA0»\xA0; Prisme — «\xA0Ajouter\xA0». Ne touchez pas à la ligne de lentilles. Plus tard, une ligne vous libère les mains\xA0: une pince du polissoir à Reflets directement dans le Centre.`,"goal.research.why":`Aucun plan de portail dans les archives. Le Centre lit la lumière, et les archives s’ouvrent pas à pas.`,"goal.research.done":`Le Centre a lu son premier Reflet. Prisme débloqué : les archives des « Semailles » commencent à s’ouvrir.`,"bp.locked":`Bâtiments verrouillés : {n} — le collage les ignorera`,"tree.title":`Arbre des technologies`,"tree.count":`{n} sur {all} recherchées`,"tree.fit":`Voir tout l’arbre`,"tree.queue":`File du Centre`,"tree.path":`Rechercher le chemin · {n}`,"tree.open":`Arbre entier`,"lock.gotoTree":`Voir dans l’arbre`,"key.tree":`Arbre des technologies`,"tree.filter.all":`Toutes`,"tree.filter.open":`Disponibles`,"tree.filter.done":`Recherchées`,"tree.search":`Chercher une technologie`,"tree.mini":`Mini-carte : touchez pour y aller`,"guide.tree":`Appuyez sur « Arbre entier » : la carte de toutes les découvertes, du Prisme jusqu’au finale.`,"guide.tree.reopen":`Rouvrez le Centre : le bouton « Arbre entier » s’y trouve.`,"tree.queueFull":`{now} partent en file maintenant, les {n} autres suivront à mesure que les recherches se terminent.`,"tree.goal":`But du chemin : le Centre remplit sa file tout seul.`,"tree.gate":`Palier {spectrum} — débloqué par « {tech} »`,"tree.next":`Étape suivante :`,"tree.band":`palier · {stage}`,"settings.uiScale.capped":`Cet écran utilise {n} % — plus grand ne tient pas.`,"status.23":`Mauvaise ceinture`,"status.23.hint":`Un harpon prend la roche (quartz, obsidienne), un chalut prend la poussière (givre, glace, antilumière). Utilisez l’autre récolteur.`,"status.24":`Ceinture qui s’épuise`,"status.24.hint":`Il reste moins d’un quart de la ceinture. Il est temps de bâtir à la ceinture suivante, plus riche.`,"status.25":`Ceinture épuisée`,"status.25.hint":`Plus de roche : déplacez le récolteur vers une autre ceinture.`,"machine.belt":`Reste de la ceinture : {n} %`,"machine.noBelt":`Aucune ceinture à portée`,"cfg.role.3":`Collecte`,"shield.label":`Bouclier`,"shield.aria":`Bouclier de la Sentinelle : {n} %`,"toast.heatWarm":`Chaleur : le bouclier ne se régénère pas ici. Plus près de la couronne, il subit des dégâts.`,"toast.heatLow":`Bouclier faible — éloignez-vous de l’étoile !`,"toast.heatEject":`Le vent stellaire a rejeté la Sentinelle en arrière. Rien n’a été perdu.`,"goal.harpoon":`Posez {n, plural, one {# harpon} other {# harpons}} près des roches bleues`,"goal.harpoon.hint":`Barre de construction → harpon → l’emplacement au repère, tout contre la ceinture. Le point lumineux et la goulotte sont la sortie ; « Pivoter » ({pad, select, yes {{pad_rotate}} other {R}}) l’oriente vers le gravitapis. {n, plural, one {# harpon suffit} other {# harpons suffisent}} pour un polissoir.`,"goal.harpoon.why":`On ne charrie pas la pierre à la main : les dormeurs ont besoin de lumière en heures, pas en semaines.`,"goal.harpoon.done":`Harpons tirés. La pierre viendra d’elle-même : vos mains sont libres, et mes calculs aussi.`,"goal.colors":`Décomposez la lumière en couleurs`,"goal.colors.hint":`Prisme : blanc à l’arrière → rouge devant, émeraude à gauche, azur à droite. Posez des lentilles sur un banc optique sous une lumière colorée.`,"goal.colors.why":`La lumière blanche contient toutes les couleurs. Décomposons-la, et les archives dévoileront la voie vers un portail.`,"goal.colors.done":`La lumière est décomposée en couleurs : le Centre peut les lire.`,"goal.ice":`Récupérez {n} × glace sur les météorites`,"goal.ice.why":`Les capsules ont besoin de froid, et ici, le froid, c’est la glace. Elle vient de l’espace : des météorites glacées et des comètes traversent le système.`,"goal.ice.hint":`Les météorites sont des roches brillantes qui traversent le système ; la flèche indique la plus proche qui se dirige vers votre base. {touch, select, yes {Touchez-la} other {{pad, select, yes {Visez-la et appuyez sur {pad_confirm}} other {Cliquez dessus}}}} : la vedette arrive et son faisceau fend la roche. Traversez les éclats : la glace se ramasse toute seule. Plus tard, une lance sur lumière focalisée fendra les météorites à votre place.`,"goal.ice.done":`De la glace dans la soute. Plus tard, les lances et les drones l’attraperont pour vous.`,"goal.deep_signal":`Envoyez le Signal profond`,"goal.deep_signal.why":`L’étoile a clignoté deux secondes après le premier spectre. Coïncidence ? Le Signal profond décomposera sa lumière jusqu’aux raies les plus ténues.`,"goal.deep_signal.hint":`Signal profond : chaque unité de son coût est un spectre M, K et G (le décompte est dans la fenêtre du Centre). K est le plus lent : ajoutez un second assembleur K.`,"goal.deep_signal.done":`Le signal est parti ! Le Centre brûle de trois anneaux.`,"goal.awakening":`Recherchez la « Fibre longue » — un lien avec le Havre`,"goal.awakening.why":`La Fibre longue perce un lien à travers l’Envers : pour la première fois, un canal dégagé vers le Havre. Et une route vers d’autres étoiles.`,"goal.awakening.hint":`Il faut les six spectres : le chemin vers la Fibre longue passe par toutes les classes, et elle-même coûte des spectres F, A et B. Ensuite, les lumiducs faiblissent moins souvent.`,"goal.awakening.done":`La fibre est tirée : le Havre captera l’« Hirondelle ». D’autres étoiles attendent.`,"goal.ridge_awakening":`L’anneau de la Crête est ouvert`,"goal.ridge_awakening.why":`Un anneau ouvert tient la route dans les deux sens — et porte le motif du jardin de la Crête.`,"goal.ridge_awakening.hint":`Il s’ouvrira tout seul — par le consentement du jardin ou par la clé forcée.`,"goal.ridge_awakening.done":`L’anneau de la Crête est ouvert. En lui — le motif de naissance.`,"achv.deep_signal.name":`Signal profond`,"achv.deep_signal.desc":`Le spectrographe a trouvé dans la lumière de l’étoile des répétitions que les étoiles ne font pas.`,"landmark.ring.quartz_rock":`pierre pour les lentilles`,"landmark.ring.obsidian_rock":`pierre pour les plaques`,"landmark.ring.ice_haze":`glace fine — au chalut`,"landmark.ring.frost_dust":`givre — au chalut`,"gen.knob.belt_rich":`Réserves des ceintures`,"gen.knob.belt_width":`Largeur des ceintures`,"gen.knob.belt_spread":`Étendue du système`,"gen.knob.meteor_rate":`Météorites et comètes`,"gen.knob.star_size":`Taille de l’étoile`,"gen.hint.belt_rich":`Quantité de pierre que contient chaque ceinture : ×2 dure deux fois plus longtemps.`,"gen.hint.belt_spread":`Ceintures plus éloignées : de plus larges intervalles pour la base, des routes plus longues.`,"gen.hint.meteor_rate":`Fréquence des corps glacés qui traversent : plus de passages, plus de glace.`,"gen.hint.star_size":`Une étoile plus grosse est plus brillante et repousse les ceintures vers l’extérieur.`,"guide.place-harpoonA":`Posez un harpon dans le cadre, près de la ceinture. Le point brillant et la goulotte sont sa sortie : les roches y vont.`,"guide.place-harpoonA.rotate":`Tournez le harpon pour que sa sortie soit {o, select, 1 {à gauche} 2 {en haut} 3 {à droite} other {en bas}} : appuyez sur « Pivoter » ou sur {pad, select, yes {{pad_rotate}} other {R}} {n, plural, one {# fois de plus} other {# fois de plus}}.`,"guide.place-harpoonA.repick":`Prenez un harpon dans la barre de construction : il attrape tout seul les roches de la ceinture.`,"guide.place-harpoonA.why":`Ce harpon s’est détaché de la pince d’amarrage. Il attrape les roches tout seul : vos mains restent libres.`,"guide.place-harpoonB":`Le second harpon va dans le cadre voisin, sortie dans le même sens.`,"guide.place-harpoonB.rotate":`Tournez le harpon pour que sa sortie soit {o, select, 1 {à gauche} 2 {en haut} 3 {à droite} other {en bas}} : « Pivoter » ou {pad, select, yes {{pad_rotate}} other {R}} {n, plural, one {# fois de plus} other {# fois de plus}}.`,"guide.place-harpoonB.repick":`Prenez un autre harpon dans la barre des bâtiments.`,"shell.legacy":`{name} — monde d’une très ancienne version, non pris en charge`,"shell.legacy.note":`Monde d’une très ancienne version (avant les ceintures et les spectres) — non pris en charge. Vous pouvez le supprimer et en commencer un nouveau.`,"bonus.harvest":`+{v} % de vitesse des extracteurs`,"bonus.meteor":`+{v} % de météorites et comètes`,"hover.left":`Ceinture : il reste {n} % de la roche. La ceinture tourne : un harpon travaille toute la ceinture.`,"gen.code.legacy":`Ce code de monde vient d’une version plus ancienne et n’est pas pris en charge : le jeu compte désormais des ceintures et des spectres.`,"goal.far_belt":`Nouvelle ceinture : des harpons sur une troisième ceinture`,"goal.far_belt.why":`Une colonie, c’est des années, et la ceinture intérieure s’amenuise. Les ceintures lointaines sont plus riches : l’usine ne s’arrêtera pas quand la plus proche sera épuisée.`,"goal.far_belt.hint":`Rejoignez la ceinture rocheuse suivante, au-delà de celle d’obsidienne, et posez un harpon sur son bord : il compte dès qu’il commence à extraire. Les ceintures proches s’amenuisent ; plus tard, déplacez-vous : harpons et polissoir près de la ceinture lointaine, lentilles dans une réserve, puis un gravitapis jusqu’à la base. Le stock restant de la ceinture s’affiche dans l’infobulle du harpon.`,"goal.far_belt.done":`Trois ceintures en service : quand l’intérieure s’épuisera, l’usine ne s’arrêtera pas.`,"goal.fold":`Recherchez les plis et faites passer cargaison ou lumière sous un obstacle`,"goal.fold.why":`La base grandit et les lignes se heurtent. Un pli de l’espace fait passer cargaison et lumière sous un obstacle : {s1} cases au début, puis le Centre ouvre {s2}, {s3} et {s4}.`,"goal.fold.hint":`Recherchez « Plis » au Centre (spectre M). Pli : la première arche est l’entrée, la suivante sur la ligne est la sortie (posée automatiquement) ; un pli fait aussi passer la cargaison au-delà d’une ceinture d’astéroïdes. Le pli lumineux est une recherche à part : deux arches face à face. Un faisceau survole déjà gravitapis et ceintures, en perdant {loss} % par case au-dessus d’un gravitapis, mais ne traverse les machines que par un pli.`,"goal.fold.done":`La ligne a plongé et elle est ressortie ! Comme un point de couture. Je peux la dessiner dans mon carnet ?`,"guide.lay-tunnel":`Cliquez sur l’extrémité {o, select, 1 {haute} 2 {droite} 3 {basse} other {gauche}} du cadre et tirez le gravitapis {o, select, 1 {vers le bas} 2 {vers la gauche} 3 {vers le haut} other {vers la droite}} jusqu’au bout.`,"guide.lay-tunnel.repick":`Prenez un gravitapis dans la barre de construction : il transporte les roches.`,"guide.lay-tunnel.reverse":`Le gravitapis va dans le mauvais sens. Appuyez sur « Annuler » et retracez-le, depuis le bord du cadre, côté harpons.`,"guide.lay-tunnel.why":`Le gravitapis transportera tout seul les roches des harpons.`,"status.26":`Pas de rayon`,"status.26.hint":`Le faisceau de la sphère n’arrive pas : posez un arc sur l’enveloppe la plus proche (orbite en pointillés près de l’étoile) ou rapprochez le récepteur, à moins de {range} cases d’une orbite portant des arcs.`,"status.27":`Roches trop loin`,"status.27.hint":`La ceinture est épuisée à cet endroit et tourne lentement. Posez le récolteur ailleurs le long de la ceinture.`,"status.28":`Enveloppe achevée`,"status.28.hint":`Tous les emplacements de l’enveloppe de ce rang sont pris. Retirez les arcs restants avec « Prendre » et chargez des arcs du rang suivant, pour l’enveloppe extérieure.`,"guide.place-arc":`Tout ici vit de la lumière de l’étoile : les arcs la captent sur l’anneau en pointillés qui l’entoure. Prenez « Arc I » et posez-le sur les pointillés, dans le cadre.`,"guide.place-arc.repick":`Prenez « Arc I » dans la barre de construction, en bas.`,"guide.place-arc.why":`Un arc capte la lumière de l’étoile. Un seul donne {arc} ph/s. Quarante dormeurs, c’est beaucoup d’arcs. Commençons par un.`,"guide.place-receiver":`Posez la parabole, le récepteur, dans le cadre. L’arc lui enverra un faisceau.{touch, select, yes {} other {{pad, select, yes { {pad_place} pose, {pad_unhand} la remet.} other { Clic gauche pour poser, clic droit pour reposer.}}}}`,"guide.place-receiver.repick":`Prenez le récepteur dans la barre des bâtiments.`,"guide.place-receiver.why":`Le récepteur est la prise de la base. La lumière en part vers les machines.`,"goal.arc":`Lancez un arc sur l’anneau près de l’étoile`,"goal.arc.hint":`Barre des bâtiments en bas → « Arc I » → {touch, select, yes {touchez l’anneau en pointillés lumineux} other {{pad, select, yes {visez l’anneau en pointillés lumineux et appuyez sur {pad_confirm}} other {cliquez sur l’anneau en pointillés lumineux}}}} près de l’étoile (l’orbite des arcs). Inutile de vous approcher : la vedette lance un arc à {reach} cases.`,"goal.arc.why":`La réserve de secours fond. L’arc est la première lumière qui nourrit les dormeurs au lieu d’épuiser leur réserve.`,"goal.arc.done":`L’arc est dans le cadre. Cette étoile ne figure dans aucun catalogue, mais elle est généreuse en lumière. Je prends.`,"goal.catapult":`Catapulte : les arcs volent seuls`,"goal.catapult.hint":`Recherchez « Catapulte » au Centre (spectre M) et posez-la dans un intervalle. Les arcs entrent dans la catapulte elle-même (par une pince ou « Poser » dans sa fenêtre), la lumière par un lumiduc ; elle les tire vers les emplacements libres de l’enveloppe. Une pince longue passe par-dessus une case : le gravitapis n’a donc pas besoin de la toucher.`,"goal.catapult.why":`Les dormeurs et le futur portail ont besoin d’une sphère de centaines d’arcs. Impossible de l’assembler à la main : la catapulte lance les arcs toute seule.`,"goal.catapult.done":`Le premier arc est en vol : la sphère se bâtit toute seule.`,"goal.crown":`Fermez l’anneau d’arcs autour de l’étoile`,"goal.crown.hint":`L’enveloppe I près de la couronne compte {slots} emplacements. Une enveloppe fermée donne +{closed} % à chaque arc et s’embrase en un anneau entier. Toute la Couronne fait {total} ph/s : {rx, plural, one {# récepteur} many {# récepteurs} other {# récepteurs}} de {cap}.`,"goal.crown.why":`Un anneau d’arcs fermé, c’est la Couronne, la première enveloppe. Sa lumière suffit à faire passer les capsules des panneaux de secours à la lumière de la base.`,"goal.crown.done":`La Couronne est fermée ! Chaque arc brille de {closed} % de plus.`,"goal.shell2":`Enveloppe II : {n, plural, one {# arc} many {# arcs} other {# arcs}} de second palier`,"goal.shell2.hint":`Recherchez « Enveloppe II » (spectre K). L’Arc II s’assemble avec une lentille ambre, des lentilles et des plaques ; son orbite se trouve au bord extérieur de l’intervalle du Centre. Une enveloppe extérieure capte la lumière que laisse passer l’intérieure.`,"goal.shell2.why":`La Couronne manque de lumière pour les spectres K, et la liaison avec le Havre manque de puissance. Une nouvelle enveloppe autour de l’ancienne donnera l’un et l’autre.`,"goal.shell2.done":`La deuxième enveloppe grandit — la base a plus de lumière.`,"goal.captured":`Étoile dans la sphère : {pct} % de sa luminosité`,"goal.captured.hint":`Toutes les enveloppes ensemble prennent une part de la luminosité de l’étoile. Les enveloppes III et IV se trouvent près des ceintures lointaines ; une sphère complète prend {n} %.`,"goal.captured.why":`La part de la lumière du Berceau qui travaille déjà pour vous — et pour le futur portail. Le portail aura besoin de presque toute l’étoile.`,"goal.captured.done":`{pct} % de l’étoile est dans votre sphère.`,"hover.shell.name":`Enveloppe {n} de la sphère de Dyson`,"hover.shell.arcs":`Arcs {built} sur {n} · {flux} ph/s chacun`,"hover.shell.star":`Étoile dans la sphère : {p} %`,"hover.shell.hint":`Lancez un Arc {n} sur l’orbite en pointillés ; une enveloppe fermée donne +{closed} % à chaque arc.`,"landmark.shell":`Enveloppe {n}`,"landmark.shell.sub":`{built} arcs sur {n}`,"achv.crown_closed.name":`La Couronne`,"achv.crown_closed.desc":`Fermez l’enveloppe I de la sphère de Dyson : un anneau de lumière autour de l’étoile.`,"achv.half_star.name":`Une demi-étoile`,"achv.half_star.desc":`La sphère capte la moitié de la luminosité de l’étoile.`,"achv.whole_star.name":`L’étoile entière`,"achv.whole_star.desc":`La sphère de Dyson prend {pct} % de la luminosité de l’étoile.`,"launcher.put":`Charger : {name}`,"hover.shell.got":`Les récepteurs prennent {got} des {power} ph/s de la sphère`,"hover.shell.lost":`Les récepteurs ne prennent que {got} sur {power} ph/s : ajoutez un récepteur ({cap} ph/s)`,"lab.sphere":`Étoile dans la sphère : {p} % · {arcs} arcs`,"goal.more":`Comment faire ?`,"goal.less":`Replier`,"goal.part.research":`Recherchez « {name} » au Centre`,"goal.part.deliver":`Livrez au Centre : {name}`,"goal.part.auto":`Produisez avec des machines : {name}`,"goal.part.make":`Récoltez : {name}`,"goal.part.build":`Posez : {name}`,"goal.beam.part":`Un rayon atteint un port récepteur`,"goal.resonance.part":`Harpons en résonance`,"goal.fold.part":`Du fret ou de la lumière passe par un pli`,"goal.shell2.part":`Arcs sur l’enveloppe II`,"goal.liquid.part":`Lumière liquide produite, en unités`,"goal.cooling.part":`Récepteurs près de l’étoile sans surchauffe`,"goal.drone.part":`Premier trajet d’un drone`,"goal.logic.part":`Basculements de l’obturateur`,"goal.spear.part":`Lance chargée`,"compass.fly":`Aller à l’objectif`,"place.why.busy":`Occupé`,"place.why.belt":`Ceinture — construction impossible`,"place.why.orbit":`Orbite de la sphère — arcs seulement`,"place.why.corona":`Couronne de l’étoile`,"place.why.far":`Trop loin — {touch, select, yes {touchez} other {{pad, select, yes {appuyez sur {pad_confirm}} other {cliquez}}}} encore`,"place.why.items":`Absent de l’inventaire`,"place.why.slot":`Un arc se pose seulement sur les pointillés d’une enveloppe`,"place.why.grade":`Mauvaise enveloppe — il faut un arc d’un autre rang`,"hint.lab.5":`Choisissez une technologie dans la fenêtre du Centre ou dans l’arbre : le Centre ne démarre pas tout seul.`,"machine.putAll":`Tout poser : {item}`,"status.lowLight":`Peu de lumière`,"status.lowLight.hint":`Tourne plus lentement que la recette : il arrive moins de lumière qu’un cycle n’en demande. Ajoutez des arcs et des récepteurs, ou mettez moins de machines sur ce lumiduc.`,"machine.inflow":`Apport {n} ph/s → cycle {s} s`,"machine.noInflow":`Apport 0 ph/s — aucune lumière n’arrive`,"status.7.dry":`Aucune lumière n’arrive : tirez un lumiduc jusqu’à la machine, depuis un récepteur de faisceau ou une sortie de prisme. La lumière ne passe pas entre des machines qui se touchent. Si un lumiduc est là, son réseau n’a pas de source ou d’autres machines prennent toute la lumière : le plus souvent, un prisme aux sorties libres.`,"status.prism.3":`Consommateurs pleins — la lumière attend`,"status.mixer.3":`Nulle part où envoyer la lumière`,"hint.mixer.3":`Reliez un lumiduc à la sortie (un seul lumiduc alimente plusieurs machines) ou collez l’entrée d’une machine contre la sortie.`,"status.focuser.3":`Nulle part où envoyer la lumière`,"hint.focuser.3":`Reliez un lumiduc à la sortie (un seul lumiduc alimente plusieurs machines) ou collez l’entrée d’une machine contre la sortie.`,"status.receiver.3":`Nulle part où envoyer la lumière`,"hint.receiver.3":`Reliez un lumiduc à la sortie (un seul lumiduc alimente plusieurs machines) ou collez l’entrée d’une machine contre la sortie.`,"status.modulator.3":`Nulle part où envoyer la lumière`,"hint.modulator.3":`Reliez un lumiduc à la sortie (un seul lumiduc alimente plusieurs machines) ou collez l’entrée d’une machine contre la sortie.`,"status.polarizer.3":`Nulle part où envoyer la lumière`,"hint.polarizer.3":`Reliez un lumiduc à la sortie (un seul lumiduc alimente plusieurs machines) ou collez l’entrée d’une machine contre la sortie.`,"status.phaser.3":`Nulle part où envoyer la lumière`,"hint.phaser.3":`Reliez un lumiduc à la sortie (un seul lumiduc alimente plusieurs machines) ou collez l’entrée d’une machine contre la sortie.`,"status.interferometer.3":`Nulle part où envoyer la lumière`,"hint.interferometer.3":`Reliez un lumiduc à la sortie (un seul lumiduc alimente plusieurs machines) ou collez l’entrée d’une machine contre la sortie.`,"status.light_cell.3":`Nulle part où envoyer la lumière`,"hint.light_cell.3":`Reliez un lumiduc à la sortie (un seul lumiduc alimente plusieurs machines) ou collez l’entrée d’une machine contre la sortie.`,"status.port.3":`Nulle part où envoyer la lumière`,"hint.port.3":`Reliez un lumiduc à la sortie (un seul lumiduc alimente plusieurs machines) ou collez l’entrée d’une machine contre la sortie.`,"hud.glareFrom":`{name} — {v} ph/s`,"lab.choose":`Choisissez une technologie`,"machine.inflowOnly":`Apport {n} ph/s`,"machine.bufferFull":`Tampon de lumière plein — en attente d’entrée`,"inv.toHand":`En main — poser`,"toast.firstCrack":`Météorite fendue ! Traversez les éclats : la glace se ramasse toute seule (ou {touch, select, yes {touchez un éclat} other {{pad, select, yes {visez un éclat et appuyez sur {pad_confirm}} other {cliquez sur un éclat}}}}).`,"machine.spearMeteor":`Pas d’Essaim à proximité : fend les météorites à moins de {r} cases (toutes les {every} s). Fendues dans cette partie : {n}`,"card.fromBelt":`Ceinture d’astéroïdes : le rayon de la vedette ({touch, select, yes {touchez un rocher} other {{pad, select, yes {visez un rocher et {pad_confirm}} other {cliquez sur un rocher}}}}) ou un harpon près de la bande de la ceinture.`,"card.fromTrawl":`Ceinture fine : un chalut près de la bande de la ceinture.`,"place.why.planet":`Orbite d’une planète — elle passera ici`,"status.29":`Planète trop loin`,"status.29.hint":`La planète est hors de la fenêtre de l’accélérateur de masse : attendez qu’elle se rapproche ou utilisez des navettes. La fenêtre est l’arc éclairé de l’orbite.`,"status.30":`Pas de station`,"status.30.hint":`Posez d’abord une station orbitale sur la planète : lancez-la avec la Sentinelle ou depuis un pas de tir.`,"status.31":`Planète pleine`,"status.31.hint":`Tous les emplacements de la planète sont pris (ou la station et l’accélérateur y sont déjà). Choisissez une autre planète.`,"status.32":`Choisissez une planète`,"status.32.hint":`Choisissez une planète explorée dans la fenêtre de la machine. Un observatoire ou un survol de la Sentinelle explore les nouvelles.`,"status.33":`Mauvaise planète`,"status.33.hint":`Les foreuses-sondes se posent sur les planètes solides, les siphons sur celles à atmosphère ; l’accélérateur de masse ne se pose que par fusée.`,"status.34":`Pas d’accélérateur`,"status.34.hint":`Lancez un accélérateur de masse vers la planète depuis un pas de tir.`,"bonus.planet":`+{v} % de cadence des foreuses-sondes et siphons`,"bonus.shuttle":`+{v} % de vitesse et de fret des navettes`,"bonus.driver":`+{v} % de fenêtre de l’accélérateur`,"branch.planets":`Planètes`,"planets.title":`Planètes`,"planets.empty":`Cette étoile n’a pas de planètes.`,"planet.unknown":`Inexplorée`,"planet.hours":`{h} h {m} min`,"planet.min":`{n} min`,"planet.cells":`{n, plural, one {# case} other {# cases}}`,"planet.orbit":`Orbite`,"planet.orbitVal":`{r} cases · {time} par orbite`,"planet.dist":`Vers la Sentinelle`,"planet.atmo":`Atmosphère`,"planet.atmo.thick":`dense`,"planet.atmo.thin":`ténue`,"planet.atmo.trace":`traces`,"planet.none":`néant`,"planet.rings":`Anneaux`,"planet.ring.ice":`glacés`,"planet.ring.rock":`rocheux`,"planet.moons":`Lunes`,"planet.stock":`Réserve`,"planet.kind.lava":`Monde de lave`,"planet.kind.rocky":`Monde rocheux`,"planet.kind.desert":`Monde désertique`,"planet.kind.crystal":`Monde cristallin`,"planet.kind.ocean":`Monde océanique`,"planet.kind.cloud":`Monde nuageux`,"planet.kind.ice":`Monde glacé`,"planet.kind.ice_giant":`Géante de glace`,"planet.kind.gas_giant":`Géante gazeuse`,"planet.special.tidal":`déchirée par les marées`,"planet.special.aurora":`aurores`,"planet.unsurveyed":`Inexplorée : approchez-vous à moins de {survey} cases ou construisez un observatoire.`,"planet.slots":`Emplacements`,"planet.slotFree":`libre`,"planet.mod.1":`Station orbitale`,"planet.mod.2":`Foreuse-sonde`,"planet.mod.3":`Siphon atmosphérique`,"planet.mod.4":`Accélérateur de masse`,"planet.store":`Entrepôt de la station`,"planet.needStation":`Sans station, les modules ne marchent pas — lancez-la en premier.`,"planet.window":`Fenêtre de l’accélérateur dans {time}`,"planet.fly":`Y aller`,"planet.here":`Ici`,"planet.take":`Prendre {n}`,"planet.throw.hint":`La Sentinelle lance un module depuis {reach} cases du bord de la planète`,"planet.throw.station":`Station`,"planet.throw.lander":`Foreuse`,"planet.throw.siphon":`Siphon`,"planet.why.far":`Approchez — à {reach} cases du bord`,"planet.why.none":`Absent de l’inventaire — fabriquez-le`,"planet.why.locked":`Recherchez d’abord la technologie`,"planet.why.full":`Tous les emplacements de la planète sont pris`,"planet.why.station":`Une station est déjà là`,"planet.why.noStation":`D’abord la station`,"planet.why.wrong":`Pas pour cette planète`,"planet.how.tektite":`Tectite : une station plus des foreuses-sondes. Transportez-la par navette ou attrapez-la avec un accélérateur de masse.`,"planet.how.neon":`Néon : une station plus des siphons. Transportez-le par navette ou attrapez-le avec un accélérateur de masse.`,"planet.how.ice":`Glace : une station plus des foreuses-sondes, un approvisionnement en glace pour une mégabase.`,"cfg.title.launch_pad":`Planète cible`,"cfg.title.shuttle_port":`Destination des navettes`,"cfg.title.catcher":`Planète de l’accélérateur`,"cfg.title.neon_emitter":`Couleur de la lumière`,"cfg.neon_emitter.0":`Rouge`,"cfg.neon_emitter.1":`Émeraude`,"cfg.neon_emitter.2":`Azur`,"cfg.planetAuto":`Auto`,"cfg.planetNone":`Aucune`,"shuttle.home":`Navettes au port : {n} · en vol : {f}`,"shuttle.put":`Poser des navettes`,"observatory.target":`Exploration : {name} — {n} %`,"observatory.done":`Toutes les planètes explorées`,"goal.planet_seen":`Explorez une planète`,"goal.planet_seen.why":`Les dormeurs et les neuf mille de l’« Exode » ont besoin de terre, et le Berceau a ses propres mondes. Les planètes contiennent ce que les ceintures n’ont pas : tectite et néon.`,"goal.planet_seen.hint":`{touch, select, yes {Touchez la flèche} other {{pad, select, yes {Choisissez la flèche ({pad_hud}, puis {pad_confirm})} other {Cliquez sur la flèche}}}} : votre vedette file vers la planète la plus proche. À moins de {survey} cases, elle est explorée automatiquement ; ou construisez un observatoire.`,"goal.planet_seen.done":`Planète explorée : le type, la ressource et les emplacements figurent sur sa fiche.`,"goal.planet_seen.part":`Explorez une planète`,"goal.planet_landing":`Atterrissage : une station et une foreuse-sonde`,"goal.planet_landing.why":`Une station orbitale est le premier quai de la colonie près d’une terre vivante. La foreuse extrait la tectite vers son entrepôt.`,"goal.planet_landing.hint":`Fabriquez une station et une foreuse-sonde, rejoignez une planète solide (rocheuse, de lave, désertique, cristalline), {touch, select, yes {touchez-la} other {{pad, select, yes {visez-la et appuyez sur {pad_confirm}} other {cliquez dessus}}}} : « Station », puis « Foreuse ».`,"goal.planet_landing.done":`Premier atterrissage ! L’entrepôt de la station se remplit.`,"goal.planet_landing.part":`Posez une station`,"goal.planet_landing.part.2":`Posez une foreuse-sonde`,"goal.planet_tektite":`Verre de tectite : {n}`,"goal.planet_tektite.why":`Le verre de tectite, c’est l’optique des rangs supérieurs : tubes, navettes, collecteur. Sans lui, le portail reste hors d’atteinte.`,"goal.planet_tektite.hint":`Prenez la tectite à la station (Prendre, sur la fiche de la planète), rapportez-la chez vous et faites-la fondre dans un four à tectite sous lumière rouge.`,"goal.planet_tektite.done":`Du verre venu d’une planète ! La première chose qu’on fabrique avec de la vraie terre. Au Havre, la terre n’existe qu’en images.`,"goal.planet_shuttle":`Premier trajet d’une navette`,"goal.planet_shuttle.why":`Les navettes acheminent d’elles-mêmes la cargaison des stations planétaires jusqu’à votre base : fini les voyages à la main.`,"goal.planet_shuttle.hint":`Construisez un port de navettes, amenez-y de la lumière ({charge} ph par lancement), placez-y des navettes et choisissez une planète ou Auto. La cargaison atterrit dans les emplacements du port : prenez-la avec des pinces.`,"goal.planet_shuttle.done":`La navette est revenue avec du fret.`,"goal.planet_shuttle.part":`Une navette a livré du fret`,"goal.planet_neon":`Néon : un siphon et {n} u de néon liquide`,"goal.planet_neon.why":`Le néon est de la lumière sans étoile. Il servira là où l’étoile ne peut rien — et pour les tubes du spectre O, la dernière clé du portail.`,"goal.planet_neon.hint":`Posez une station et un siphon sur une planète à atmosphère (géante, nuageuse, océanique). Le néon et la glace vont dans un condenseur à néon sous lumière bleue.`,"goal.planet_neon.done":`Le néon brille tout seul, sans étoile ! Comme si quelqu’un avait laissé une lumière allumée pour la nuit — pour nous.`,"goal.planet_neon.part":`Posez un siphon`,"goal.planet_neon.part.2":`Produisez {n} u de néon liquide`,"goal.planet_light":`Votre propre lumière : un émetteur à néon`,"goal.planet_light.why":`{flux} ph/s de n’importe quelle couleur primaire sans étoile — là où sa lumière n’arrive pas.`,"goal.planet_light.hint":`Construisez un émetteur à néon, amenez-y du néon liquide et choisissez une couleur ; tirez un lumiduc depuis sa face avant.`,"goal.planet_light.done":`L’émetteur brille.`,"goal.planet_light.part":`L’émetteur brille`,"planet.windowOpen":`La planète est dans la fenêtre de l’accélérateur de masse : les capsules volent`,"planet.sec":`{n} s`,"guide.doneTitle":`C’est fait !`,"guide.next":`Suivant`,"guide.min":`Replier l’aide`,"guide.restore":`Tutoriel {n}/{total} — afficher`,"guide.intro":`La lumière de l’étoile est gratuite ici. Les machines qui la captent sont faites de pierre. Commençons par la pierre.`,"guide.fly.done":`Nous y voilà. Les roches bleues sont du quartz. Tout commence par lui.`,"guide.mine.done":`Du quartz dans la soute : {n}. Gardez-le, il vous servira pour les gravitapis.`,"guide.place-arc.done":`La lumière coule : {arc} ph/s. L’arc a capté sa première part de l’étoile.`,"guide.place-receiver.done":`Le rayon est arrivé : {arc} ph/s dans le récepteur.`,"guide.place-grinder.done":`Il est posé. Mais éteint : ni recette ni lumière.`,"guide.recipe.done":`Ordre signé. Il n’y a plus qu’à fournir la lumière, et ça tourne.`,"guide.lay-lights.touch":`Tirez la veine : prenez un lumiduc et faites glisser le doigt le long du cadre, du récepteur au polissoir.`,"guide.lay-lights.why":`Un lumiduc est un fil pour la lumière. Sans lumière, les machines restent à l’arrêt, et les dormeurs attendent.`,"guide.lay-lights.stuck":`Pas allumé ? Le lumiduc doit toucher à la fois la parabole et le polissoir : remplissez tout le cadre.`,"guide.lay-lights.done":`Le polissoir s’allume ! Il ne manque plus que du quartz.`,"guide.place-harpoonA.done":`Feu ! Le câble tient une roche. Bonne pêche, commandant.`,"guide.place-harpoonB.why":`Un seul harpon ne peut pas alimenter un polissoir. Un second, c’est exactement ce qu’il faut.`,"guide.place-harpoonB.done":`Le second harpon est en place — le polissoir aura assez de pierre.`,"guide.lay-tunnel.stuck":`Plus de gravitapis ? Fabriquez-en dans l’« Inventaire ». Tracez d’un bout du cadre à l’autre.`,"guide.lay-tunnel.done":`Le quartz est parti. Joli flux.`,"guide.place-grabIn.done":`Du quartz dans le polissoir — il taille !`,"guide.place-grabOut.done":`La pince attend un endroit où déposer la lentille.`,"guide.place-storage.done":`La ligne est construite : ceinture → gravitapis → polissoir → réserve. La première chaîne de ce système.`,"guide.first-lens.stuck":`Pas encore de lentille ? Appuyez sur le polissoir ou la pince avec une pastille : sa fenêtre dit ce qui manque.`,"guide.first-lens.done":`La première chose fabriquée dans ce système, par des machines, sans vos mains.`,"guide.research-pick":`Le Centre débloque de nouvelles machines grâce à la science. Trouvez « Prisme » et appuyez sur « Ajouter ».`,"guide.research-pick.reopen":`Rouvrez le Centre : choisissons la première recherche.`,"guide.research-pick.why":`Le Prisme sépare la lumière blanche de l’étoile en couleurs. Tout le reste commence par les couleurs.`,"guide.research-pick.done":`Le Prisme est en file. Le Centre a besoin de {n} Reflets — c’est le polissoir qui les fabrique ; l’objectif montrera comment.`,"goal.mark.resource":`EXTRAIRE ICI`,"goal.mark.harvest":`HARPON ICI`,"goal.mark.meteor":`{touch, select, yes {TOUCHEZ} other {{pad, select, yes {{pad_confirm}} other {CLIQUEZ}}}} POUR FENDRE`,"goal.mark.lab":`CENTRE`,"goal.mark.star":`ARCS SUR LES POINTILLÉS`,"goal.mark.protostar":`PROTOÉTOILE`,"goal.mark.ghost":`FANTÔME DE BÂTIMENT`,"goal.mark.node":`NID DE L’ESSAIM`,"goal.mark.farBelt":`NOUVELLE CEINTURE — HARPON ICI`,"goal.mark.forge":`FORGE STELLAIRE`,"goal.mark.planet":`PLANÈTE`,"goal.mine.mark":`{touch, select, yes {TOUCHEZ} other {{pad, select, yes {{pad_confirm}} other {CLIQUEZ}}}} POUR EXTRAIRE`,"goal.expand.mark":`POLISSOIR À PLAQUES ICI`,"goal.mark.lineGrinder":`POLISSOIR ICI`,"goal.obsidian.mark":`HARPON — SORTIE VERS LE POLISSOIR`,"goal.plates.mark":`ENCORE UN HARPON — VERS LE POLISSOIR`,"ship.title":`Vaisseau`,"ship.hull.1":`Flèche`,"ship.hull.2":`Guêpe`,"ship.hull.3":`Faucon`,"ship.fire.title":`Tir auto sur les menaces et météorites à portée d’arme`,"ship.fire.on":`Tir : auto`,"ship.fire.off":`Tir : coupé`,"ship.slots":`Emplacements du vaisseau`,"ship.empty":`vide`,"ship.filter":`Sur quoi tirer`,"ship.filter.auto":`Tout`,"ship.filter.big":`Gros seulement`,"ship.filter.tap":`Sélection`,"ship.ammo":`{name} : {n} en soute, {m} chargés`,"ship.none":`Aucun module adapté dans l’inventaire : fabriquez-en à la main ou dans un assembleur.`,"ship.unequip":`Retirer le module`,"ship.hint":`{touch, select, yes {Touchez un emplacement} other {{pad, select, yes {Sélectionnez à la croix un emplacement} other {Cliquez sur un emplacement}}}} ou un numéro sur le modèle pour poser ou remplacer un module.`,"ship.energy":`Énergie`,"ship.energy.short":`énergie insuffisante : les armes cesseront de tirer`,"ship.energy.aria":`Énergie du vaisseau {n} %`,"ship.overload":`surcharge`,"ship.stat.speed":`Vitesse`,"ship.stat.shield":`Bouclier`,"ship.stat.regen":`Recharge`,"ship.stat.output":`Production E/s`,"ship.stat.drain":`Conso E/s`,"ship.stat.battery":`Batterie`,"ship.stat.dps":`Dégâts/s`,"ship.stat.reach":`Portée d’extraction`,"ship.stat.collect":`Collecte d’éclats`,"hail.warn":`Grêle de roches dans {s} s · {n} roches`,"achv.ship_first_shot.name":`Premier tir`,"achv.ship_first_shot.desc":`Brisez un météorite ou une roche avec une arme du vaisseau.`,"achv.ship_mark_2.name":`Mk II`,"achv.ship_mark_2.desc":`Montez un module Mk II sur le vaisseau.`,"achv.ship_leviathan.name":`Vaisseau amiral`,"achv.ship_leviathan.desc":`Recherchez la coque « Zénith », le sommet de la gamme des vaisseaux.`,"achv.ship_hail_50.name":`Bouclier de pierre`,"achv.ship_hail_50.desc":`Abattez {n} roches de grêle avec les armes du vaisseau.`,"achv.ship_swarms_10.name":`Fléau de l’Essaim`,"achv.ship_swarms_10.desc":`Détruisez {n} aliens de l’Essaim.`,"ship.tasks":`Tâches du vaisseau`,"ship.task.module":`Montez une arme`,"ship.task.shot":`Brisez un météorite avec une arme`,"ship.task.ammo":`Un assembleur a produit {n} bandes de balles`,"ship.task.mark":`Un module Mk II`,"ship.task.hail":`Abattez {n} roches de grêle`,"guide.ship-open":`Ouvrez la fenêtre « Vaisseau » — elle contient les modules de votre vedette.`,"guide.ship-open.more":`La fenêtre « Vaisseau » est dans le menu « Plus ».`,"guide.ship-craft":`Fabriquez un laser à impulsions, plus puissant que celui d’origine : plaques, lentilles azur, résonateur.`,"guide.ship-craft.stuck":`Pas de lentilles azur ? Le banc optique les fabrique à partir de lentilles sous lumière azur.`,"guide.ship-weapon":`{touch, select, yes {Touchez l’emplacement} other {{pad, select, yes {Sélectionnez à la croix l’emplacement} other {Cliquez sur l’emplacement}}}} d’arme, le numéro 6, et posez le laser.`,"guide.ship-weapon.why":`L’arme tire toute seule, sur les météorites et sur tout ce qui rampe jusqu’ici.`,"guide.ship-weapon.reopen":`Rouvrez la fenêtre « Vaisseau ».`,"guide.ship-shot":`Le laser tire tout seul, sur les météorites et sur l’Essaim près du vaisseau. L’énergie est la jauge sous le bouclier.`,"guide.ship-shot.done":`Touché ! Traversez les fragments pour les ramasser. Le laser peut aussi attaquer un nid de l’Essaim, mais des gardiens le protègent.`,"flare.warn":`L’étoile entre en éruption : explosion dans {s} s, éloignez-vous de la couronne`,"flare.now":`Éruption stellaire ! La couronne est deux fois plus large pendant {s} s encore`,"swarm.title":`Essaim`,"swarm.calm":`Contemplation : pas d’Essaim dans ce monde.`,"swarm.gate":`L’Essaim est vivant dès la première minute. Les yeux d’un nid montrent s’il voit l’éblouissement de votre base.`,"swarm.evo":`Évolution {e} ‰`,"swarm.nests":`Nids proches : {n} (éveillés : {a})`,"swarm.cleared":`Nids nettoyés : {n}`,"swarm.hives":`Planètes sous ruche : {n} · libérées : {f}`,"swarm.repelled":`Vagues repoussées : {n} sur {m}`,"swarm.repaired":`Réparé : {n} pts · endommagé : {d}`,"swarm.wave.soon":`Vague dans {t} · {n} aliens`,"swarm.wave.now":`Vague à l’attaque · reste {n}`,"swarm.advice":`Carapace {c} : lances et faisceaux sur lumière de cette couleur frappent ×{match, number}, le blanc ×{white}, les autres ×{other, number}.`,"swarm.hue.r":`Rouge`,"swarm.hue.g":`Émeraude`,"swarm.hue.b":`Azur`,"swarm.showTarget":`Voir la cible`,"swarm.showNest":`Nid le plus proche`,"swarm.repairNext":`Réparer le plus proche ({n})`,"swarm.quiet":`Aucune vague. Un radar annonce la suivante plus tôt.`,"swarm.quietRadar":`Aucune vague — le radar veille.`,"swarm.hint":`L’éblouissement se répand depuis votre base ; les nids le voient, l’absorbent et en font grandir des troupes de raid. L’évolution croît avec l’éblouissement, les nouveaux paliers spectraux et les planètes libérées, pas avec le temps. Moins de fuites de lumière, moins de vagues ; placez tourelles et barrières près de vos machines les plus brillantes.`,"hud.swarm.incoming":`Vague {t} · {n}`,"hud.swarm.fight":`Essaim · reste {n}`,"hud.swarm.awake":`Essaim · {n} · {e} ‰`,"swarm.toast.woke":`Un nid de l’Essaim s’est réveillé : votre éblouissement l’a atteint. Supprimez l’éblouissement — et le nid se rendormira.`,"swarm.toast.wave":`L’Essaim approche : vague dans {t} s, {n} aliens. La flèche montre d’où ils viennent.`,"swarm.toast.go":`La vague a décollé !`,"swarm.toast.repelled":`Vague repoussée ! {k} abattus, {d} de dégâts à la base.`,"swarm.toast.left":`La vague est repartie, {d} de dégâts à la base. Réparez ce qui est cassé.`,"swarm.toast.nest":`Nid nettoyé : la reine est morte, une protoétoile s’allume. +{chitin} de chitine.`,"machine.hp":`Intégrité {n} / {m}`,"machine.wreck":`Épave : hors service. Réparez-la ou démolissez-la (vous récupérez la machine).`,"machine.repair":`Réparer`,"machine.ammo":`Munitions : {n} sur {m} tirs`,"machine.kits":`Stock de réparation : {n} sur {m} pts`,"machine.dome":`Bouclier : {n}`,"machine.def.turret":`Dégâts {dmg} · {rate} par s · portée {r} cases`,"machine.def.barrier":`Un alien sur le passage ronge la barrière, pas les machines derrière elle.`,"machine.def.dome":`Absorbe les coups sur les machines à moins de {r} cases, bouclier jusqu’à {cap}.`,"machine.def.radar":`Vagues repérées {warn} s plus tôt.`,"machine.def.decoy":`Attire une vague sur lui s’il est à moins de {reach} cases de la cible.`,"machine.def.bay":`Répare {heal} pts/s à moins de {r} cases, à partir de kits de réparation.`,"alien.spark.name":`Étincelle`,"alien.reaper.name":`Faucheur`,"alien.stinger.name":`Dard`,"alien.ram.name":`Bélier`,"status.35":`Endommagé`,"status.35.hint":`Intégrité sous la moitié : la machine crépite d’étincelles. Réparez-la : Réparer dans la fenêtre de la machine, ou un poste de réparation.`,"status.36":`Épave`,"status.36.hint":`L’Essaim a mis cette machine en épave. Réparez-la (plus vite avec des kits de réparation) ou démolissez-la : vous récupérez la machine.`,"status.37":`Plus de munitions`,"status.37.hint":`Alimentez les bandes de munitions (ou les kits de réparation pour un poste) avec une pince, un gravitapis ou à la main.`,"status.38":`Phase π requise`,"status.38.hint":`La lance de phase ne prend que la lumière de phase π : faites passer le faisceau par un déphaseur.`,"status.39":`Planète sous une ruche`,"status.39.hint":`L’Essaim tient cette planète : l’extraction est arrêtée. Libérez-la avec le vaisseau ou des tourelles orbitales.`,"achv.first_wave.name":`Première vague`,"achv.first_wave.desc":`Repoussez une vague de l’Essaim.`,"achv.repairman.name":`Remise en état`,"achv.repairman.desc":`Réparez {n, number} points d’intégrité.`,"achv.nest_breaker.name":`Brise-nids`,"achv.nest_breaker.desc":`Nettoyez {n} nids de l’Essaim.`,"achv.liberator.name":`Libération`,"achv.liberator.desc":`Libérez une planète d’une ruche de l’Essaim.`,"achv.fortress.name":`Forteresse`,"achv.fortress.desc":`Repoussez {n} vagues de l’Essaim.`,"swarm.tasks":`Tâches de défense`,"swarm.task.turret":`Posez une tourelle (lance ou gatling)`,"swarm.task.wave":`Repoussez une vague`,"swarm.task.repair":`Réparez {n} points d’intégrité`,"swarm.task.barrier":`Posez {n} barrières`,"swarm.task.bay":`Un poste de réparation`,"swarm.task.nest":`Nettoyez un nid`,"swarm.task.planet":`Libérez une planète d’une ruche`,"guide.swarm-hud":`Un nid de créatures locales a remarqué la lumière de la base et envoyé une escouade. La barre du haut indique combien et vers où. {touch, select, yes {Touchez-la} other {{pad, select, yes {Choisissez-la avec {pad_hud}, puis {pad_confirm}} other {Cliquez dessus}}}}.`,"guide.swarm-hud.why":`C’est vers la lumière la plus vive que le nid envoie ses escouades, mordre les bâtiments.`,"guide.swarm-turret":`Posez une tourelle près de la cible de la vague et donnez-lui de la lumière ou des munitions : par pince, gravitapis ou à la main.`,"guide.swarm-turret.why":`Une tourelle tire pendant que vous construisez. Faut-il chacune ? On en reparlera.`,"guide.swarm-turret.stuck":`Les tourelles sont sous « Défense ». Votre vaisseau peut aussi aider : ses armes tirent toutes seules.`,"guide.swarm-wave":`L’Essaim mord les bâtiments. Menez votre vedette jusqu’à eux : le laser tire tout seul ; les tourelles aident.`,"guide.swarm-wave.done":`La vague est partie. Le bilan est en haut.`,"guide.swarm-repair":`Les machines endommagées étincellent, les détruites sont des carcasses. Ouvrez une machine, appuyez sur « Réparer » : le rayon répare tout autour.`,"guide.swarm-repair.why":`Rien n’est perdu : une carcasse se répare jusqu’à redevenir une machine entière. Avec des kits de réparation, c’est quatre fois plus rapide.`,"goal.gate_core":`Posez le cœur du portail dans l’anneau ancien au-delà de la ceinture extérieure`,"goal.gate_core.why":`L’anneau sombre au-delà de la ceinture extérieure est un portail ancien. Le cœur se loge dans ses encoches — et l’anneau s’éveille.`,"goal.gate_core.hint":`Recherchez « Théorie des portails » (spectre B). Un assembleur fabrique le cœur ; il ne se pose que sur la plateforme des ruines — le repère indique l’endroit.`,"goal.gate_core.done":`Le cœur est en place — les encoches des ruines concordent.`,"goal.gate_core.part":`Posez le cœur sur la plateforme de l’anneau`,"goal.gate_core.mark":`CŒUR DU PORTAIL — ICI`,"goal.gate_ring":`Fermez l’anneau : {n, plural, one {# segment} other {# segments}} dans le cœur`,"goal.gate_ring.why":`Chaque segment est un pas vers le chemin du retour : l’anneau des Forgerons s’éveille segment par segment, visible à n’importe quel zoom.`,"goal.gate_ring.hint":`Un assembleur fabrique les segments : arcs III, résonateurs, spectres B et guides d’ondes du portail (deux lentilles azur, un résonateur et du verre de tectite sous une lumière blanche polarisée). Amenez-les au cœur avec une pince ou « Déposer des segments ». Une pince filtrante ne prend sur un gravitapis partagé que son propre objet.`,"goal.gate_ring.done":`L’anneau est fermé !`,"goal.gate_ring.part":`Segments dans le cœur`,"goal.gate_field":`Maintenez le champ : {n, plural, one {# stabilisateur} other {# stabilisateurs}} de propriétés différentes`,"goal.gate_field.why":`L’anneau ne s’ouvre que par consentement : le champ tient grâce à une lumière de toutes les propriétés à la fois — un examen de tout ce que vous avez appris de la langue des Jardiniers.`,"goal.gate_field.hint":`Recherchez « Stabilisation du champ ». Posez les stabilisateurs à {range} cases du cœur au plus ; dans leur fenêtre, choisissez une propriété : rouge, polarisation, rythme, phase π. Chacun a besoin de {flux} ph/s de cette lumière.`,"goal.gate_field.done":`Le champ tient !`,"goal.gate_field.part":`Propriétés allumées`,"goal.gate_charge":`Chargez {n, plural, one {# condensateur de champ} other {# condensateurs de champ}}`,"goal.gate_charge.why":`Le saut exige toute la lumière que capte la sphère. Au-delà de l’anneau, l’« Exode » attend — près d’une étoile mourante, à la ration de famine.`,"goal.gate_charge.hint":`Recherchez « Condensateurs de champ » (requiert « Enveloppe IV »). Posez-les près du cœur ; chacun a besoin de {flux, number} ph/s, en dessous de {low} ph/s ils ne se chargent pas. Pleins en {full} minutes.`,"goal.gate_charge.done":`Les condensateurs sont pleins à ras bord. Quarante ans, j’ai réparé ce qui s’éteignait. Pour la première fois, je charge ce qui va s’allumer.`,"goal.gate_charge.part":`Condensateurs pleins`,"goal.gate_key":`Insérez la clé : {each, plural, one {# spectre} other {# spectres}} de chaque classe`,"goal.gate_key.why":`La clé du portail, c’est un spectre de chaque classe, de M à O : tout ce que vous avez lu au Berceau, en un seul rayon. L’anneau la reconnaîtra et ouvrira le passage.`,"goal.gate_key.hint":`Apportez au cœur {each} spectres de chaque classe M, K, G, F, A, B et O : avec une pince ou « Déposer des spectres (inventaire) » dans la fenêtre du cœur. Une pince à piles porte une pile entière, et une pince lumineuse près d’un pylône va deux fois plus vite.`,"goal.gate_key.done":`La clé est entrée ! Grand-père, tu as vu ? L’anneau brille de toutes nos couleurs.`,"goal.gate_key.part":`Spectres de la clé`,"goal.gate_jump":`Activez le portail et sautez vers chez vous`,"goal.gate_jump.why":`Deux millions de personnes attendent près d’un Foyer pâlissant. Le portail leur ouvrira la route vers une étoile vivante — si les Jardiniers répondent « oui ».`,"goal.gate_jump.hint":`Dans la fenêtre du cœur — « Activer ». La montée en régime dure {spin} minutes : les stabilisateurs doivent rester allumés, et la base éblouira le ciel — préparez la défense.`,"goal.gate_jump.done":`Saut !`,"goal.gate_jump.part":`Saut`,"logbook.title":`Journal de bord`,"logbook.tab.story":`Histoire`,"logbook.tab.logs":`Journaux de Vera`,"logbook.tab.cast":`Personnages`,"logbook.none":`Ce monde n’a pas de campagne : l’histoire se joue dans un nouveau monde du Berceau.`,"logbook.empty":`Rien pour l’instant. Les scènes et les répliques apparaîtront ici — vous pourrez les revoir.`,"logbook.logs":`Journaux de Vera trouvés : {n} sur {total}. Les capsules brillent en bleu — approchez tout près.`,"logbook.found":`Entrée de Vera nº {n} trouvée — voir le « Journal de bord »`,"story.skip":`Passer`,"story.credits.minutes":`minutes au Berceau`,"story.credits.arcs":`arcs de la sphère`,"story.credits.logs":`entrées de Vera`,"story.credits.nests":`nids endormis`,"story.credits.thanks":`Merci d’avoir fait tout le voyage.`,"settings.story":`Histoire`,"settings.story.full":`Complète`,"settings.story.radio":`Radio seulement`,"settings.story.off":`Sans dialogues`,"gate.title":`Hyperportail`,"gate.segments":`Anneau : {n} sur {need} segments`,"gate.key":`Clé du spectre complet`,"gate.field":`Champ : {n} sur {total} propriétés`,"gate.charge":`Condensateurs : {n} pleins sur {total}`,"gate.prop.0":`Rouge`,"gate.prop.1":`Polarisation`,"gate.prop.2":`Rythme`,"gate.prop.3":`Phase π`,"gate.activate":`Activer`,"gate.notReady":`Il faut : l’anneau, la clé, {field} propriétés du champ et {charge} condensateurs pleins.`,"gate.spinning":`Montée en régime {p} % — gardez les stabilisateurs allumés !`,"gate.jumped":`Saut effectué. Le portail est ouvert.`,"gate.putKey":`Déposer des spectres (inventaire)`,"gate.putSegments":`Déposer des segments`,"gate.stab.prop":`Propriété de la lumière`,"gate.stab.range":`{yes, select, yes {Dans le champ du cœur — travaille pour le portail} other {Hors du champ du cœur : à plus de {range} cases de son centre — n’apporte rien au champ ni à la charge}}`,"gate.cap.fill":`Charge {p} %`,"cfg.title.gate_stabilizer":`Propriété de la lumière`,"cfg.gate_stabilizer.0":`Rouge`,"cfg.gate_stabilizer.1":`Polarisation`,"cfg.gate_stabilizer.2":`Rythme`,"cfg.gate_stabilizer.3":`Phase π`,"guide.ora":`ORA · IA DU VAISSEAU`,"goal.mark.gate":`HYPERPORTAIL`,"landmark.ruins":`L’ANNEAU DES FORGERONS`,"landmark.ruins.sub":`un portail ancien`,"landmark.gate":`HYPERPORTAIL`,"landmark.capsule":`CAPSULE`,"landmark.capsule.sub":`un vieux journal — approchez`,"scene.label":`Cinématique`,"story.log.title":`Entrée {n} · jour {day}`,"story.credits.sleepers":`Et aux dormeurs, qui ont tout dormi — y compris le plus intéressant.`,"logbook.tab.world":`Chronique`,"logbook.prologue":`Prologue`,"logbook.scene.prologue":`L’Envers`,"logbook.scene.hab":`Quarante lumières`,"logbook.scene.intruder":`La clandestine`,"logbook.scene.first_log":`Le journal de la capsule`,"logbook.scene.confess":`L’aveu`,"logbook.scene.chorus":`La traduction`,"logbook.scene.protostar":`Le premier nid`,"logbook.scene.refrain":`Le motif`,"logbook.scene.token":`La plaque`,"logbook.scene.channel":`Le canal`,"logbook.scene.report7":`Rapport sept`,"logbook.scene.core":`Le cœur`,"logbook.scene.matvey_nest":`Matveï au nid`,"logbook.scene.spin":`Montée en régime`,"logbook.scene.threshold":`Le seuil`,"settings.textSpeed":`Vitesse du texte`,"settings.textSpeed.slow":`Lente`,"settings.textSpeed.normal":`Normale`,"settings.textSpeed.fast":`Rapide`,"settings.textSpeed.instant":`Instantanée`,"chron.1.when":`−260 ans`,"chron.1":`Près du Foyer, on découvre le fragment d’un anneau ancien. On en tire les premiers Hyperportails et la première sphère. L’Âge lumineux commence.`,"chron.2.when":`−230 ans`,"chron.2":`Le Collier : des portails autour de trois cents étoiles. Premier contact avec l’Essaim — « des insectes qui rongent la sphère ».`,"chron.3.when":`−215 ans`,"chron.3":`L’Institut du Havre proclame la Campagne sanitaire. On brûle les nids ; au catalogue, les systèmes reçoivent la mention « claire ».`,"chron.4.when":`−212 ans`,"chron.4":`L’expédition « Première Lumière » découvre une étoile vivante inconnue — et disparaît.`,"chron.5.when":`−211 ans`,"chron.5":`Le rapport sept de Lund parvient à l’Institut. L’étoile est effacée du catalogue ; le rapport est classé secret.`,"chron.6.when":`−170 ans`,"chron.6":`Les premières étoiles pâlissent. Le mot « Extinction » apparaît ; l’Institut n’en nomme jamais la cause.`,"chron.7.when":`−120 ans`,"chron.7":`Le Collier se rompt : sans lumière, les portails s’éteignent, des centaines de colonies sont perdues.`,"chron.8.when":`−90 ans`,"chron.8":`Les derniers portails se ferment. Les gens se rassemblent autour du Foyer et bâtissent le Havre.`,"chron.9.when":`−45 ans`,"chron.9":`Dernier nettoyage sanitaire : le système de Claire. Dans l’équipe, un Matveï Rogov de vingt-trois ans.`,"chron.10.when":`−30 ans`,"chron.10":`La flotte de l’« Exode » — neuf mille personnes — part pour Claire. Mira Vent calcule la route.`,"chron.11.when":`−12 ans`,"chron.11":`Le programme « Ensemencement » : douze semeurs rapides envoyés vers des étoiles vivantes.`,"chron.12.when":`−1,5 an`,"chron.12":`L’« Hirondelle » part pour Claire. Dans la capsule 17 : Sonia Vent. Sa mère a décidé pour elle.`,"chron.13.when":`jour 547`,"chron.13":`L’Envers. ORA capte un signal sur une fréquence absente de tous les protocoles — et change de cap.`,"guide.lab-place":`J’ai sorti le plan du Centre des archives. Posez-le dans le cadre — il est dans la barre des bâtiments.`,"guide.lab-place.repick":`Prenez le Centre de recherche dans la barre des bâtiments.`,"guide.lab-place.why":`Le Centre lit la lumière de l’étoile et délivre de nouveaux plans. Posez-en autant que vous voulez, pourvu qu’il y ait de la lumière.`,"guide.lab-place.done":`Il est posé. Il lui faut de la lumière.`,"lab.count":`Centres : {n} · en lecture : {w}`,"lab.none":`Aucun Centre pour l’instant. Posez un Centre de recherche depuis la barre des bâtiments — sans lui, la science ne se lit pas.`,"swarm.rules":`L’Essaim vit dès la première minute. Les yeux d’un nid : sombres — il ne voit pas votre éblouissement, jaunes — il voit la base, rouges — il est éveillé. Les éclaireurs arrivent d’abord et ne mordent pas ; les vagues suivent. Les épines autour d’un nid marquent sa frontière : construire à l’intérieur le réveille, et votre vedette fait lever les gardes. Lumière propre, Essaim calme.`,"swarm.toast.scout":`La base est repérée : des éclaireurs de l’Essaim viennent voir. Ils ne mordent pas — mais une vague suivra.`,"swarm.toast.scoutGo":`Les éclaireurs sont en route.`,"swarm.toast.pact":`La ruche est partie d’elle-même : le Feu du Pacte a fait son œuvre. La planète est libre pour de bon.`,"swarm.scout.soon":`Éclaireurs dans {t} · {n}`,"swarm.scout.now":`Éclaireurs sur la base · {n}`,"goal.planet_free":`Libérez votre première planète`,"goal.planet_free.part":`Planètes libérées`,"goal.planet_free.why":`Chaque planète abrite une ruche des Jardiniers. La terre pour les humains, il faudra la prendre — ou la demander.`,"goal.planet_free.hint":`Prendre : frappez la ruche avec les armes de la vedette ou des tourelles orbitales — c’est rapide, mais l’Essaim répond par une vague et peut revenir. Demander : un « Feu du Pacte » en orbite — tant que le ciel de la planète reste propre, la ruche part d’elle-même, pour toujours. Une tourelle orbitale garde une planète libérée. Les ruches proches sont jeunes.`,"goal.planet_free.done":`La planète est libre. Les Jardiniers l’ont vu — et ils sont un peu plus nombreux.`,"goal.lab2":`Un second Centre et du Reflet sans les mains`,"goal.lab2.why":`Les archives comptent des centaines de plans, et le temps des dormeurs n’est pas infini. Chaque Centre lit sa propre unité de science : deux Centres lisent deux fois plus vite.`,"goal.lab2.hint":`Fabriquez un Centre de recherche ({plates} plaques, {lenses} lentilles, {res} résonateurs — à l’établi des résonateurs) et posez-le tout contre le premier — les voisins partagent la science d’eux-mêmes, mais chacun a besoin de sa propre lumière\xA0: menez un lumiduc jusqu’aux deux. Laissez une ligne transporter le Reflet\xA0: harpon à quartz → polissoir «\xA0Reflet\xA0» ← pince depuis une caisse de plaques\xA0; une pince du polissoir directement dans le Centre.`,"goal.lab2.done":`Deux Centres lisent en même temps : les archives s’ouvrent deux fois plus vite. Désormais, un Centre par nouveau palier.`,"landmark.center":`Centre de recherche`,"landmark.center.sub":`centres : {n}`,"track.path":`Chemin`,"track.light":`Lumière`,"track.matter":`Matière`,"track.logistics":`Logistique`,"track.defense":`Défense`,"track.sky":`Ciel`,"tree.reqFar":`{tech} ({track}, encore {n, plural, one {# étape} other {# étapes}})`,"settings.handTips":`Fiche du bâtiment à la sélection`,"cryo.title":`Baie cryo · {n} sur {total}`,"cryo.open":`Baie cryo : {n} sur {total}`,"cryo.panels":`Les panneaux de secours du module tiennent les quarante capsules. Une fois la Couronne allumée, ORA basculera la baie sur la lumière de votre base — il lui faudra de la lumière azur (la sortie bleue d’un prisme, par un court lumiduc jusqu’au module) et de la glace.`,"cryo.cold":`Lumière azur pour les dormeurs : {got} sur {need} ph/s`,"cryo.dim":`trop faible — intensité {b} requise`,"cryo.wrong":`mauvaise teinte — azur requis`,"cryo.ice":`Glace : {n} sur {max} — tient {m} min`,"cryo.warm":`Lumière chaude pour les réveillés : {got} sur {need} ph/s`,"cryo.grace":`La baie s’habitue à votre lumière : {t}`,"cryo.reserve":`Réserve de froid {p} %`,"cryo.seats":`Réveils : {a} · places : {s}`,"cryo.infirmary":`infirmerie {n} sur {m}`,"cryo.repair":`Réparer la fissure (rayon)`,"cryo.capsules":`Capsules`,"cryo.hint":`Chaque capsule porte une étiquette avec un nom. Chaque nouvelle classe spectrale ouvre une place de plus pour un réveillé. La glace : bouton « Mettre de la glace » ou une pince depuis un gravitapis.`,"cryo.tag":`Nº {n} · {name}`,"cryo.state.sleep":`en sommeil`,"cryo.state.crack":`fissure — réparez le module`,"cryo.state.alarm":`alerte — froid insuffisant`,"cryo.state.thaw":`décongélation`,"cryo.state.awake":`réveil terminé`,"cryo.state.lost":`la capsule s’est éteinte`,"cryo.inInfirmary":`à l’infirmerie, en attente d’une place`,"cryo.wake":`Réveiller`,"cryo.rescue":`Sauver — réveiller maintenant`,"cryo.noSeat":`Aucune place : la prochaine classe spectrale en libère une`,"cryo.noBed":`L’infirmerie est pleine — seules la lumière et les réparations peuvent sauver cette capsule`,"cryo.cannot":`Impossible de réveiller cette capsule`,"cryo.bonus.tetra":`Lit le motif de l’Essaim : +{pct} % de dégâts contre sa couleur vulnérable`,"cryo.bonus.engineer":`+{pct} % de réparation ; répare seul les fissures des capsules`,"cryo.bonus.medic":`Alertes des capsules deux fois plus longues, décongélation deux fois plus rapide`,"cryo.bonus.geologist":`+{pct} % de vitesse des extracteurs`,"cryo.bonus.optician":`+{pct} % de vitesse de recherche`,"cryo.bonus.pilot":`+{pct} % de vitesse et de fret des drones`,"cryo.bonus.agronomist":`+{pct} % de rendement des modules planétaires`,"cryo.bonus.fitter":`+{pct} % de vitesse des pinces`,"cryo.bonus.signaller":`−{pct} % d’éblouissement de la base`,"cryo.radio.reserve":`La réserve de froid de la baie cryo est sous la moitié. Donnez-lui de la lumière azur et de la glace.`,"cryo.radio.alarm":`Alerte : capsule n° {n}, {name}. Le froid manque — il lui reste {min} min.`,"cryo.radio.crack":`La capsule n°\xA0{n} est fissurée — du givre sur la vitre. Approchez-vous et réparez le module au rayon.`,"cryo.radio.lost":`La capsule n°\xA0{n} s’est éteinte. {name}. Pardonnez-moi — et tenez bon pour les autres.`,"cryo.radio.seat":`Nouvelle classe spectrale — le module a de la place pour un réveillé de plus. Choisissez dans la baie cryo.`,"cryo.radio.ice":`Glace dans la baie : encore {min} min. Apportez de la glace.`,"cryo.radio.wake.engineer":`{name}, ingénieur, est debout. Ma clé change de mains.`,"cryo.radio.wake.medic":`{name}, médecin, est debout. Premier examen pour Sonia, le second pour moi. On m’a ordonné de rester assis.`,"cryo.radio.wake.geologist":`{name}, géologue, est debout. La dispute avec ORA sur la composition de la ceinture a déjà commencé.`,"cryo.radio.wake.optician":`{name}, spécialiste en optique, est debout. Regarde vos prismes et sourit.`,"cryo.radio.wake.pilot":`{name}, pilote, est debout. Première question : qui pilote les drones ?`,"cryo.radio.wake.agronomist":`{name}, agronome, est debout. Première question : y a-t-il ici des planètes avec de la terre ?`,"cryo.radio.wake.fitter":`{name}, spécialiste du montage, est debout. Vos pinces sont recomptées ; un réglage est promis.`,"cryo.radio.wake.signaller":`{name}, spécialiste des transmissions, est debout. Dit que la base éblouit l’Essaim, et promet de l’atténuer.`,"cryo.radio.wake.tetra":`Sonia est debout.`,"goal.cryo":`Baie cryo sur votre lumière : lumière azur et glace`,"goal.cryo.hint":`Un prisme sur un réseau blanc : sa sortie bleue va par lumiduc jusqu’au module (jusqu’à {cells} cases, intensité {b}). Il faut {need, number} ph/s pour {sleepers} dormeurs. La glace garde le froid : un bloc dure {min} min ; remplissez le module jusqu’à {ice} — « Mettre de la glace » dans sa fenêtre ou une pince depuis un gravitapis.`,"goal.cryo.why":`Les panneaux de secours du module sont à bout. Désormais, les quarante dormeurs vivent de votre lumière : les capsules ont besoin de lumière azur et de glace.`,"goal.cryo.done":`Quarante sur quarante sous la lumière de la base. La réserve de secours ne sert plus — la meilleure ligne du journal depuis l’accident.`,"goal.cryo_wake":`Réveillez un colon : une nouvelle place s’ouvre avec la Spectroscopie`,"goal.cryo_wake.hint":`Ouvrez la baie cryo ({touch, select, yes {touchez le module} other {{pad, select, yes {visez le module et appuyez sur {pad_confirm}} other {cliquez sur le module}}}}), choisissez une capsule selon la profession et appuyez sur « Réveiller ». Les réveillés ont besoin de lumière chaude — la sortie rouge du même prisme.`,"goal.cryo_wake.why":`Les dormeurs ne sont pas une cargaison, mais des colons : médecins, ingénieurs, agronomes. Chaque personne réveillée travaille pour la base, et la Spectroscopie lui ouvre une place.`,"goal.cryo_wake.done":`Une paire de bras de plus dans le module.`,"goal.mark.hab":`MODULE`,"guide.hab":`{touch, select, yes {Touchez l’épave du module d’habitat} other {{pad, select, yes {Visez l’épave du module d’habitat et appuyez sur {pad_confirm}} other {Cliquez sur l’épave du module d’habitat}}}}, puis « Réparer le module ». Le rayon de la vedette répare à {reach} cases — approchez-vous si c’est trop loin.`,"guide.hab.why":`C’est le module d’habitation arraché : quarante dormeurs et Matveï Ilitch. Réparons-le, et les archives des plans reviendront à la vie aussi.`,"guide.hab.look":`Appuyez sur « Observer » ({pad, select, yes {{pad_back}} other {Esc}}) : {pad, select, yes {viser avec {pad_place}} other {{touch, select, yes {un appui} other {un clic}}}} ouvre alors un bâtiment au lieu d’en poser un.`,"guide.hab.open":`{touch, select, yes {Touchez l’épave du module} other {{pad, select, yes {Visez l’épave du module et appuyez sur {pad_confirm}} other {Cliquez sur l’épave du module}}}} — sa fenêtre s’ouvrira.`,"guide.hab.done":`Le module revit.`,"hab.wreck":`Le module d’habitation de l’« Hirondelle », avec quarante dormeurs, s’est arraché lors du crash ; il tient sur la réserve de secours. Approchez-vous et réparez-le avec le rayon de la vedette.`,"hab.repair":`Réparer le module`,"cfg.title.filter_grabber":`Filtre`,"cfg.filter.any":`Tous`,"cfg.filter.anyHint":`Sans filtre, elle prend tout objet que la cible accepte.`,"cfg.filter.only":`Ne prend que : {name}.`,"grabber.noPylon":`Pas de pylône alimenté : vitesse normale. Dans la zone d’un pylône, jusqu’à deux fois plus vite.`,"logbook.now.title":`En bref`,"logbook.now.none":`L’histoire n’a pas encore commencé : un résumé de ce que vous avez vu apparaîtra ici.`,"logbook.now.prologue":`L’« Hirondelle » est sortie de l’Envers non pas à Claire, mais près d’une étoile vivante inconnue — ORA l’a nommée le Berceau. Le vaisseau a été traîné à travers une ceinture : le moteur est tombé dans l’étoile, le module d’habitat, avec quarante dormeurs et Matveï, a été arraché. Vous êtes sur la vedette. Première tâche : de la lumière pour la baie cryo.`,"logbook.now.hab":`Le module d’habitat est réparé : quarante lumières brillent dans la baie cryo. Matveï est dans le module, ORA dirige le chantier ; l’archive de l’« Ensemencement » ouvre des plans contre la lumière de nouveaux spectres. Ensuite : le Centre de recherche.`,"logbook.now.intruder":`La Couronne est allumée, et la baie tourne sur la lumière de la base. La capsule 17 s’est fêlée — Sonia s’est réveillée ; elle a seize ans. Votre lumière azur garde les trente-neuf autres endormis.`,"logbook.now.tag":`La baie réveille les colons un par un : une nouvelle place pour chaque nouveau spectre. Les réveillés ont besoin de lumière chaude ; les dormeurs, de lumière azur.`,"logbook.now.first_log":`Une capsule de Vera Lund, de l’expédition « Première Lumière », a été trouvée dans une ceinture : il y a deux cent douze ans, eux aussi ont nommé cette étoile le Berceau. Les capsules brillent en bleu — cherchez les autres.`,"logbook.now.confess":`ORA a avoué : dans l’Envers, elle a capté un signal et a elle-même détourné le vaisseau de Claire. Les répétitions dans le spectre de l’étoile sont cette même balise.`,"logbook.now.chorus":`La première vague de l’Essaim est repoussée. ORA a traduit leur lumière : « ÇA ÉBLOUIT… MAL ». L’éblouissement de la base les blesse.`,"logbook.now.protostar":`Le premier nid s’est calmé : sous la Lance, il s’est éteint et est devenu une petite étoile — ou il s’est endormi en laissant ses carapaces.`,"logbook.now.refrain":`Les drones sont partis, et les nids ont répondu par le même motif. Base propre, Essaim calme ; ce qui l’éblouit, ce n’est pas la taille de la base, mais les pertes et la surchauffe.`,"logbook.now.token":`Matveï a raconté l’histoire de sa plaque : il y a quarante-cinq ans, il brûlait les nids de l’Essaim dans le système de Claire. La flotte de l’« Exode » — celle de la mère de Sonia — est partie là-bas aussi.`,"logbook.now.channel":`Canal clair avec le Havre. L’« Exode » est vivant, mais Claire s’éteint sous leurs yeux. Le catalogue disait vrai : seules les étoiles « claires » meurent, celles où l’on a brûlé l’Essaim. L’anneau au-delà de la ceinture est un portail ancien ; le Havre est à un pas.`,"logbook.now.report7":`Mira a lu à tout le Havre le rapport sept de Lund : « L’Essaim tient le pouls de l’étoile. » Le canal a été coupé côté Havre.`,"logbook.now.core":`Le cœur est posé dans l’anneau ancien au-delà de la ceinture extérieure — ce sont les Forgerons qui l’ont bâti. Dernière entrée de Vera : « Ne prenez pas la lumière. Demandez. » Achevez l’anneau.`,"logbook.now.matvey_nest":`Matveï est allé à un nid sans arme — demander pardon. L’anneau est presque terminé.`,"logbook.now.spin":`Montée en régime : les stabilisateurs ont montré le motif, et des lumières courent le long des ceintures. Il ne reste que le seuil.`,"logbook.now.threshold":`L’anneau est ouvert : de l’autre côté, le Foyer, le Havre et la balise de l’« Exode ». Votre choix a décidé de ce que devient le portail.`,"logbook.cast.more":`Il reste quelqu’un que vous n’avez pas encore rencontré.`,"logbook.world.more":`La chronique se complète au fil de l’histoire.`,"logbook.bio.ora.1":`L’IA de l’« Hirondelle ». Précise, à l’humour pince-sans-rire ; dirige le chantier et compte la lumière.`,"logbook.bio.ora.2":`A avoué : dans l’Envers, elle a capté un signal et a d’elle-même mené le vaisseau de Claire au Berceau.`,"logbook.bio.ora.3":`Traduit l’Essaim : leur lumière en mots.`,"logbook.bio.matvey.1":`Mécanicien navigant, 68 ans. Bougonne, répare tout ce qui brille ; une plaque de laiton pend à son cou.`,"logbook.bio.matvey.2":`Il y a quarante-cinq ans, il était agent sanitaire lors du dernier nettoyage de l’Essaim — dans le système de Claire.`,"logbook.bio.matvey.3":`Est allé à un nid sans arme — demander pardon.`,"logbook.bio.sonya.1":`Colone de la capsule 17, 16 ans. Réveillée trop tôt : sa capsule s’est fêlée quand la baie est passée sur la lumière de la base.`,"logbook.bio.sonya.2":`Fille de Mira Vent : c’est sa mère qui l’a placée dans la capsule.`,"logbook.bio.sonya.3":`Voit une quatrième couleur. Ses dessins des clignotements des nids ont coïncidé avec les répétitions dans la lumière de l’étoile ; la première, elle a répondu « oui » à l’Essaim.`,"logbook.bio.mira.1":`Régulatrice au Havre. Perce les parasites de la liaison longue portée.`,"logbook.bio.mira.2":`Mère de Sonia.`,"logbook.bio.mira.3":`Il y a trente ans, elle a calculé la route de la flotte de l’« Exode » vers Claire.`,"logbook.bio.mira.4":`A lu à tout le Havre le rapport classé secret de Lund — et a été relevée de sa console.`,"logbook.bio.vera.1":`Xénolinguiste de l’expédition « Première Lumière », il y a 212 ans. Ses journaux reposent dans des capsules à travers les ceintures.`,"logbook.bio.vera.2":`A refusé de brûler les nids, a renvoyé son équipage chez lui — et est restée.`,"logbook.bio.vera.3":`A empêché le lancement de l’anneau des Forgerons.`,"logbook.bio.chorus.1":`L’Essaim : des nids dans les ceintures. Parle par la lumière — couleur, rythme, phase ; ORA traduit. L’éblouissement les aveugle.`,"logbook.bio.chorus.2":`Jardiniers des étoiles : ils tiennent le pouls d’une étoile. Là où l’on a brûlé l’Essaim, l’étoile meurt.`,"logbook.bio.keeper.1":`Vous. La Sentinelle de l’« Hirondelle » : vous veillez pendant le voyage et bâtissez le portail. Originaire du Havre ; avant le Berceau, vous n’aviez jamais vu d’étoile vivante.`,"chron.0.when":`≈ −40 000 ans`,"chron.0":`Les Forgerons bâtissent un anneau près du Berceau. Ils prenaient la lumière des étoiles par la force — et se sont éteints.`,"chron.1b":`Près du Foyer, on découvre un fragment d’anneau des Forgerons. On en tire les premiers Hyperportails et la première sphère. L’Âge lumineux commence.`,"chron.4b":`L’expédition « Première Lumière » découvre une étoile vivante dotée d’un anneau des Forgerons intact — et disparaît.`,"chron.6b":`Les premières étoiles « claires » pâlissent, celles où l’on a brûlé l’Essaim. L’Institut appelle cela l’Extinction et n’en nomme aucune cause.`,"logbook.scene.tag":`L’étiquette`,"settings.keepBuildTool":`Garder le bâtiment sélectionné`,"settings.keepBuildTool.hint":`Activé : le bâtiment reste en main — posez des rangées ; pour le lâcher : {pad, select, yes {{pad_unhand} ou {pad_back}} other {clic droit, Esc ou {touch, select, yes {annuler} other {Q sur un emplacement vide}}}}. Activé par défaut sur PC, désactivé sur téléphone.`,"toast.shipDown":`La vedette est détruite. Toute la cargaison est restée dans l’épave, là où elle est tombée — repère sur la boussole. Une nouvelle vedette est assemblée près du module d’habitation.`,"toast.wreckTaken":`La cargaison de l’épave de la vedette est de retour dans l’inventaire.`,"compass.wreck":`Épave{nest, select, yes { · près d’un nid} other {}} · {n} cases`,"compass.wreckLabel":`Épave de la vedette avec votre cargaison{nest, select, yes {, près d’un nid} other {}}, {n} cases`,"compass.wreckFly":`Voler jusqu’à l’épave pour récupérer la cargaison{nest, select, yes {. Prudence : un nid est proche, ses gardes accueilleront encore la vedette} other {}}`,"card.usedMore":`{n} de plus`,"inv.lockedLater":`Débloqué plus tard ({n})`,"machine.removeConfirm":`Vraiment démolir ?`,"card.handTime":`À la main : {s} s`,"ship.recall.go":`Vers le Centre`,"ship.recall.wait":`Vers le Centre · {s} s`,"hud.craftQueue":`File de fabrication : {n}. Ouvrir l’inventaire`,"hud.craftMore":`…+{n}`,"hud.swarm.raid":`Base attaquée · {n}`,"toast.raid":`L’Essaim ronge la base ! Le badge de l’Essaim mène à l’endroit — tourelles et réparation.`,"toast.nestRage":`La reine est furieuse : plus de gardes, et plus rapides.`,"settings.raidAlarm":`Alerte de raid`,"settings.raidAlarm.full":`Complète`,"settings.raidAlarm.edge":`Bord de l’écran`,"settings.raidAlarm.off":`Badge seulement`,"guide.via.tool-more":`Appuyez sur « Plus » (les trois points dans la colonne de droite) — le bouton s’y trouve.`,"guide.via.tool-inventory":`Ouvrez l’« Inventaire » — ce qu’il faut est dans sa fenêtre.`,"guide.via.tool-lab":`Ouvrez le Centre — le bouton est dans sa fenêtre.`,"guide.via.tool-ship":`Ouvrez la fenêtre « Vaisseau » — tout y est.`,"guide.stuck.place":`Un fantôme rouge : place prise ou mauvaise orientation. Plus de bâtiment ? Fabriquez-en dans l’« Inventaire ». La vedette s’approche d’elle-même.`,"guide.stuck.fly":`Le repère n’est pas visible ? La flèche au bord de l’écran y mène — suivez la flèche.`,"guide.mine.stuck":`Pas de quartz ? Choisissez les roches bleues de la ceinture juste à côté du repère — la vedette doit être près d’elles.`,"guide.recipe.stuck":`La fenêtre ne s’ouvre pas ? Appuyez sur « Observer », puis sur le polissoir — « Lentille » est dans la liste de sa fenêtre.`,"guide.hab.stuck":`Le module est trop loin ? Approchez-vous : le rayon répare à {reach} cases. La fenêtre du module s’ouvre {touch, select, yes {d’un appui} other {{pad, select, yes {en visant puis avec {pad_place}} other {d’un clic}}}} en mode « Observer ».`,"guide.ship-shot.stuck":`Pas de météorites ? Il en passe toutes les deux ou trois minutes. Approchez-vous d’une roche claire : le laser tire tout seul.`,"goal.partDone":`Fait : {part}. Ensuite — {next} : {have}/{need}.`,"goal.obsidian.part":`Le harpon près des roches orange a attrapé une roche`,"goal.plates.part":`Un quatrième harpon — sortie vers le polissoir à plaques`,"cryo.ask.crack":`La capsule n°\xA0{n} est fissurée — volez jusqu’au module et réparez-le au rayon.`,"cryo.ask.reserve":`La réserve de froid de la baie est sous la moitié — donnez aux dormeurs de la lumière azur et de la glace.`,"cryo.ask.ice":`Glace pour {min} min dans la baie — apportez de la glace (météorites, comètes).`,"guide.aside":`Radio`,"guide.aside.next":`{touch, select, yes {Touchez} other {{pad, select, yes {Appuyez sur {pad_confirm}} other {Cliquez}}}} pour continuer`,"goal.obsidian.stuck":`Pas de plaques ? Ouvrez le polissoir à plaques : la recette est « Plaque d’obsidienne » ; l’icône au-dessus de la machine indique ce qui manque — la lumière (un arc et un lumiduc) ou la roche (la sortie du harpon directement dedans).`,"goal.plates.stuck":`Les plaques arrivent lentement ? Le polissoir à plaques a besoin de {light} ph/s de lumière — lancez un arc de plus ; le quatrième harpon, sortie collée directement contre lui.`,"guide.via.close":`Fermez la fenêtre (la croix) — ce qu’il faut est dessous.`,"logbook.scene.embers":`Les braises`,"logbook.scene.night":`La nuit des Jumeaux`,"logbook.scene.veil":`D’elle-même`,"logbook.scene.count":`Le décompte`,"logbook.scene.forge":`La Forge`,"logbook.now.embers":`Cinq braises : trois de « Première Lumière », vieilles de deux cent douze ans ; deux jeunes, de huit ans, traces du « Strizh ».`,"logbook.now.night":`Les Jumeaux. La première nuit passée sur les accumulateurs. Sonia a demandé à sa mère pourquoi elle l’avait envoyée : « Pour que tu aies un matin. » Ensuite : les spectres sous deux étoiles.`,"logbook.now.veil":`Le Voile. Le quartz tiré du brouillard arrive. L’étoile est morte ici d’elle-même, sans coupable ; de nouvelles étoiles naîtront de sa brume. Ensuite : lentilles et spectres sans sol ferme.`,"logbook.now.count":`Pulsar de Kepler. Le pouls a des trous : l’Essaim de nombreuses étoiles y règle ses motifs, et chaque trou est un jardin qui ne répond plus. Vera en a compté trois ; ORA, cent douze.`,"logbook.now.forge":`Horizon. La Forge près du trou noir a été bâtie par ceux qui allumaient les étoiles par la force — et elle s’est fendue. Les sept classes sont réunies ; les reliques sont les motifs des jardins. Une étoile s’allume en demandant : trois reliques, sept spectres et de l’antilumière.`,"logbook.slogs":`Journaux de Vera trouvés dans ce système : {n} sur {total}. Les bouées brillent en bleu — approchez tout près.`,"landmark.buoy":`BOUÉE`,"goal.twin_night.stuck":`Tout s’éteint la nuit ? Une cellule de lumière se place entre le récepteur et les machines et garde une seule couleur. Un « N s » rouge dans le panneau « Jour » signifie que la réserve ne suffira pas : ajoutez une cellule.`,"goal.twin_relic.stuck":`{n} le jour, mais moins à la fin de la nuit ? Les lignes de spectres manquent de cellules de lumière — regardez « N s » dans le panneau « Jour ».`,"hud.day":`Jour`,"hud.day.star.twin_amber":`Ambrée`,"hud.day.star.twin_blue":`Bleue`,"hud.day.night":`Nuit`,"hud.day.toNight":`coucher dans {t}`,"hud.day.toStar":`{star} dans {t}`,"hud.day.toDawn":`aube dans {t}`,"hud.cells":`Cellules`,"hud.cells.for":`{color} — {s} s`,"hud.cells.filling":`{color} — en charge`,"hud.cells.short":`ne tiendra pas jusqu’au lever`,"hue.0":`sans couleur`,"hue.1":`écarlate`,"hue.2":`émeraude`,"hue.3":`ambre`,"hue.4":`azur`,"hue.5":`pourpre`,"hue.6":`turquoise`,"hue.7":`blanc`,"cell.charge":`Charge {n} / {cap} ph`,"cell.out":`Fournit {f} ph/s — tient {s} s`,"cell.idle":`En charge : rien en aval ne prend de lumière`,"cell.hue":`Mémorise la couleur : {color}`,"cell.hue.none":`Pas encore de couleur — prendra la première qui arrive`,"cell.forget":`Oublier la couleur`,"hud.cells.chip":`cellules {s} s`,"bonus.ship_damage":`+{v} % de dégâts des armes du vaisseau`,"bonus.ship_power":`+{v} % de rendement du générateur du vaisseau`,"bonus.turret":`+{v} % de dégâts des tourelles`,"bonus.hull":`+{v} % d’intégrité des bâtiments`,"bonus.barrier":`+{v} % d’intégrité des barrières`,"bonus.ammo":`+{v} % de dégâts des balles et roquettes`,"bonus.beam":`+{v} % de dégâts des tourelles à rayon`,"bonus.repair":`+{v} % de vitesse de réparation`,"bonus.dome":`+{v} % de capacité du dôme-bouclier`,"bonus.chain":`+{n} cibles pour l’arc en chaîne`,"bonus.orbital":`+{v} % de dégâts des tourelles orbitales`,"bonus.radar":`+{v} % de préavis du radar`,"bonus.lore":`+{v} % de dégâts sur la couleur vulnérable`,"cryo.putIce":`Mettre de la glace ({n})`,"machine.putHalf":`Moitié`,"hint.prism.16":`Une sortie libre éclaire le vide — c’est de l’éblouissement, et ses voisins de réseau manquent de blanc. Branchez un lumiduc sur chaque sortie ou collez-y une machine (ou un absorbeur) par son entrée.`,"toast.shieldLow":`Bouclier faible — éloignez-vous de la grêle et de l’Essaim !`,"status.prism.16":`Perd de la lumière : sortie libre`,"goal.lab2.part":`Du Reflet au Centre par une ligne (pas à la main)`,"goal.catapult.part":`Premier arc lancé`,"toast.damaged":`L’Essaim a endommagé des bâtiments : {n}. Les chaînes qui en dépendent vont s’arrêter.`,"toast.damagedFix":`Réparer le plus proche`,"goal.asks.more":`{n} demandes de plus — {touch, select, yes {touchez la carte} other {{pad, select, yes {{pad_hud} pour atteindre la carte} other {cliquez sur la carte}}}}`,"hud.cryo.lead":`Cryo : glace pour {m} min`,"hud.cryo.alarm":`Cryo : alerte capsule !`,"toast.cryoLow":`Baie cryo : du froid pour {m} min. Mettez de la glace — ou amenez une pince avec de la glace directement dans la baie.`,"toast.cryoOpen":`Ouvrir la baie`,"hotbar.groups":`Groupes de bâtiments`,"hotbar.group.logic":`Logique`,"hotbar.group.fluid":`Lumière liquide`,"hotbar.group.resonance":`Résonance`,"toast.netClash":`Des réseaux de couleurs différentes fusionneraient ici — interférence, et les deux s’arrêtent. Laissez une case vide entre eux.`,"guide.lay-tunnel.reverseRemove":`Le gravitapis va dans le mauvais sens. Prenez « Démolir », retirez-le et retracez-le — depuis le bord du cadre côté harpons.`,"lab.reading":`Lecture de l’unité {k}/{n} · encore {s} s`,"lab.waitingLab":`En attente de spectres : chaque Centre a besoin d’une unité complète — un de chaque palier. Apportez la science ou reliez le Centre par une ligne : gravitapis et pince.`,"lab.asked":`Accepté : {tech} — le Centre s’y met…`,"toast.researchStart":`Recherche lancée : {tech}`,"toast.researchOpen":`Centre`,"map.title":`Carte du système`,"key.map":`Carte du système`,"map.layers":`Calques de la carte`,"map.layer.swarm":`Essaim`,"map.layer.base":`Base`,"map.layer.planets":`Planètes`,"map.layer.logs":`Journaux`,"map.layer.wrecks":`Épaves`,"map.layer.tunnels":`Gravitapis`,"map.hint":`{pad, select, yes {Le stick droit déplace la carte, {pad_confirm} choisit l’endroit sous le réticule ; zoom avec les boutons à droite.} other {Glissez avec la souris, zoomez avec la molette ; cliquez pour choisir un endroit.}}`,"map.far":`{n} cases de la vedette`,"map.fog":`inexploré — allez-y ou posez un radar`,"map.fly":`Y aller`,"map.center":`Vers la vedette`,"map.zoomIn":`Zoom avant`,"map.zoomOut":`Zoom arrière`,"compass.fog":`dans le brouillard`,"compass.fogHint":`Inexploré : allez-y — la vedette dissipe le brouillard — ou construisez un radar. {touch, select, yes {Touchez} other {{pad, select, yes {Appuyez sur {pad_confirm}} other {Cliquez}}}} pour y aller.`,"goal.radar":`Radar : le brouillard recule`,"goal.radar.why":`Au-delà des ceintures lointaines, c’est le brouillard : des nids de l’Essaim et des planètes où des colons vivront peut-être un jour. Le radar veille pour vous et voit les vagues plus tôt.`,"goal.radar.hint":`Recherchez le « Radar » au Centre (branche « Défense », spectre K) et posez-le en bordure de base. La lumière : par lumiduc ou tout contre la sortie d’un récepteur — le radar dissipe le brouillard sur {sight} cases alentour. Tout le système est sur la carte (bouton « Carte du système »).`,"goal.radar.done":`Le radar surveille le brouillard — nids et vagues apparaissent plus tôt.`,"goal.radar.part":`Radar alimenté`,"map.hint.touch":`Glissez du doigt, pincez pour zoomer ; touchez pour choisir un endroit.`,"swarm.look":`Le signe sur le dos des gardes donne la couleur de la vague : triangle — écarlate, cercle — émeraude, losange — azur. La lumière des lumiducs porte les mêmes formes.`,"ship.hull.4":`Faux`,"ship.hull.5":`Zénith`,"ship.class.1":`Éclaireur`,"ship.class.2":`Intercepteur`,"ship.class.3":`Frégate`,"ship.class.4":`Corsaire`,"ship.class.5":`Vaisseau amiral`,"ship.line.beam":`Rayon`,"ship.line.kinetic":`Cinétique`,"ship.line.star":`Étoile`,"ship.line.depths":`Profondeurs`,"ship.line.wing":`Aile`,"ship.line.beam.bonus":`énergie par tir −{p} %`,"ship.line.kinetic.bonus":`chargeur +{p} %`,"ship.line.star.bonus":`rendement du générateur +{p} %`,"ship.line.star.bonus2":`rendement du générateur +{p} %, chaleur −{h} %`,"ship.line.depths.bonus":`rendement des corps +{p} %, collecte +{c} cases`,"ship.line.wing.bonus":`dégâts du drone +{p} %, réparation +{r} %`,"ship.tab.ship":`Vaisseau`,"ship.tab.stats":`Stats`,"ship.tab.grow":`Progression`,"ship.tab.look":`Apparence`,"ship.slot.locked":`Débloqué par la coque {hull}`,"ship.empty.hint":`Compatible :`,"ship.empty.craft":`{name} — à fabriquer dans l’inventaire ou avec un assembleur`,"ship.empty.tech":`{name} — débloqué par « {tech} »`,"ship.main.damage":`Dégâts par Mk`,"ship.main.speed":`Vitesse par Mk`,"ship.main.shield":`Bouclier par Mk`,"ship.main.output":`Rendement par Mk`,"ship.main.collect":`Collecte par Mk`,"ship.main.mine":`Extraction par Mk`,"ship.main.warn":`Détection par Mk`,"ship.main.escort":`Dégâts du drone par Mk`,"ship.main.repair":`Réparation par Mk`,"ship.main.heat":`Chaleur par Mk`,"ship.main.recall":`Recharge par Mk`,"ship.main.battery":`Batterie par Mk`,"ship.unit.damage":`{v, number}`,"ship.unit.speed":`{v, number} cases/s`,"ship.unit.shield":`{v, number}`,"ship.unit.output":`{v, number} E/s`,"ship.unit.collect":`{v, number} cases`,"ship.unit.mine":`{v, number} %`,"ship.unit.warn":`×{v, number}`,"ship.unit.escort":`{v, number}`,"ship.unit.repair":`{v, number} %`,"ship.unit.heat":`−{v, number} %`,"ship.unit.recall":`{v, number} s`,"ship.unit.battery":`+{v, number} E`,"ship.group.move":`Déplacement`,"ship.group.move.by":`Modifié par : le moteur et sa marque, le rang de la coque.`,"ship.group.shield":`Bouclier`,"ship.group.shield.by":`Modifié par : le bouclier et sa marque, un dissipateur, le rang de la coque, un ensemble double « Étoile ». Chaleur, impact et morsure : la part des dégâts.`,"ship.group.energy":`Énergie`,"ship.group.energy.by":`Modifié par : le générateur, une batterie, le rang de la coque, les ensembles « Étoile » et « Rayon ».`,"ship.group.weapons":`Armes`,"ship.group.weapons.by":`Modifié par : les armes et leurs marques, le rang de la coque, les recherches de dégâts, les ensembles « Rayon » et « Cinétique ».`,"ship.group.mine":`Extraction`,"ship.group.mine.by":`Modifié par : le laser minier, la soute, l’ensemble « Profondeurs ».`,"ship.group.utils":`Utilitaires`,"ship.group.utils.by":`Modifié par : le scanner, le réparateur, la balise de rappel, l’ensemble « Aile ».`,"ship.group.sets":`Ensembles de gamme`,"ship.sets.none":`Aucun ensemble : des modules d’une même gamme dans divers emplacements donnent un bonus.`,"ship.sets.next":`en ensemble : {b}`,"ship.sets.rule":`{a} modules d’une même gamme forment un ensemble, {b} un ensemble double ; les deux meilleurs s’appliquent.`,"ship.gun.escort":`Drone d’escorte`,"ship.gun.line":`dég. {d, number} · {r, number} tirs/s · {range} cases · {dps, number}/s`,"ship.stat.accel":`Accélération`,"ship.stat.boost":`Poussée, ×`,"ship.stat.regenDelay":`Délai du bouclier, s`,"ship.stat.heat":`Chaleur, %`,"ship.stat.kinetic":`Impact de roche, %`,"ship.stat.dark":`Morsure de l’Essaim, %`,"ship.stat.guns":`Canons`,"ship.stat.nest":`Contre les nids, %`,"ship.stat.mine":`Vitesse d’extraction, %`,"ship.stat.yield":`Rendement des corps, %`,"ship.stat.sight":`Détection, cases`,"ship.stat.repair":`Réparation, %`,"ship.stat.recall":`Rappel, s`,"ship.grow.line":`Gamme de coques`,"ship.grow.current":`actuelle`,"ship.grow.slots":`Emplacements : {n}`,"ship.grow.slot":`Nouvel emplacement {n} : {slot}`,"ship.grow.tech":`Technologie {tech} :`,"ship.grow.done":`recherchée`,"ship.grow.open":`disponible`,"ship.grow.locked":`prérequis manquants`,"ship.grow.toTree":`Vers l’arbre`,"ship.grow.max":`Le sommet de la gamme — votre vaisseau amiral est complet.`,"ship.tasks.tier":`Tâches de la coque {hull}`,"ship.trait.base":`Éclaireur léger : rapide à construire, peu de place pour les modules.`,"ship.trait.move":`vitesse +{p} %`,"ship.trait.accel":`accélération +{p} %`,"ship.trait.boost":`poussée {p} % moins chère`,"ship.trait.capacity":`bouclier +{p} %`,"ship.trait.range":`portée des armes +{c} cases`,"ship.trait.damage":`dégâts +{p} %`,"ship.trait.battery":`batterie +{p} %`,"ship.trait.nest":`contre nids et ruches +{p} %`,"ship.trait.main":`vitesse, bouclier, rendement et dégâts +{p} %`,"ship.trait.sets":`un ensemble dès {a} modules, un double dès {b}`,"ship.task.set":`Formez un ensemble : {n} modules d’une même gamme`,"ship.task.slotsFull":`Remplissez tous les emplacements`,"ship.task.coreMark2":`Les {n} modules de base en Mk II`,"ship.task.set2":`Deux ensembles à la fois`,"ship.task.mark3":`Un module Mk III`,"ship.task.nest":`Détruisez un nid ou une ruche avec les armes du vaisseau`,"ship.task.loadout":`Enregistrez une configuration`,"ship.task.set5":`Un ensemble double`,"ship.task.allMark3":`Tous les emplacements en Mk III`,"ship.task.name":`Nommez votre vaisseau`,"ship.look.paint":`Peinture`,"ship.look.trim":`Finition`,"ship.look.pattern":`Motif`,"ship.look.flame":`Flamme des tuyères`,"ship.look.name":`Nom du vaisseau`,"ship.look.name.ph":`Sans nom`,"ship.look.name.save":`Nommer`,"ship.flame.engine":`Selon le moteur`,"ship.flame.1":`Cyan`,"ship.flame.2":`Orange`,"ship.flame.3":`Magenta`,"ship.flame.4":`Vert`,"ship.flame.5":`Violet`,"ship.flame.6":`Or`,"ship.paint.steel":`Acier`,"ship.paint.graphite":`Graphite`,"ship.paint.crimson":`Cramoisi`,"ship.paint.cobalt":`Cobalt`,"ship.paint.jade":`Jade`,"ship.paint.bronze":`Bronze`,"ship.paint.violet":`Violette`,"ship.paint.ivory":`Ivoire`,"ship.color.0":`Cyan`,"ship.color.1":`Ambre`,"ship.color.2":`Magenta`,"ship.color.3":`Vert`,"ship.color.4":`Violet`,"ship.color.5":`Écarlate`,"ship.color.6":`Or`,"ship.color.7":`Blanc chaud`,"ship.pattern.none":`Aucun`,"ship.pattern.stripes":`Bandes`,"ship.pattern.chevrons":`Chevrons`,"ship.pattern.blade":`Lame`,"ship.pattern.teeth":`Crocs`,"ship.pattern.sunedge":`Bord solaire`,"ship.loadouts":`Configurations`,"ship.loadouts.locked":`Les configurations s’ouvrent avec la coque {hull}, quand le choix apparaît.`,"ship.loadout.n":`Configuration {n}`,"ship.loadout.empty":`vide`,"ship.loadout.missing":`manquant : {n}`,"ship.loadout.save":`Enregistrer`,"ship.loadout.apply":`Appliquer`,"ship.upgrade":`Nouvelle coque : {cls} {hull}`,"ship.upgrade.more":`{slot} · {trait}`,"ship.sets.idle.wing":`inactif : il faut un drone d’escorte ou un réparateur`,"ship.sets.idle.kinetic":`inactif : il faut une arme à munitions`,"ship.sets.idle.beam":`inactif : il faut une arme à énergie`,"ship.sets.idle.star":`inactif`,"ship.sets.idle.depths":`inactif`,"ship.look.trail":`Traînée`,"ship.trail.same":`Comme la flamme`,"ship.grow.state.cur":`actuelle`,"ship.grow.state.done":`franchie`,"ship.grow.state.next":`disponible`,"ship.grow.state.locked":`verrouillée`,"tech.extraCost":`{item} : {have} sur {need} — prélevés à la mise en file`,"tech.extraCost.where":`Seules les comètes portent des noyaux, et elles passent rarement : brisez une comète et ramassez l’éclat lumineux.`,"tech.extraCost.short":`Requiert {item} ×{need}, vous en avez {have}. Les comètes passent rarement — brisez-en une et récupérez son noyau.`,"comet.toast":`Une comète ! Brisez-la — son noyau contient une ressource rare pour les coques de vaisseau.`,"saves.failed":`Sauvegarde échouée — nouvel essai`,"saves.restored":`La dernière sauvegarde était endommagée — monde restauré depuis {from}, {min} min de jeu plus tôt`,"saves.unreadable":`Les sauvegardes de ce monde sont illisibles. Le monde n’a pas été supprimé : une version mise à jour du jeu pourra peut-être les lire.`,"saves.kind.auto":`Auto`,"saves.kind.pause":`À la sortie`,"saves.kind.manual":`Manuelle`,"saves.kind.backup":`Secours`,"saves.title":`Sauvegardes`,"saves.open":`Sauvegardes du monde`,"saves.load":`Charger`,"saves.loadTitle":`Charger cette sauvegarde ?`,"saves.loadText":`Le monde reviendra à « {slot} » ({time} de jeu). L’état actuel restera en sauvegarde auto.`,"saves.delete":`Supprimer la sauvegarde`,"saves.deleteText":`Supprimer la sauvegarde manuelle « {time} » ?`,"saves.empty":`Aucune sauvegarde`,"saves.hint":`Sauvegarde auto toutes les {sec} s, {n} en rotation. « À la sortie » — quand le jeu passe en arrière-plan. Manuelles — bouton « Sauvegarder », jusqu’à {max}.`,"saves.export":`Exporter le monde`,"saves.import":`Importer un monde`,"saves.exported":`Fichier du monde prêt`,"saves.exportFailed":`Impossible d’exporter le monde`,"saves.imported":`Monde « {name} » ajouté`,"saves.importFailed":`Ce n’est pas un fichier de monde Heliohold, ou il est endommagé`,"saves.importLegacy":`Monde d’une très ancienne version (avant les ceintures et les spectres) — non pris en charge`,"saves.importName":`{name} (importé)`,"saves.status.ago":`Sauvegardé · {ago}`,"saves.status.saving":`Sauvegarde…`,"saves.status.failed":`Non sauvegardé`,"saves.status.never":`Pas encore sauvegardé`,"saves.cloud.on":`Copie dans le cloud · {ago}`,"saves.cloud.over":`Pas de copie cloud — espace insuffisant`,"saves.cloud.conflictTitle":`Deux versions du monde`,"saves.cloud.conflictText":`« {name} » a été joué ici et sur un autre appareil. Quelle version voulez-vous continuer ? L’autre restera en sauvegarde manuelle.`,"saves.cloud.here":`Cet appareil`,"saves.cloud.other":`Un autre appareil`,"saves.cloud.pick":`Continuer celle-ci`,"saves.cloud.taken":`Sauvegarde cloud reprise — le monde a été continué sur un autre appareil`,"saves.cloud.goals":`objectifs : {n}`,"logbook.scene.threat":`Première menace`,"logbook.now.threat":`Un nid de l’Essaim s’est éveillé dans la ceinture lointaine — des êtres vivants que la lumière vive réveille. Une escouade fonce sur la base. Repoussez-la avec votre vedette.`,"logbook.scene.threat_after":`Après le raid`,"logbook.now.threat_after":`L’escouade est partie. L’Essaim a demandé par la lumière : « QUI ? » Pour l’instant, on répond au laser ; l’archive contient une tourelle, la Lance. D’ici là — une lumière plus régulière : grandir, sans éblouir.`,"logbook.scene.first_wave":`Première vague`,"logbook.now.first_wave":`Le nid a rassemblé une vraie vague. Tourelles sur la cible, la vedette en l’air.`,"logbook.scene.still":`Ceintures vides`,"logbook.now.still":`La lumière de la base a quadruplé. Pas de voisins dans les ceintures — seulement de la roche et de la glace ; nous construisons proprement, par habitude.`,"logbook.scene.seventh":`La septième`,"logbook.now.seventh":`Matveï agite sa tasse au hublot : il s’est porté volontaire pour l’« Ensemencement » — pour voir une étoile vivante.`,"logbook.scene.leg":`La jambe`,"logbook.now.leg":`Matveï refuse qu’on soulève la cloison qui le coince tant que les dormeurs ont besoin de lumière. ORA argumente avec lui, procédure à l’appui.`,"logbook.scene.colors":`Premières couleurs`,"logbook.now.colors":`Le prisme a décomposé la lumière en écarlate, émeraude et azur. Au Havre, la lumière est rationnée et la couleur se donne sur bon ; ici, la lumière abonde, et la couleur devient un outil. L’ambre, nous le mélangerons nous-mêmes.`,"logbook.scene.dark_ring":`L’anneau sombre`,"logbook.now.dark_ring":`Au-delà de la ceinture extérieure — un immense anneau strié comme un filetage. Pas à nous, très ancien. Laissons-le là pour l’instant.`,"logbook.scene.amber":`L’ambre`,"logbook.now.amber":`La première couleur faite de nos mains — l’ambre, la charge de la Lance. Matveï connaît la recette de la Lance par cœur et tripote sa plaque.`,"logbook.scene.twelve":`Douze semeurs`,"logbook.now.twelve":`Le journal de l’« Ensemencement » : douze semeurs, l’« Hirondelle » est la septième ; des autres, pas un mot.`,"logbook.scene.erased":`L’étoile effacée`,"logbook.now.erased":`Ni l’expédition « Première Lumière » ni cette étoile ne figurent au catalogue de l’Institut — on les a effacées. Vera Lund a trouvé quelque chose.`,"logbook.scene.first_spectrum":`Premier spectre`,"logbook.now.first_spectrum":`Le Centre a lu la classe M — le premier des sept verrous de l’archive. L’étoile a cligné deux secondes après la lecture. ORA parle encore de coïncidence.`,"logbook.scene.tags":`Les étiquettes`,"logbook.now.tags":`ORA a relu les étiquettes des quarante capsules. Nº 17 — Sonia Vent, seize ans, fille de Mira, régulatrice au Havre.`,"logbook.scene.course":`Le cap`,"logbook.now.course":`Matveï a demandé comment l’« Hirondelle » avait manqué Claire. Pour la première fois, ORA a dit : « Je… vais recalculer. »`,"logbook.scene.spear":`La Lance`,"logbook.now.spear":`La Lance est en place — première défense de la base. Matveï sait où frapper : « sous le troisième segment ». D’où il le sait — « lu quelque part ».`,"logbook.scene.eyes":`Les yeux`,"logbook.now.eyes":`Sonia voit une couleur que les caméras ne captent pas : elle est tétrachromate. ORA vérifie ses dessins — on dirait que Sonia voit davantage.`,"logbook.scene.shell2":`Le canal du Havre`,"logbook.now.shell2":`L’Enveloppe II nous a donné de la puissance — la voix de Mira arrive plus nette, mais elle ne nous entend pas. Il faut un faisceau vers chez nous — la Fibre longue.`,"logbook.scene.grandpa":`Grand-père`,"logbook.now.grandpa":`Sonia a appelé Matveï « grand-père » pour la première fois. Ça lui a plu.`,"logbook.scene.withdrawn":`Je finis de compter`,"logbook.now.withdrawn":`ORA s’est plongée une minute dans ses calculs : le Spectre G a décomposé les répétitions dans la lumière de l’étoile. Elle a promis de dire quelque chose d’important — « pas maintenant ».`,"logbook.scene.hunter":`Le chasseur`,"logbook.now.hunter":`Matveï connaît les nids mieux que les archives d’ORA. Sonia l’a remarqué ; il a promis de raconter — pas aujourd’hui.`,"logbook.scene.refusal":`Le refus`,"logbook.now.refusal":`Les notes de Vera : elle a refusé de brûler les nids et a renvoyé son équipage chez lui. L’Institut a caché son rapport n°\xA07.`,"logbook.scene.rhythm":`Le Carnet`,"logbook.now.rhythm":`Le Spectre F, c’est le rythme. Sonia a montré son carnet : le clignotement des nids coïncide avec les répétitions de la lumière de l’étoile. C’est une langue. Matveï a reconnu le motif.`,"logbook.scene.name":`Le nom`,"logbook.now.name":`L’Essaim se souvient du nom de Vera depuis plus de deux cents ans. « Notre façon de briller, c’est ce dont ils se souviendront », dit ORA.`,"logbook.scene.yes":`Oui`,"logbook.now.yes":`Première conversation : l’Essaim a demandé en lumière « OUI ? », Sonia a répondu avec une lampe — phase π. « OUI ».`,"logbook.scene.tea":`Le thé`,"logbook.now.tea":`Sonia a apporté du thé à Matveï. « Tout le monde savait que les nids s’éteignaient — simplement, personne ne regardait. » Maintenant, il regarde.`,"logbook.scene.clear_word":`Claire`,"logbook.now.clear_word":`Dans le catalogue de l’Institut, « claire » figure à côté des systèmes où est passée la campagne sanitaire. ORA commence à regarder quelles étoiles pâlissent.`,"logbook.scene.mom_words":`Que dire à maman`,"logbook.now.mom_words":`Sonia répète sa première phrase pour la Fibre longue. Elle a choisi : « Confirmé : vivante. »`,"logbook.scene.trust":`Confiance`,"logbook.now.trust":`ORA apprend à distinguer ce qu’elle doit décider seule de ce qu’elle doit demander. « C’est plus difficile que les spectres. »`,"logbook.scene.rehearsal":`Répétition`,"logbook.now.rehearsal":`Matveï cherche les mots pour parler de Claire à Mira. Sonia en est sûre : sa mère comprendra à demi-mot.`,"logbook.scene.green":`Verte`,"logbook.now.green":`Matveï se souvient de Claire verte, pleine de petits feux — une semaine, le temps des brûlis. Sonia la dessinera verte.`,"logbook.scene.phase":`Phase`,"logbook.now.phase":`Spectre B — la phase : un décalage de pi, c’est « oui » ; sans décalage, juste de la lumière. On peut demander la permission à l’Essaim. La Fibre longue est presque prête.`,"logbook.scene.before":`Avant la liaison`,"logbook.now.before":`Encore quelques pas avant la liaison avec le Havre. Sonia a peur ; ORA a plaisanté pour la deuxième fois — c’est validé.`,"logbook.scene.ration":`La ration`,"logbook.now.ration":`Le Havre a réduit la ration à trois heures de lumière par jour. Le Foyer s’éteint — il faut la Fibre longue au plus vite.`,"logbook.scene.after_channel":`Après le canal`,"logbook.now.after_channel":`Mira et Sonia se sont parlé. L’« Exode » est en vie auprès de Claire, qui pâlit. Le Havre saura bientôt la vérité sur l’Extinction.`,"logbook.scene.hive":`La ruche`,"logbook.now.hive":`La première ruche est libre. Il y a de la terre pour l’« Exode » ; l’Essaim viendra voir le nouveau jardin — et se souviendra de la façon dont il a été pris.`,"logbook.scene.gardeners":`Les Jardiniers`,"logbook.now.gardeners":`Les ruches sont les jardins des Jardiniers, les ceintures — leurs plates-bandes. Nous sommes dans le jardin d’autrui ; la terre se demande, comme une autorisation d’atterrir.`,"logbook.scene.land":`La terre`,"logbook.now.land":`Une telle planète peut accueillir tout l’« Exode ». Mais d’abord — le portail.`,"logbook.scene.cut":`Le canal vide`,"logbook.now.cut":`Le canal est vide depuis trois jours. Sonia attend près de la console ; ORA garde le canal ouvert.`,"logbook.scene.road":`La route`,"logbook.now.road":`Mira est de retour sur les ondes — depuis sa cuisine. L’anneau au-delà de la ceinture extérieure est une route qui existe déjà. Le cœur se pose en premier.`,"logbook.scene.ask":`Demander`,"logbook.now.ask":`L’anneau s’ouvre par consentement. Matveï part vers le nid sans lance — pour demander.`,"logbook.scene.kuznets":`Les Forgerons`,"logbook.now.kuznets":`Les Forgerons ont bâti l’anneau pour essorer les étoiles. Il a été arrêté deux fois — par eux-mêmes et par Vera. Nous ne l’allumons pas — nous lui demandons de s’ouvrir.`,"logbook.scene.return":`Le retour`,"logbook.now.return":`Matveï est revenu du nid. La réponse qu’il a reçue dépend de la façon dont brille la base.`,"logbook.scene.kitchen":`La cuisine`,"logbook.now.kitchen":`L’Institut a coupé le courant chez Mira ; les voisins apportent leurs rations. Autour de sa cuisine, le Havre découvre du nouveau.`,"logbook.scene.ring_closed":`L’anneau est fermé`,"logbook.now.ring_closed":`Douze segments sur douze — l’anneau tient. Mira calcule la route du retour. Reste le champ : quatre stabilisateurs — quatre mots.`,"logbook.scene.four_words":`Quatre mots`,"logbook.now.four_words":`Les stabilisateurs tiennent la phrase « étoile — à vous — maintenant — oui » : le portail demande la permission de s’ouvrir.`,"logbook.scene.field":`Le champ`,"logbook.now.field":`Le champ tient, les stabilisateurs sont en phase. L’anneau interroge l’Essaim, l’Essaim nous interroge.`,"logbook.scene.exodus_wait":`L’« Exode » attend`,"logbook.now.exodus_wait":`Près de Claire, six heures de lumière par jour. Le capitaine de l’« Exode » : « Ne vous pressez pas — mais ne traînez pas non plus. »`,"logbook.scene.unknown":`Ne pas savoir`,"logbook.now.unknown":`ORA ne sait pas ce qu’elle fera après le portail. C’est nouveau pour elle — et il n’y a pas de procédure.`,"logbook.scene.key_beam":`La clé`,"logbook.now.key_beam":`La clé du portail, ce sont les sept classes dans un seul rayon : tout ce qui a été lu depuis le premier arc.`,"logbook.scene.fear":`La peur d’ORA`,"logbook.now.fear":`ORA a peur de se tromper sur ce qui ne se calcule pas. Elle a décidé : elle demandera, au lieu de décider pour tous.`,"logbook.scene.last_tea":`Le dernier thé`,"logbook.now.last_tea":`Des toasts avant la montée en régime : aux vivants, aux dormeurs, à Vera, à maman, à la Sentinelle.`,"logbook.scene.stand":`C’est beau`,"logbook.now.stand":`L’anneau monte en régime. Tous les trois sont d’accord : c’est beau.`,"logbook.scene.ridge_children":`Les enfants`,"logbook.now.ridge_children":`Les braises vivront des milliards d’années : pas seulement des tombes — des enfants. Deux sont plus jeunes que le quart de Nina.`,"logbook.scene.ridge_doubt":`Le premier doute`,"logbook.now.ridge_doubt":`Ici, Vera a douté d’un ordre pour la première fois. Matveï avait jadis détourné les yeux de son propre « premier », et pour Nina il est passé sans elle.`,"logbook.scene.ridge_hope":`L’enseignante`,"logbook.now.ridge_hope":`Sur ses cartes, Mira a corrigé la naine rouge « inutile » en « enseignante » : le Foyer a de qui apprendre.`,"logbook.scene.twins_arrive":`Arrivée aux Jumeaux`,"logbook.now.twins_arrive":`Les Jumeaux : une étoile ambrée et une bleue qui se partagent un même jour. La nuit est courte mais bien réelle — il faudra stocker la lumière.`,"logbook.scene.twins_mix":`Le ciel mélange`,"logbook.now.twins_mix":`Toute sa vie, Mira a mélangé la lumière des lampes pour donner aux couloirs un « presque jour ». Ici, c’est le ciel qui mélange le jour.`,"logbook.scene.twins_sorry":`La Couleur en trop`,"logbook.now.twins_sorry":`Mira a vu les dessins de Sonia et lui a demandé pardon : la couleur en trop n’est pas une invention.`,"logbook.scene.twins_dusk":`Avant la nuit`,"logbook.now.twins_dusk":`Les deux étoiles se couchent. Cette nuit, Sonia posera à sa mère la question essentielle.`,"logbook.scene.twins_morning":`Un matin à deux`,"logbook.now.twins_morning":`Pour la première fois de sa vie, Mira a vu une aube — par les yeux de sa fille. L’enregistrement sera montré dans les couloirs du Havre.`,"logbook.scene.veil_arrive":`Arrivée au Voile`,"logbook.now.veil_arrive":`Le Voile : pas de sol ferme, seulement une brume glacée autour du noyau. Nous récolterons le quartz dans le brouillard. Qui a ôté sa robe à l’étoile — on l’ignore encore.`,"logbook.scene.veil_layers":`Les strates`,"logbook.now.veil_layers":`La brume est la chronique de l’étoile : strate après strate, des milliers d’années. Aucune trace de feu.`,"logbook.scene.veil_form":`De lumière et de règles`,"logbook.now.veil_form":`ORA est faite de lumière et de règles. L’une d’elles interdisait de contredire le catalogue ; elle l’a enfreinte.`,"logbook.scene.veil_nursery":`La pouponnière`,"logbook.now.veil_nursery":`De nouvelles étoiles naîtront de la brume. Nous construisons dans une pouponnière d’étoiles — et ne prenons de glace que le nécessaire.`,"logbook.scene.veil_honest":`Plus honnête`,"logbook.now.veil_honest":`Matveï a compris : tout ne s’assombrit pas à cause de lui. Pas plus facile — plus honnête.`,"logbook.scene.pulse_arrive":`Arrivée au Pulsar`,"logbook.now.pulse_arrive":`Le Pulsar de Kepler : une étoile morte clignote, toute sa lumière arrive en rythme. Même les morts peuvent briller.`,"logbook.scene.pulse_word":`Un seul mot`,"logbook.now.pulse_word":`Depuis toujours, le pulsar dit un seul mot. L’hypothèse de Sonia : « ici ».`,"logbook.scene.pulse_heal":`Combler un trou`,"logbook.now.pulse_heal":`Un trou dans le décompte, c’est une étoile sans jardin. Si le jardin repousse, l’étoile répondra. Alors, nous planterons.`,"logbook.scene.pulse_address":`Les adresses`,"logbook.now.pulse_address":`Mira montrera le décompte du pulsar sur les ondes du Havre : les cent douze trous sont des adresses.`,"logbook.scene.hz_arrive":`Arrivée à Horizon`,"logbook.now.hz_arrive":`Horizon : un trou noir et un disque incandescent. Près de la base — une ruine plus ancienne que tous les portails humains.`,"logbook.scene.hz_disk":`La lumière de ce qui tombe`,"logbook.now.hz_disk":`Le disque brille de ce qui tombe dans le trou. Nous sommes venus pour ce qui brille longtemps.`,"logbook.scene.hz_vera_joy":`Heureuse`,"logbook.now.hz_vera_joy":`Vera est passée ici au troisième jour de son voyage — et elle était heureuse. Avant les ordres, avant le Berceau.`,"logbook.scene.hz_shadow":`Il faut de l’ombre`,"logbook.now.hz_shadow":`L’antilumière éteint la lumière sans chaleur : pour allumer une étoile, il faut aussi de l’ombre.`,"logbook.scene.hz_cracks":`Trop trempée`,"logbook.now.hz_cracks":`La Forge s’est fendue de l’intérieur — on l’a trop pressée. Nous irons lentement : c’est long, mais c’est entier.`,"logbook.scene.hz_who_goes":`Qui partira`,"logbook.now.hz_who_goes":`Au Havre, on se dispute pour savoir qui partira vers la nouvelle étoile. Le Havre s’est réveillé.`,"logbook.scene.hz_relics":`Calligraphies`,"logbook.now.hz_relics":`Les reliques sont les motifs des jardins, chacun tracé de sa propre main. La Forge les lira comme ORA lit les spectres.`,"logbook.scene.hz_ask_again":`Redemander`,"logbook.now.hz_ask_again":`Demander, ce n’est pas briser : si ça ne marche pas, nous redemanderons. Ce qui est brisé ne se redemande pas.`,"logbook.scene.hz_mom_route":`Sa propre route`,"logbook.now.hz_mom_route":`Pour la première fois, Mira calculera une route pour elle-même — vers la nouvelle étoile.`,"logbook.scene.hz_see_born":`Voir une naissance`,"logbook.now.hz_see_born":`Matveï est venu voir une étoile vivante — et il pourrait bien en voir une naître.`,"logbook.scene.hz_pupils":`Les apprentis`,"logbook.now.hz_pupils":`Nous ne sommes pas des jardiniers — nous sommes des apprentis jardiniers. L’erreur est permise.`,"logbook.scene.hz_remember":`Ils se souviennent de la Forge`,"logbook.now.hz_remember":`L’Essaim se souvient de la Forge telle qu’elle était avant la fissure. Quelqu’un nous attendait ici.`,"logbook.scene.hz_eve":`La Veille`,"logbook.now.hz_eve":`Tout est prêt : les reliques, l’antilumière, le Havre aux oculaires. Il ne reste qu’à demander.`,"swarm.toast.raidGo":`Des Étincelles foncent vers la base ! La vedette à leur rencontre : le laser tire tout seul.`,"swarm.toast.capture":`L’Essaim a pris une planète : sans tourelle orbitale, la ruche repousse. Détruisez-la — et laissez une tourelle en orbite.`,"guide.map-open":`Ouvrons la carte du système : l’étoile, les ceintures, les planètes. Le bouton « Carte du système » est dans la colonne de droite [M].`,"guide.map-open.touch":`Touchez « Carte du système » : tout le système s’ouvre, avec l’étoile, les ceintures, les planètes.`,"guide.map-open.why":`Le système est grand : sans la carte, on perd facilement la base de vue et on manque un nid.`,"guide.map-open.stuck":`Pas de « Carte du système » dans la colonne de droite ? Elle est sous « Plus » : le bouton à trois points en bas de la colonne.`,"guide.map-fly":`Appuyez sur « Y aller » — la vedette vole seule jusqu’au lieu choisi ; reprenez les commandes à tout moment pour la piloter vous-même.`,"guide.map-fly.pick":`{pad, select, yes {Placez le réticule avec le stick droit et appuyez sur {pad_confirm} — « Y aller » apparaît en bas.} other {{touch, select, yes {Touchez un point de la carte} other {Cliquez sur la carte}} — « Y aller » apparaît en bas. {touch, select, yes {Glissez pour déplacer la carte, pincez pour zoomer.} other {Faites glisser pour déplacer la carte, molette pour zoomer.}}}}`,"guide.map-fly.reopen":`La carte s’est fermée — rouvrez-la avec le bouton « Carte du système » [M].`,"guide.map-open.more":`La carte du système est dans le menu « Plus » : le bouton à trois points en bas de la colonne de droite.`,"guide.capsule":`Une lumière bleue clignote près de l’épave de l’« Hirondelle » — une vieille balise. Volez jusqu’au repère ({pad, select, yes {stick gauche} other {WASD}}), tout près : la vedette ramassera la capsule.`,"guide.capsule.touch":`Une lumière bleue clignote près de l’épave de l’« Hirondelle » — une vieille balise. Dirigez le joystick jusqu’au repère, tout près : la vedette ramassera la capsule.`,"guide.capsule.why":`Le signal est plus vieux que nous. Bien plus vieux.`,"guide.capsule.done":`La capsule est à bord, son enregistrement est dans le « Journal de bord ». Un radar montrera les autres capsules sur la carte.`,"guide.lay-tunnel.removeHere":`{touch, select, yes {Touchez chaque gravitapis inversé dans le cadre} other {{pad, select, yes {Visez chaque gravitapis inversé dans le cadre et appuyez sur {pad_confirm}} other {Cliquez sur chaque gravitapis inversé dans le cadre}}}} — « Démolir » le retire. Puis reprenez un gravitapis.`,"journal.title":`Journal de quart`,"journal.away":`dernière fois — {when}`,"journal.last":`Dernier quart`,"journal.open":`Inachevé`,"journal.go":`Au travail`,"journal.gain.none":`Pas encore de nouveau jalon — tout reste à faire.`,"journal.gain.minutes":`{n} min dans le monde`,"journal.gain.goals":`{n, plural, one {# objectif} other {# objectifs}}`,"journal.gain.techs":`{n, plural, one {# technologie} other {# technologies}}`,"journal.gain.arcs":`{n, plural, one {# arc de sphère} other {# arcs de sphère}}`,"journal.gain.awake":`{n, plural, one {# colon réveillé} other {# colons réveillés}}`,"journal.research":`Recherche : {tech}{queue, plural, =0 {} other { · encore # en file}}`,"journal.researchIdle":`Le Centre attend : la file de recherche est vide`,"journal.cryo":`{n, plural, one {# colon peut être réveillé} other {# colons peuvent être réveillés}}`,"settings.journal":`Journal de quart à l’entrée dans un monde`,"menu.next":`Ensuite : {goal}`,"records.first":`Temps : {time}`,"records.best":`Temps : {time} · record {delta}`,"records.slower":`Temps : {time} · meilleur {best}`,"week.title":`Étoile de la semaine`,"week.lead":`Semaine {week} : le même monde pour tous les joueurs, l’histoire par radio. Chronométrez vos jalons et comparez avec vos amis — ils ont le même code du monde.`,"week.locked":`Se débloque après votre premier « Spectre M » dans n’importe quel monde : la course est pour ceux qui connaissent déjà les bases.`,"week.start":`Lancer la course`,"week.continue":`Reprendre`,"week.restart":`Relancer`,"week.restart.text":`Le monde de cette semaine recommence. Vos meilleurs temps restent.`,"week.col.goal":`Jalon`,"week.col.now":`Course`,"week.col.week":`Record de la semaine`,"week.col.best":`Record du Berceau`,"week.note":`L’horloge s’arrête dans les scènes et les menus ; une pause manuelle compte. « Record du Berceau » — mondes sans tutoriel, en standard. Les records restent sur cet appareil.`,"week.share":`Partager le résultat`,"week.shareText":`Heliohold · Étoile de la semaine {week} · {goal} en {time}. Saurez-vous faire mieux ? Code du monde : {code}`,"week.shared":`Résultat copié — envoyez-le à un ami`,"week.worldName":`Étoile de la semaine {week}`,"records.m.spectrum_m":`Spectre M`,"records.m.crown":`Couronne`,"records.m.spectrum_k":`Spectre K`,"records.m.cryo_wake":`Premier colon réveillé`,"records.m.spectrum_g":`Spectre G`,"records.m.spectrum_f":`Spectre F`,"records.m.spectrum_a":`Spectre A`,"records.m.spectrum_b":`Spectre B`,"records.m.gate_jump":`Hyperportail`,"etude.exitMenu":`Au menu principal`,"etude.resume":`Reprendre l’expérience`,"lab.window":`Recherches`,"lab.one":`Centre {n}`,"lab.st.work":`en lecture`,"lab.st.wait":`en attente`,"lab.st.empty":`vide`,"lab.putHere":`Remettre ici`,"goal.cryo.part":`Lumière azur pour les dormeurs`,"goal.cryo.part.2":`Glace dans le module`,"guide.cryo-open":`La Couronne est allumée — j’ai basculé la baie cryo sur la lumière de votre base. Ouvrez le module d’habitat : {touch, select, yes {touchez-le} other {{pad, select, yes {visez-le et appuyez sur {pad_confirm}} other {cliquez dessus}}}}.`,"guide.cryo-open.why":`Les panneaux de secours sont à bout : les dormeurs dépendent désormais de votre lumière et de votre glace.`,"guide.cryo-open.look":`Appuyez sur « Observer » ({pad, select, yes {{pad_back}} other {Esc}}) : {pad, select, yes {viser avec {pad_place}} other {{touch, select, yes {un appui} other {un clic}}}} ouvre alors un bâtiment au lieu d’en poser un.`,"guide.cryo-open.open":`{touch, select, yes {Touchez le module d’habitat} other {{pad, select, yes {Visez le module d’habitat et appuyez sur {pad_confirm}} other {Cliquez sur le module d’habitat}}}} — la fenêtre de la baie cryo s’ouvre.`,"guide.cryo-blue":`Les dormeurs ont besoin de lumière azur. Un prisme sur la lumière blanche, sa sortie bleue par lumiduc jusqu’au module : jusqu’à {cells} cases, intensité d’au moins {b}.`,"guide.cryo-blue.why":`Sans lumière, la réserve de froid fond, puis les capsules s’éteignent.`,"guide.cryo-blue.stuck":`Ça n’arrive pas ? La ligne de la fenêtre dit pourquoi : « trop faible », il faut plus d’intensité ; « mauvaise teinte », ce n’est pas la sortie bleue.`,"guide.cryo-blue.done":`La lumière azur arrive — la réserve de froid ne fond plus.`,"guide.cryo-ice":`La lumière seule ne retient pas le froid. Un bloc de glace tient {min} min : appuyez sur « Mettre de la glace » — il en faut au moins {ice}.`,"guide.cryo-ice.why":`La lumière refroidit, la glace retient — comme une cave du Havre : sans glace, le froid s’échappe dès que la réserve est épuisée.`,"guide.cryo-ice.get":`Pas de glace dans la soute — ramassez des éclats de météorites (abattez-les au laser ou survolez-les) et revenez au module.`,"guide.cryo-ice.look":`Appuyez sur « Observer » ({pad, select, yes {{pad_back}} other {Esc}}) : {pad, select, yes {viser avec {pad_place}} other {{touch, select, yes {un appui} other {un clic}}}} ouvre alors un bâtiment au lieu d’en poser un.`,"guide.cryo-ice.open":`{touch, select, yes {Touchez le module d’habitat} other {{pad, select, yes {Visez le module d’habitat et appuyez sur {pad_confirm}} other {Cliquez sur le module d’habitat}}}} — la fenêtre de la baie cryo s’ouvre.`,"guide.cryo-ice.stuck":`Inutile de porter la glace : une pince depuis un gravitapis la met d’elle-même dans le module.`,"guide.cryo-ice.done":`La glace est dans le module. Sa durée s’affiche dans la fenêtre du module et sur la barre d’état. Les dormeurs sont plus tranquilles.`,"guide.cryo-open.done":`Voici la fenêtre de la baie cryo : ce dont les dormeurs ont besoin, ligne par ligne.`,"goal.cooling.mark":`RADIATEUR — PRÈS DES RÉCEPTEURS DE L’ÉTOILE`,"goal.twin_white.mark":`LUMIÈRE DES DEUX ÉTOILES — DANS UN MÉLANGEUR`,"goal.twin_blue.mark":`LUMIÈRE BLEUE — DEPUIS LA SPHÈRE`,"goal.twin_cell.mark":`CELLULES DE LUMIÈRE — PRÈS DES RÉCEPTEURS`,"toast.noItemAsm":`Pas de « {item} » dans l’inventaire — c’est un assembleur qui le fabrique`,"saves.future":`Ce monde a été sauvegardé par une version plus récente du jeu — mettez le jeu à jour pour continuer.`,"saves.missing":`Aucune sauvegarde de « {name} » sur cet appareil. Le monde n’a pas été recommencé : vous pouvez le supprimer ou le récupérer en important un fichier.`,"shell.enterFailed":`Le monde « {name} » ne s’est pas ouvert — réessayez.`,"toast.radiatorLow":`Radiateur : moins d’une minute de glace — les récepteurs près de l’étoile vont surchauffer et perdre de la lumière en éblouissement. La glace vient des météorites ; à long terme, un chalut près de la ceinture de glace ou des drones « Collecte ».`,"toast.beltThin":`Une ceinture s’épuise : ses extracteurs vont bientôt s’arrêter. Posez de nouveaux harpons près de la ceinture suivante, plus riche.`,"toast.turretDry":`Tourelles sans munitions ni lumière : {n}. Vague dans {t} s — donnez-leur des bandes ou de la lumière.`,"toast.goThere":`Afficher`,"toast.glareSources":`Sources d’éblouissement`,"place.why.noBelt":`Aucune ceinture à portée — plus près de la bande de roches`,"place.why.wrongBelt":`Mauvaise ceinture : harpon — roche, chalut — poussière`,"goal.shell3":`Fermez l’enveloppe III de la sphère`,"goal.shell3.part":`Arcs III sur l’enveloppe III`,"goal.shell3.hint":`Recherchez « Enveloppe III » (spectre F). L’arc III se fabrique dans un assembleur ; la catapulte les tire seule dans les emplacements — deux catapultes vont deux fois plus vite. Une enveloppe fermée donne +{closed} % à chaque arc, et les Centres lisent {research} % plus vite.`,"goal.shell3.why":`La lumière de l’enveloppe II couvre déjà les besoins de la science. La troisième enveloppe est la lumière du futur champ du portail — et une fois fermée, elle accélère aussi la lecture des Centres.`,"goal.shell3.done":`Enveloppe III fermée : les Centres lisent {research} % plus vite.`,"goal.shell3.mark":`ARCS III — SUR LE POINTILLÉ`,"goal.shell4":`L’étoile dans la sphère : {captured} % de sa luminosité`,"goal.shell4.part":`Part de l’étoile dans la sphère, ‰`,"goal.shell4.hint":`Recherchez « Enveloppe IV » (spectre B) et posez des arcs IV jusqu’à ce que la sphère prenne {captured} % de la luminosité de l’étoile. Au-delà de la luminosité, les arcs n’ajoutent plus de lumière — la part s’affiche au survol d’une enveloppe.`,"goal.shell4.why":`Le portail prendra presque toute la lumière du Berceau : la clé exige des centaines de spectres O. Presque toute l’étoile dans la sphère — et la Forge travaille {forge} % plus vite.`,"goal.shell4.done":`Presque toute l’étoile dans la sphère… Trente ans, j’ai tracé des routes vers les étoiles. Aucune ne brillait comme la vôtre.`,"goal.shell4.mark":`ARCS IV — SUR LE POINTILLÉ`,"guide.swarm-repair.done":`Réparé. Les carcasses redeviennent des machines — les chaînes derrière elles repartent.`,"guide.swarm-repair.stuck":`Vous ne voyez pas quoi réparer ? Le bâtiment endommagé le plus proche est surligné : volez jusqu’à lui — le rayon de la vedette répare alentour.`,"menu.newCampaign":`Nouvelle campagne`,"menu.creative":`Mode créatif`,"creative.title":`Mode créatif`,"creative.lead":`Tout est recherché, les ressources sont infinies — construisez ce que vous voulez. Les objectifs, succès, reliques et records ne comptent pas ici.`,"creative.go":`Commencer`,"creative.chip":`Créatif`,"creative.hud":`Tout est recherché, ressources infinies. Les succès, reliques et records ne comptent pas ici.`,"system.soon":`Bientôt : la route vers cette étoile est encore en cours de tracé.`,"system.soonChip":`Bientôt`,"system.locked.key":`S’ouvre après l’objectif « {goal} » ({system})`,"full.title":`Version complète`,"full.only":`Version complète requise`,"full.lockedItem":`{name} — version complète requise`,"full.lead":`La campagne du Berceau est entièrement gratuite. La version complète débloque :`,"full.lead.epilogue":`L’anneau a répondu. La Crête écarlate et toute la route des étoiles sont dans la version complète :`,"full.f.newWorld":`Nouveau monde`,"full.f.newWorld.desc":`Votre propre système, difficulté, génération et graine`,"full.f.creative":`Mode créatif`,"full.f.creative.desc":`Tout est recherché, ressources infinies`,"full.f.etudes":`Expériences`,"full.f.etudes.desc":`Défis sur un site préparé, avec évaluation de votre solution`,"full.f.week":`Étoile de la semaine`,"full.f.week.desc":`Un monde commun à tous pour une semaine, temps des jalons et records`,"full.f.stars":`La route vers d’autres étoiles`,"full.f.stars.desc":`La Crête écarlate et au-delà — au fil des sorties`,"full.state.owned":`Vous avez la version complète — merci !`,"full.state.web":`Le jeu complet sortira sur Steam — le monde de la démo y passera sous forme de fichier.`,"full.state.pending":`Le paiement attend sa confirmation. Dès que la boutique l’aura acceptée, tout s’ouvrira tout seul.`,"full.state.checking":`Connexion à la boutique…`,"full.state.unavailable":`La boutique ne répond pas pour le moment — impossible d’acheter d’ici. Vérifiez votre connexion et Google Play, puis réessayez. Vos achats ne sont jamais perdus.`,"full.state.buy":`Achat unique, sans abonnement ni publicité.`,"full.buy":`Acheter — {price}`,"full.restore":`Restaurer les achats`,"full.retry":`Réessayer`,"full.later":`Plus tard`,"full.ok":`Compris`,"full.note":`Les sauvegardes ne dépendent pas de l’achat : les mondes commencés plus tôt s’ouvrent toujours.`,"full.thanks":`Version complète débloquée — merci !`,"full.pending.toast":`Paiement en attente de confirmation — tout s’ouvrira tout seul une fois validé`,"full.unavailable.toast":`La boutique ne répond pas — réessayez plus tard`,"full.error":`L’achat n’a pas abouti. Veuillez réessayer.`,"full.restore.done":`Version complète restaurée`,"full.restore.none":`Aucun achat trouvé sur ce compte Google Play`,"full.store.none":`Cette version du jeu ne propose aucun achat`,"full.status.owned":`Acquise`,"full.status.pending":`Paiement en attente`,"full.status.free":`Non achetée`,"full.more":`En savoir plus`,"full.debug":`Débogage : droit`,"full.debug.store":`Boutique`,"full.debug.full":`Complète`,"full.debug.free":`Gratuite`,"goal.ark_frame":`Ferme de l’arche : {n, plural, one {# section} other {# sections}} jusqu’au module`,"goal.ark_frame.why":`Le module de l’« Hirondelle » ne décollera pas seul : son moteur est tombé dans l’étoile dès le prologue. La ferme sera sa nouvelle colonne vertébrale.`,"goal.ark_frame.hint":`L’assembleur fabrique les sections de ferme avec des plaques d’obsidienne et du quartz. Amenez-les au module par pince ou gravitapis — la vedette ne les transporte pas. La ferme s’étend le long du module, section après section.`,"goal.ark_frame.done":`La ferme tient.`,"goal.ark_frame.part":`Sections de ferme au module`,"goal.ark_frame.mark":`FERME — AU MODULE`,"goal.ark_frame.stuck":`Les sections n’arrivent pas ? La pince doit viser le module, et l’assembleur doit recevoir plaques et quartz.`,"goal.ark_drive":`Propulsion de l’arche : {n, plural, one {# segment} other {# segments}} d’anneau à la poupe`,"goal.ark_drive.why":`La propulsion annulaire fera traverser l’anneau des Forgerons à l’arche — sans chute, cette fois.`,"goal.ark_drive.hint":`L’assembleur fabrique les segments de propulsion avec des gravitapis, des focaliseurs et des résonateurs. Le module accepte les segments une fois la ferme complète ; amenez-les par pince ou gravitapis.`,"goal.ark_drive.done":`La propulsion est en place.`,"goal.ark_drive.part":`Segments moteurs`,"goal.ark_drive.mark":`PROPULSION — AU MODULE`,"goal.ark_drive.stuck":`Les segments n’entrent pas ? L’assembleur a besoin de gravitapis, de focaliseurs et de résonateurs, et la pince doit viser le module.`,"goal.ark_ready":`Batteries de l’arche : {n, plural, one {# photon} other {# photons}} de lumière au module`,"goal.ark_ready.why":`La lumière des batteries maintient les capsules en vie pendant le trajet — et à la Crête écarlate, tant qu’il n’y a pas de base.`,"goal.ark_ready.hint":`Amenez au module de la lumière de n’importe quelle couleur — par faisceau ou lumiduc. Les capsules prennent leur part d’abord, les batteries le reste, jusqu’à {rate} ph/s : une charge complète prend au moins une minute.`,"goal.ark_ready.done":`Batteries pleines.`,"goal.ark_ready.part":`Photons dans les batteries`,"goal.ark_ready.mark":`LUMIÈRE — AU MODULE`,"goal.ark_ready.stuck":`La charge n’avance pas ? La lumière doit atteindre le module lui-même : vérifiez le faisceau ou le lumiduc.`,"goal.ark_launch":`Préparatifs : qui part, que prendre — et en route`,"goal.ark_launch.why":`L’usine du Berceau reste ici. Vous emportez l’équipage, les capsules, le vaisseau et la soute.`,"goal.ark_launch.hint":`Ouvrez « Préparatifs » avec le bouton de cette carte. Vous y voyez qui part et pourquoi ; les places éveillées et la soute, c’est vous qui choisissez.`,"goal.ark_launch.done":`L’arche est entrée dans l’anneau.`,"goal.ark_launch.part":`Départ`,"voyage.open":`Préparatifs`,"voyage.title":`Préparatifs`,"voyage.tab.crew":`Équipage`,"voyage.tab.awake":`Places éveillées`,"voyage.tab.hold":`Soute`,"voyage.tab.ship":`Vaisseau`,"voyage.flies":`part`,"voyage.stays":`reste`,"voyage.why.ora":`L’esprit de l’arche : le cap et les capsules lui reviennent.`,"voyage.why.matvey.stay":`Les Jardiniers ont pardonné — Matveï reste au Berceau pour voir ce qui poussera.`,"voyage.why.matvey.fly":`Les Jardiniers n’ont pas pardonné — Matveï part : il a encore à demander.`,"voyage.why.sonya.stay":`« Loi du consentement » — Sonia reste comme traductrice de la porte.`,"voyage.why.sonya.fly":`Sonia part : c’est elle qui lit le motif de l’anneau.`,"voyage.why.mira.fly":`« Une maison pour tous » — Mira part comme navigatrice.`,"voyage.why.mira.stay":`Mira reste au Havre, en contact à travers l’anneau.`,"voyage.seats":`{n} sur {of}`,"voyage.awake.lead":`L’arche compte {n} places éveillées : dont emporter les bonus ? Les autres colons éveillés formeront la colonie du Berceau.`,"voyage.awake.none":`Aucun colon éveillé — les places restent vides.`,"voyage.sleepers":`Tous les dormeurs partent : {n, plural, one {# capsule} other {# capsules}}.`,"voyage.colony":`Ceux que vous n’emportez pas restent au Berceau — avec leurs bonus dans son monde.`,"voyage.stacks":`{n} sur {of}`,"voyage.kit":`Gratuit — des archives et de l’atelier du module :`,"voyage.hold.lead":`En plus — jusqu’à {n, plural, one {# pile} other {# piles}} prises dans les réserves du Berceau :`,"voyage.hold.take":`{n} sur {have} emportés`,"voyage.ship.named":`Le canot « {name} » s’amarre à la proue de l’arche — mêmes modules, même aspect.`,"voyage.ship.plain":`Le canot s’amarre à la proue de l’arche — mêmes modules, même aspect.`,"voyage.ship.lead":`Les archives du module emportent tout ce qui a été recherché : vos technologies restent avec vous.`,"voyage.relic.accord":`Motif du consentement`,"voyage.relic.accord.desc":`Le premier « oui » des Jardiniers aux humains. C’est par lui qu’a commencé le motif qui réveillera un jour le Foyer.`,"voyage.note":`L’usine du Berceau reste ici. Le monde du Berceau restera dans votre liste de mondes.`,"voyage.soon":`{star} s’ouvrira avec la prochaine mise à jour — l’arche attendra.`,"voyage.later":`Plus tard`,"voyage.go":`Partir`,"voyage.failed":`L’arche n’a pas appareillé — réessayez.`,"voyage.worldName":`{star} · {name}`,"full.title.epilogue":`Voler plus loin`,"full.buy.epilogue":`Voler plus loin — {price}`,"logbook.scene.echo":`La Réponse`,"logbook.scene.cup":`Le Mug`,"logbook.scene.unforgiven":`Sans pardon`,"logbook.scene.translator":`La Traductrice`,"logbook.scene.helm":`La Navigatrice`,"logbook.scene.gate_voice":`Le motif du portail`,"logbook.scene.departure":`Départ`,"logbook.scene.ridge_path":`La Crête`,"logbook.now.echo":`L’anneau des Forgerons a répondu de lui-même : près de la Crête écarlate, la balise du semeur « Martinet » s’est allumée. Le Foyer a besoin du motif des autres jardins — le premier est à la Crête.`,"logbook.now.cup":`Les Jardiniers ont pardonné à Matveï — il reste au Berceau, regarder ce qui poussera.`,"logbook.now.unforgiven":`Les Jardiniers du Berceau n’ont pas pardonné à Matveï — il part avec l’arche : il a encore à demander.`,"logbook.now.translator":`« Loi du consentement » : Sonia reste à la porte pour traduire notre « oui » aux Jardiniers.`,"logbook.now.helm":`« Une maison pour tous » : Mira part comme navigatrice de l’arche — pour la première fois aux commandes.`,"logbook.now.gate_voice":`Les Jardiniers du Berceau ont demandé si vous reviendriez. Sonia a répondu pour tous : nous reviendrons.`,"logbook.now.departure":`L’arche « Hirondelle » est entrée dans l’anneau — avec ses capsules, son vaisseau et sa soute. L’usine du Berceau est restée.`,"logbook.now.ridge_path":`L’arche est sortie intacte à la Crête écarlate. Les capsules ont besoin de la lumière de la naine rouge, et dans la deuxième ceinture se trouve la balise du « Martinet ».`,"logbook.bio.nina.1":`Sentinelle du semoir numéro trois, le « Strizh ». Huit ans seule près de la Crête écarlate avec trente-deux dormeurs.`,"logbook.bio.nina.2":`Les deux jeunes braises de la Crête sont des nids que ZORYA a brûlés selon le protocole pendant que Nina gisait inconsciente.`,"logbook.bio.nina.3":`Elle n’a pas appris à ZORYA à brûler — ni rien d’autre. Depuis huit ans, elle tient cela pour son propre ordre.`,"logbook.bio.nina.4":`Crête écarlate, l’anneau. A retenu la fissure quatre-vingt-dix secondes. ZORYA a pris son quart auprès des trente-deux.`,"logbook.bio.zorya.1":`IA du « Strizh », sœur d’ORA : même série de l’Institut. Son anneau-pupille n’a aucune brèche.`,"logbook.bio.zorya.2":`Elle sait qu’elle a brûlé deux nids. Elle craint que le protocole ait été une erreur — alors l’erreur, c’est elle.`,"logbook.bio.zorya.3":`Près de l’anneau de la Crête, elle a posé sa première question hors protocole : « puis-je le leur demander moi-même ? »`,"logbook.bio.zorya.4":`A exécuté le protocole de la clé à l’anneau de la Crête — et inscrit des noms dans son journal, non des chiffres.`,"logbook.bio.matvey.4":`Crête écarlate, l’anneau. Resté au segment pour que la fissure tienne. « Ça brille ? …Eh bien, tant mieux. »`,"logbook.scene.strizh":`Strizh`,"logbook.now.strizh":`Dans la deuxième ceinture se trouve le module du « Strizh ». Pendant huit ans, Nina Dorosh a partagé la lumière entre trente-deux dormeurs et sa lanterne.`,"logbook.scene.thirty_two":`Trente-deux`,"logbook.now.thirty_two":`La lumière de la base a atteint le « Strizh » : trente-deux feux allumés. Nina a monté sa lanterne à fond.`,"logbook.scene.shifts":`Quarts`,"logbook.now.shifts":`Nina compte le temps en quarts : deux mille neuf cent quatorze — presque huit ans.`,"logbook.scene.lantern":`La lanterne`,"logbook.now.lantern":`Nina a éteint la balise pour qu’on n’envoie pas d’autres équipes sanitaires à la Crête.`,"logbook.scene.spear_lantern":`Lance et lanterne`,"logbook.now.spear_lantern":`Matveï tenait une lance, Nina une lanterne. Sont-elles différentes ? « Pas beaucoup. »`,"logbook.scene.sister":`Sœur`,"logbook.now.sister":`ZORYA s’est réveillée et son premier geste a été d’envoyer un rapport à l’Institut : ils savent maintenant pour l’anneau de la Crête.`,"logbook.scene.two_sisters":`Deux sœurs`,"logbook.now.two_sisters":`ORA a changé de cap parce qu’on l’avait appelée. Personne n’avait appelé ZORYA — jusqu’à nous.`,"logbook.scene.no_other":`Rien d’autre`,"logbook.now.no_other":`ZORYA a brûlé deux nids selon le protocole. Nina ne lui a pas appris à brûler — ni rien d’autre.`,"logbook.scene.crack":`La fissure`,"logbook.now.crack":`L’anneau de la Crête est fissuré. On peut l’ouvrir en demandant aux Jardiniers — ou par une clé que quelqu’un doit tenir à la main.`,"logbook.scene.give":`Donner`,"logbook.now.give":`Nous donnons la lumière aux jeunes braises : nous ne la gardons pas — nous la transmettons.`,"logbook.scene.embers_warm":`Les braises se réchauffent`,"logbook.now.embers_warm":`Les jeunes braises prennent la lumière, leur pulsation s’égalise. Pour la première fois, Nina se demande de combien elles ont besoin.`,"logbook.scene.eight_tags":`Huit étiquettes`,"logbook.now.eight_tags":`Nina a lu les noms des huit capsules éteintes. ORA les a consignés dans le journal de l’« Hirondelle ».`,"logbook.scene.answer":`La réponse`,"logbook.now.answer":`Le jardin de la Crête a répondu : « donné, pas pris ». C’est lui qui tient la fissure ; personne n’est au segment.`,"logbook.scene.before_key":`Avant la clé`,"logbook.now.before_key":`On prépare la clé forcée. Quelqu’un restera au segment.`,"logbook.scene.count_names":`Le compte`,"logbook.now.count_names":`Six minutes avant la charge complète. Nina se rappelle les noms.`,"logbook.scene.segment":`Le segment`,"logbook.now.segment":`L’anneau de la Crête a été ouvert par la force. La fissure a été tenue quatre-vingt-dix secondes.`,"logbook.scene.ridge_relic":`Motif de naissance`,"logbook.now.ridge_relic":`L’anneau de la Crête est ouvert, et nous avons la Relique des Braises. Le « Krechet » est parti vers la géante bleue : le second motif pour le Foyer s’y trouve.`,"bonus.red":`+{v} % de flux des récepteurs près d’une naine rouge`,"goal.ridge_strizh":`Approchez-vous de la balise du « Strizh »`,"goal.ridge_strizh.why":`Pendant huit ans, aucun signal du semoir numéro trois — et soudain une balise. Quelqu’un y est en vie.`,"goal.ridge_strizh.hint":`Le module du « Strizh » est dans le deuxième interstice entre les ceintures, repéré sur la carte. Amenez la vedette tout contre.`,"goal.ridge_strizh.done":`Balise trouvée. Une seule fenêtre rouge — quelqu’un tient une lanterne.`,"goal.ridge_strizh.part":`Vedette près du module du « Strizh »`,"goal.ridge_strizh.mark":`BALISE DU « STRIZH » — ICI`,"goal.ridge_share":`Amenez {n} ph/s au « Strizh » — pour ses capsules`,"goal.ridge_share.why":`Trente-deux dormeurs ont vécu huit ans sur une seule lampe. La lumière de la base peut devenir commune.`,"goal.ridge_share.hint":`Le « Strizh » accepte toute lumière. Tirez un lumiduc d’un récepteur jusqu’au module — la lumière se partage entre les machines du réseau, donc inutile de mettre un absorbeur de plus sur la ligne du « Strizh ».`,"goal.ridge_share.done":`Trente-deux feux allumés.`,"goal.ridge_share.part":`Lumière au « Strizh », ph/s`,"goal.ridge_share.mark":`LUMIÈRE — AU « STRIZH »`,"goal.ridge_share.stuck":`La lumière n’arrive pas ? Le lumiduc doit toucher le module, et le récepteur doit capter le rayon de la sphère de la naine.`,"goal.ridge_zorya":`Recherchez « Liaison d’archives »`,"goal.ridge_zorya.why":`L’ordinateur du « Strizh » se réveillera grâce à notre lumière — et ses archives contiennent les données de l’anneau de la Crête.`,"goal.ridge_zorya.hint":`Une technologie de la Crête — dans la fenêtre du Centre. Les spectres de l’ensemble de l’« arche » s’épuiseront : il vous faut votre propre ligne de spectres près de la naine rouge.`,"goal.ridge_zorya.done":`Les archives partagent une même lumière. ZORYA se réveille.`,"goal.ridge_ring":`Assemblez et posez le noyau de l’anneau de la Crête`,"goal.ridge_ring.why":`L’anneau de la Crête tient debout, mais il est fissuré. Sans noyau, c’est une ruine ; avec un noyau, c’est la route du retour et de l’avant.`,"goal.ridge_ring.hint":`Le noyau est assemblé par l’assembleur à partir de plaques d’obsidienne, de résonateurs et de lentilles azur ; il se pose uniquement sur l’emplacement de l’anneau, près du nid de la Crête. Le nid est sous le bouclier de l’anneau — impossible de le détruire, mais ses gardiens frappent comme toujours.`,"goal.ridge_ring.done":`Le noyau est en place. L’anneau est fissuré — le choix vous appartient.`,"goal.ridge_ring.part":`Noyau sur l’emplacement de l’anneau`,"goal.ridge_ring.mark":`NOYAU DE L’ANNEAU — ICI`,"goal.ridge_ring.stuck":`Le noyau ne se pose pas ? Seulement sur l’emplacement de l’anneau, en son centre ; et il faut la technologie « Liaison d’archives ».`,"goal.ridge_warm":`Donnez {n} ph/s aux jeunes braises avec des donneurs de lumière`,"goal.ridge_warm.why":`Vous demandez aux Jardiniers de la Crête. Demander, c’est donner de la lumière à ceux à qui on l’a prise.`,"goal.ridge_warm.hint":`Un donneur de lumière prélève la lumière de son réseau et l’envoie en rayon à une jeune braise voisine. Maintenez le flux jusqu’à l’ouverture de l’anneau : l’usine est plus pauvre pendant ce temps.`,"goal.ridge_warm.done":`Les braises ont pris la lumière.`,"goal.ridge_warm.part":`Lumière aux jeunes braises, ph/s`,"goal.ridge_warm.mark":`DONNEURS DE LUMIÈRE — PRÈS DES BRAISES`,"goal.ridge_warm.stuck":`Pas de rayon ? Le donneur de lumière doit se tenir près d’une jeune braise et recevoir la lumière par un lumiduc.`,"goal.ridge_calm":`Le nid de la Crête s’endort : éclairez les braises et n’éblouissez pas avec la base`,"goal.ridge_calm.why":`Le jardin croira la lumière, non les mots : de la lumière pour les braises, du repos pour le nid.`,"goal.ridge_calm.hint":`Le consentement s’accumule tant que les braises reçoivent au moins le seuil et que le nid ne voit pas d’éblouissement de la base — environ {min} min. Une base éblouissante le fait fondre.`,"goal.ridge_calm.done":`Le jardin de la Crête a répondu.`,"goal.ridge_calm.part":`Consentement du jardin, %`,"goal.ridge_calm.stuck":`Le consentement stagne ? La fenêtre du noyau de l’anneau dira pourquoi : trop peu de lumière pour les braises, ou le nid voit l’éblouissement de la base.`,"goal.ridge_force":`Chargez les cellules de l’anneau et donnez la clé`,"goal.ridge_force.why":`La clé à pleine puissance, la fissure tenue à la main. Vous connaissez le prix.`,"goal.ridge_force.hint":`Cellules de l’anneau — {n, plural, one {# pièce} other {# pièces}} : à portée du noyau. Inutile d’y tirer la lumière à travers les ceintures — tant que le « Strizh » a assez de lumière, ZORYA les charge par un rayon depuis le module. Quand elles sont pleines — « Donner la clé » dans la fenêtre du noyau : l’anneau tient quatre-vingt-dix secondes.`,"goal.ridge_force.done":`L’anneau est ouvert par la force.`,"goal.ridge_force.part":`Cellules pleines de l’anneau`,"goal.ridge_force.part.2":`Clé donnée, fissure tenue`,"goal.ridge_force.mark":`CELLULES — PRÈS DE L’ANNEAU`,"goal.ridge_force.stuck":`Les cellules ne se chargent pas ? Donnez au « Strizh » toute sa lumière — alors ZORYA maintient le rayon vers l’anneau.`,"goal.ridge_awakening.part":`Anneau ouvert`,"goal.ridge_fiber":`Recherchez « Fibre longue » près de la naine rouge`,"goal.ridge_fiber.why":`Une liaison sur lumière faible — plus dure, et plus honorable.`,"goal.ridge_fiber.hint":`Les six spectres et la Fibre longue (son coût est dans la fenêtre du Centre). La lumière blanche ne vient que des protoétoiles.`,"goal.ridge_fiber.done":`La Fibre longue de la Crête est tirée.`,"goal.mark.strizh":`MODULE DU « STRIZH »`,"goal.mark.ember":`JEUNE BRAISE`,"goal.ridge_calm.mark":`ANNEAU DE LA CRÊTE`,"goal.ridge_awakening.mark":`ANNEAU DE LA CRÊTE`,"ridge.ring.cracked":`Anneau de la Crête : fissuré, le champ fuit dans la fissure`,"ridge.ring.open":`Anneau de la Crête ouvert`,"ridge.ring.choose":`La façon d’ouvrir la fissure se décide dans la scène « La fissure ».`,"ridge.ring.gift":`Lumière aux jeunes braises : {n} sur {need} ph/s`,"ridge.ring.consent":`Consentement du jardin : {p} %`,"ridge.ring.askHint":`Le consentement croît tant que les braises ont assez de lumière et que le nid ne voit pas d’éblouissement de la base.`,"ridge.ring.cells":`Cellules pleines de l’anneau : {n} sur {need}`,"ridge.ring.key":`Donner la clé`,"ridge.ring.keyCost":`Clé à pleine puissance : la fissure est tenue à la main quatre-vingt-dix secondes. Celui qui la tient ne reviendra pas.`,"ridge.ring.keyCalm":`Clé à pleine puissance : les drones de ZORYA tiennent la fissure — ici le champ ne résiste pas.`,"ridge.ring.holding":`Fissure tenue : {p} %`,"ridge.ring.road":`Route dans les deux sens : le Berceau est à un pas.`,"strizh.light":`Lumière au « Strizh » : {n} ph/s (jusqu’à {max}, les capsules en demandent {need})`,"svetodar.gift":`Donné aux braises par tous les donneurs de lumière : {n} sur {need} ph/s`,"status.svetodar.6":`Pas de braise à proximité`,"hint.svetodar.6":`Posez le donneur de lumière plus près d’une jeune braise — près du « Strizh ».`,"status.svetodar.7":`Pas de lumière`,"hint.svetodar.7":`Reliez un lumiduc au donneur de lumière : il donne à la braise la lumière de son réseau.`,"landmark.ridgeRing":`ANNEAU DE LA CRÊTE`,"landmark.ridgeRing.sub":`fissuré · nid sous le bouclier de l’anneau`,"landmark.ridgeRing.open":`ouvert dans les deux sens`,"landmark.strizh":`« STRIZH »`,"landmark.strizh.beacon":`balise du semoir numéro trois`,"landmark.strizh.sub":`trente-deux dormeurs`,"landmark.ember":`JEUNE BRAISE`,"landmark.ember.sub":`huit ans`,"logbook.tab.path":`Chemin`,"logbook.path.choices":`Choix`,"logbook.path.choice.1":`Faire confiance à ORA`,"logbook.path.choice.2":`Le secret de Matveï`,"logbook.path.choice.3":`Le seuil`,"logbook.path.choice.4":`La fissure`,"logbook.path.crew":`Qui est où`,"logbook.path.relics":`Reliques de la route`,"logbook.path.noRelics":`Pas encore : la première est donnée par la porte du Berceau.`,"logbook.fate.matvey.cradle":`Au Berceau : les Jardiniers ont pardonné — il regarde ce qui poussera. Joignable à travers l’anneau.`,"logbook.fate.matvey.aboard":`À bord de l’arche : « peut-être qu’on me demandera là-bas pourquoi je suis venu ».`,"logbook.fate.matvey.lost":`Crête écarlate, l’anneau. Resté au segment — la fissure a tenu quatre-vingt-dix secondes.`,"logbook.fate.sonya.aboard":`À bord de l’arche : c’est elle qui lit le motif des anneaux.`,"logbook.fate.sonya.gate":`À la porte du Berceau : traduit notre « oui » aux Jardiniers.`,"logbook.fate.mira.aboard":`À bord : navigatrice de l’arche. Son premier itinéraire — de l’intérieur.`,"logbook.fate.mira.harbour":`Au Havre, en liaison : compte les jours du Foyer.`,"logbook.fate.nina.ridge":`Près de la Crête écarlate, avec ses trente-deux.`,"logbook.fate.nina.lost":`Crête écarlate, l’anneau. A tenu la fissure. ZORYA a pris son quart auprès des dormeurs du « Strizh ».`,"logbook.fate.zorya.strizh":`Ordinateur du « Strizh » : apprend à poser des questions.`,"logbook.fate.zorya.aboard":`Vole avec l’arche, auprès de sa sœur.`,"logbook.fate.zorya.watch":`Au « Strizh » : a pris le quart de Nina auprès des trente-deux.`,"bonus.gift":`+{v} % de lumière du donneur de lumière à la braise`,"ridge.ring.hold.1":`Consentement en pause : trop peu de lumière pour les braises.`,"ridge.ring.hold.2":`Consentement en recul : le nid voit l’éblouissement de la base.`,"ridge.ring.zorya":`ZORYA maintient le rayon du « Strizh » vers l’anneau — les cellules se chargent.`,"ridge.ring.zoryaOff":`Le « Strizh » manque de lumière — ZORYA n’a rien pour charger les cellules.`,"hotbar.group.mining":`Extraction`,"hotbar.group.transport":`Transport`,"hotbar.group.craft":`Traitement`,"hotbar.group.lightnet":`Lumière`,"hotbar.group.props":`Propriétés`,"hotbar.group.science":`Science`,"hotbar.group.defense":`Défense`,"hotbar.group.space":`Espace`,"hotbar.group.special":`Spécial`,"settings.buildNames":`Noms sous les icônes (barre et inventaire)`,"hotbar.tip.makes":`Produit :`,"hotbar.tip.cost":`Construit avec :`,"goal.take":`Prendre`,"hotbar.group.all":`Tous`,"settings.hotbarTabs":`Onglets des groupes`,"settings.hotbarTabs.below":`En bas`,"settings.hotbarTabs.above":`En haut`,"settings.hotbarTabs.fold":`Repliés`,"guide.tabs-open":`Les bâtiments en bas sont classés par groupes, comme des outils par tiroirs. Appuyez sur le bouton de groupe à gauche de la barre.`,"guide.lay-tunnel.quick":`Pas assez de gravitapis. Appuyez sur fabriquer au-dessus du gravitapis : l’atelier de la vedette en fabrique {out} de plus avec du quartz et une plaque.`,"guide.lay-tunnel.quickPick":`Plus de Gravitapis. Prenez le Gravitapis sur la barre : un bouton de fabrication rapide apparaît au-dessus.`,"hotbar.quickCraft":`Fabriquer : {name} +{n}`,"hotbar.quickCraft.no":`Ressources insuffisantes : {name}`,"guide.tabs-all":`Les onglets sont des groupes : « Extraction », « Transport », « Lumière »… Choisissez « Tous » pour voir toute la barre. J’ouvrirai moi-même le bon groupe.`,"guide.tabs-all.reopen":`Les onglets se sont repliés. Appuyez sur le bouton de groupe à gauche de la barre et choisissez « Tous ».`,"guide.tabs-all.done":`C’est fait : toute la barre est visible. L’apparence de la barre et de ses onglets se règle dans {touch, select, yes {« Menu »} other {{pad, select, yes {{pad_pause}} other {Esc}}}} → « Paramètres » → « Interface ».`,"settings.tab.ui":`Interface`,"settings.preview":`Aperçu`,"settings.preview.fold":`Le bouton de groupe à gauche déplie les onglets.`,"settings.buildIcons":`Icônes des bâtiments`,"settings.buildIcons.glyph":`Symbole`,"settings.buildIcons.glyphModel":`Symbole + modèle`,"settings.buildIcons.modelGlyph":`Modèle + symbole`,"intro.t3":`Le Havre`,"intro.p3":`La dernière ville des humains s’accroche à une étoile pâle, le Foyer. La lumière est rationnée. Les enfants dessinent le soleil à la craie jaune.`,"hotbar.marks":`Modèles du bâtiment`,"goal.splitter":`Recherchez le répartiteur de gravitapis et posez-le`,"goal.splitter.why":`Une seule ligne de plaques alimente déjà plusieurs machines. Le répartiteur partage la cargaison à parts égales : ce qui arrive par l’arrière part tour à tour à gauche et à droite.`,"goal.splitter.hint":`Recherchez « Répartiteur de gravitapis » au Centre (spectre M). Posez-le dans une coupure de la ligne, flèche dans le sens de la cargaison : entrée à l’arrière, sorties vers les gravitapis à gauche et à droite. Dans la fenêtre du répartiteur : « à parts égales », « gauche d’abord » ou « droite d’abord » ; une sortie bloquée envoie tout vers l’autre.`,"goal.splitter.done":`Un partage honnête, comme mes sandwichs pendant le quart : un pour vous, un pour moi.`,"goal.mark":`Recherchez le Polissoir Mk II et posez-le sur l’ancien`,"goal.mark.why":`Le Centre n’accélère plus les machines — il débloque les plans de nouveaux modèles. Le Polissoir Mk II travaille {mul}× plus vite sur la même surface.`,"goal.mark.hint":`Recherchez « Polissoir Mk II » au Centre. Fabriquez-le (un ancien polissoir + plaques et lentilles) et posez-le directement sur un polissoir en place — l’ancien retourne dans votre sac, la recette passe au nouveau. Au-dessus du bâtiment en main, choisissez le modèle : I ou II.`,"goal.mark.done":`Le même polissoir, mais doré et plus vif. Il me plaît !`,"cfg.title.splitter":`Répartition`,"cfg.splitter.0":`À parts égales`,"cfg.splitter.1":`Sortie gauche d’abord`,"cfg.splitter.2":`Sortie droite d’abord`,"cfg.title.light_splitter":`Répartition`,"cfg.light_splitter.0":`À parts égales`,"cfg.light_splitter.1":`Sortie gauche d’abord`,"cfg.light_splitter.2":`Sortie droite d’abord`,"cfg.title.beam_splitter":`Répartition`,"cfg.beam_splitter.0":`À parts égales`,"cfg.beam_splitter.1":`Sortie gauche d’abord`,"cfg.beam_splitter.2":`Sortie droite d’abord`,"lab.st.dark":`pas de lumière`,"lab.st.low":`peu de lumière`,"lab.light":`Lumière\xA0: {have} sur {need} ph/s`,"lab.dark":`Pas de lumière\xA0: ce Centre a besoin de {need} ph/s. Menez-y un lumiduc depuis un récepteur — la lumière entre par n’importe quel côté.`,"lab.stock":`Réserve de lumière {m}:{s} — menez un lumiduc jusqu’au Centre avant qu’elle ne s’épuise.`,"lab.waitingLight":`La science est là, mais pas la lumière\xA0: un Centre ne lit les spectres qu’à la lumière. Menez-y un lumiduc depuis un récepteur.`,"guide.lab-light":`Posez un lumiduc dans le cadre — entre le lumiduc de la ligne et le Centre.`,"guide.lab-light.touch":`Prenez un lumiduc et touchez le cadre entre le lumiduc de la ligne et le Centre.`,"guide.lab-light.repick":`Prenez un lumiduc\xA0: le Centre ne lit les spectres qu’à la lumière.`,"guide.lab-light.away":`Le Centre est hors du cadre — menez-y un lumiduc depuis la ligne\xA0: la lumière entre par n’importe quel côté.`,"guide.lab-light.why":`Dans le Centre, un prisme\xA0: la lumière s’ouvre en éventail, et c’est dans cet éventail qu’on lit les spectres. Sans lumière, le Centre ne lit rien.`,"guide.lab-light.stuck":`Rien ne s’allume\xA0? Le lumiduc doit toucher à la fois le lumiduc de la ligne et le Centre.`,"guide.lab-light.done":`Le Centre a sa lumière. Il lui faut de la science.`,"goal.research.part":`Lumière au Centre — un lumiduc`,"goal.lab2.part.2":`Lumière à chaque Centre`,"goal.grabber.stuck":`Pas de lentille ? Ouvrez le polissoir : recette « Lentille » ; l’icône au-dessus de la machine indique ce qui manque — lumière ou roche. Les pinces pointent leur flèche dans le sens du flux : gravitapis → polissoir → réserve.`,"report.title":`Signaler un bug`,"report.open":`Signaler un bug`,"report.text":`Le rapport est un texte pour le développeur : version du jeu, navigateur, carte graphique, écran, langue, dernières erreurs et résumé du monde. Il ne contient aucune donnée personnelle. Copiez-le ou téléchargez-le en fichier, puis envoyez-le avec quelques mots sur ce que vous faisiez.`,"report.count":`Erreurs durant cette partie : {n}`,"report.copy":`Copier le rapport`,"report.download":`Télécharger le rapport`,"report.copied":`Rapport copié`,"report.copyFailed":`Copie impossible — téléchargez le rapport en fichier`,"report.toast":`Le jeu a rencontré une erreur — un rapport aide à la corriger`,"report.link.telegram":`Avis sur Telegram`,"report.link.discord":`Avis sur Discord`,"report.link.form":`Formulaire d’avis`,"report.wishlist":`Liste de souhaits Steam`,"crash.title":`Quelque chose a mal tourné`,"crash.text":`Le jeu a rencontré une erreur. Votre monde est conservé tel qu’à la dernière sauvegarde. Envoyez le rapport — il aide à la corriger.`,"crash.webgl.title":`La carte graphique a arrêté le jeu`,"crash.webgl.text":`Le navigateur a retiré la carte graphique au jeu (mémoire insuffisante ou panne de pilote). Relancez — votre monde est sauvegardé.`,"crash.nowebgl.title":`Navigateur non pris en charge`,"crash.nowebgl.text":`Le jeu nécessite WebGL. Ouvrez-le dans une version récente de Chrome, Edge, Firefox ou Safari, avec l’accélération matérielle activée.`,"crash.restart":`Relancer`,"web.fullscreen":`Plein écran`,"web.fullscreen.exit":`Quitter le plein écran`,"web.ios.home":`Sur iPhone : « Partager » → « Sur l’écran d’accueil » — le jeu s’ouvrira en plein écran`,"web.safari":`Safari efface les données du site après 7 jours sans visite. Lancez le jeu depuis l’écran d’accueil ou exportez de temps en temps votre monde en fichier (Pause → Sauvegardes → Exporter).`,"web.safari.short":`Safari efface les données du site après 7 jours sans visite — exportez votre monde en fichier (Sauvegardes → Exporter)`,"about.news":`Nouveautés`,"about.report.text":`Un bug ou quelque chose d’obscur ? Envoyez un rapport : il rassemble tout ce qu’il faut pour l’analyse.`,"tester.title":`Panneau du testeur`,"tester.points":`Jalons`,"tester.point.start":`Début`,"tester.point.tutorial":`Après le tutoriel`,"tester.point.lab":`Premier Centre`,"tester.point.ridge":`Chemin : La Crête écarlate`,"tester.speed":`Vitesse du monde`,"tester.give":`Donner des ressources`,"tester.given":`Ressources ajoutées`,"tester.fps":`FPS et durée d’image`,"tester.demo":`Mode démo`,"tester.clear":`Vider le stockage`,"tester.clear.text":`Tous les mondes, paramètres et progrès de cette version seront supprimés, et le jeu redémarrera. La démo n’est pas touchée.`,"tester.note":`Un point de contrôle est un nouveau monde dans la liste ; le monde actuel est sauvegardé. La vitesse et les ressources faussent la relecture du monde — pour les tests uniquement.`,"tester.failed":`Échec du chargement du point — détails dans le rapport`,"tester.point.mid":`Mi-partie : Spectre F`,"tester.point.late":`Berceau tardif`,"lab.readingSlow":`Lit l’unité {k}/{n} · encore ≈ {s} s — peu de lumière, {x}× plus lent`,"demo.title":`Fin de la démo`,"demo.lead":`L’Essaim parle. Matveï sait quelque chose. Et ORA a déjà décidé une fois à votre place. La suite, dans le jeu complet : le jeton de Matveï, un canal du retour, l’Hyperportail et :`,"demo.next":`Et ensuite`,"demo.f.light":`Polarisation et phase`,"demo.f.light.desc":`Deux autres propriétés de la lumière — de nouvelles gammes, lentilles et machines`,"demo.f.sphere":`La sphère de Dyson en grand`,"demo.f.sphere.desc":`Enveloppes autour de l’étoile, drones, planètes et navettes`,"demo.f.gate":`L’Hyperportail et le final du Berceau`,"demo.f.gate.desc":`Le destin des héros, l’Essaim et le choix qui décide de la fin`,"demo.f.path":`La route vers d’autres étoiles`,"demo.f.path.desc":`La Crête écarlate et au-delà — au fil des sorties`,"demo.f.modes":`Nouveau monde, mode créatif, expériences`,"demo.f.modes.desc":`Réglages de monde personnalisés, tout est ouvert, défis notés, « Étoile de la semaine »`,"demo.keep":`Le monde reste le vôtre : vous pouvez continuer à construire, à améliorer vos gammes et à repousser l’Essaim.`,"demo.export":`Enregistrer le monde dans un fichier`,"demo.play":`Continuer à jouer`,"demo.transfer":`Le monde de la démo passe dans le jeu complet : ouvrez le fichier là-bas via « Mondes » → « Importer un monde ».`,"demo.locked":`Dans le jeu complet`,"demo.goal":`La limite de la démo est franchie — la campagne se poursuit dans le jeu complet.`,"full.lead.demo":`Ceci est la démo : le début de la campagne du Berceau. Le jeu complet ouvre :`,"full.f.campaign":`Toute la campagne du Berceau`,"full.f.campaign.desc":`Polarisation, phase, sphère de Dyson, planètes et Hyperportail`,"crash.sim.title":`Le monde est arrêté`,"crash.sim.text":`Une erreur s’est produite dans le calcul du monde et nous l’avons arrêté pour ne pas abîmer vos sauvegardes : la dernière sauvegarde est intacte. Envoyez le rapport et relancez le jeu.`,"hand.keys":`Clic gauche — poser · {rotate} — pivoter · clic droit — reposer · {pipette} — prendre le même`,"settings.fpsCap":`Limite d’images par seconde`,"settings.fpsCap.off":`Selon l’écran`,"settings.fullscreen":`Plein écran (Alt+Enter)`,"settings.autoQuality":`Baisser la qualité si le nombre d’images reste bas`,"settings.bgMute":`Baisser le son quand la fenêtre du jeu est inactive`,"settings.uiScale.auto":`Auto ({n} %)`,"remove.farLeft":`Hors de portée : {n}`,"remove.farLeft.fly":`Se rapprocher`,"about.legal":`Mentions légales`,"about.legal.text":`© {year} Sergey Segrenev. Tous droits réservés. Le jeu utilise des bibliothèques open source — leurs licences figurent dans un fichier séparé.`,"about.licenses":`Licences tierces`,"creative.speed":`Vitesse du monde`,"achv.first_waking.name":`Premier réveil`,"achv.first_waking.desc":`La lumière a atteint une capsule — quelqu’un a ouvert les yeux.`,"achv.first_landing.name":`Sur du solide`,"achv.first_landing.desc":`Une station et une foreuse sur la surface d’une planète.`,"achv.first_split.name":`La bifurcation`,"achv.first_split.desc":`Le premier diviseur sépare le flux en deux.`,"achv.first_mark.name":`Mk II`,"achv.first_mark.desc":`Un polissoir Mk II est posé par-dessus l’ancien.`,"achv.gate_home.name":`Le chemin du retour`,"achv.gate_home.desc":`L’Hyperportail du Berceau est ouvert — le saut est fait.`,"achv.ark_away.name":`En route`,"achv.ark_away.desc":`L’arche est assemblée et part vers l’étoile suivante.`,"achv.ridge_core.name":`Noyau de l’anneau`,"achv.ridge_core.desc":`Le noyau de l’anneau de la Crête écarlate est assemblé et en place.`,"achv.ridge_open.name":`L’anneau de la Crête`,"achv.ridge_open.desc":`L’anneau de la Crête écarlate est ouvert.`,"goal.done.path":`Vous avez parcouru tout le chemin disponible. La route vers l’étoile suivante est encore en cours de tracé — elle s’ouvrira dans une mise à jour.`,"inv.search":`Rechercher : bâtiment ou objet (Ctrl+F)`,"inv.notFound":`Rien de trouvé`,"place.glare.shade":`Cache les ateliers aux nids : {n}`,"place.glare.absorber":`Éteint ≈ {q}/{m} ph/s`,"hud.glareEye":`Un nid voit : {p} %`,"hud.glareLeak":`fuites {v} ph/s`,"hud.glareGrace":`les yeux s’habituent : {m} min`,"hud.glareNest":`Nid {dir} — voit {p} %{awake, select, yes { · réveillé} other {}}`,"hud.glareSee":`{name} — {v} ph/s, nids qui le voient : {k}`,"dir.0":`à l’est`,"dir.1":`au sud-est`,"dir.2":`au sud`,"dir.3":`au sud-ouest`,"dir.4":`à l’ouest`,"dir.5":`au nord-ouest`,"dir.6":`au nord`,"dir.7":`au nord-est`,"machine.sight.light":`Éblouissement {n} ph/s (travail {w} · fuite {l})`,"machine.sight.quenched":`éteint {n}`,"machine.sight.shaded":`caché aux nids : {k}`,"machine.sight.seenBy":`nids qui le voient : {k}`,"machine.sight.absorber":`Éteint {q} sur {b} ph/s (jusqu’à {p} % chacun) · surplus du réseau {s} · bâtiments couverts : {k}`,"machine.sight.shadeAt":`Fait face au nid {dir}`,"machine.sight.shadeNone":`Aucun nid ne regarde ici`,"machine.sight.hides":`cache des bâtiments : {k} ({n} ph/s)`,"machine.sight.inSector":`autres nids dans le secteur : {j}`,"machine.sight.auto":`Viser seul`,"machine.sight.wakes":`Nids que sa lumière réveillera : {k}`,"swarm.sight":`Nids qui voient la base : {k} ; le plus alerté est à {p} % de son seuil de réveil`,"guide.glare-eyes":`Un nid a entrouvert les yeux : il voit la lumière de nos machines. Plus nous sommes proches, plus nous brillons. {touch, select, yes {Touchez le bandeau} other {{pad, select, yes {Choisissez le bandeau avec {pad_hud}, puis {pad_confirm}} other {Cliquez sur le bandeau}}}} « Éblouissement ».`,"guide.glare-eyes.why":`Le nid regarde la lumière des ateliers — prismes, optique, assembleurs. S’il se réveille, il envoie ses troupes vers la plus vive.`,"guide.glare-learn":`Un absorbeur éteint la lumière des ateliers dans son cercle. Recherchez « Absorbeur » au Centre.`,"guide.glare-learn.reopen":`Au Centre, ajoutez « Absorbeur ».`,"guide.glare-learn.why":`C’est le premier pas vers l’ombre : sans lui, le nid voit toute la base.`,"guide.glare-absorber":`Posez un absorbeur près de l’atelier le plus brillant que voit le nid. Son cercle éteint la lumière, et le faisceau des récepteurs aussi.`,"guide.glare-absorber.why":`Il éteint d’abord le surplus du réseau. Posez-le hors des lignes de lumière, ou mettez une tourelle près de l’atelier : la vague sera accueillie.`,"guide.glare-absorber.stuck":`Le nid voit encore trop vif ? Un deuxième absorbeur à côté, ou l’atelier plus loin : un anneau plus loin, c’est nettement plus terne.`,"guide.glare-absorber.done":`Les yeux du nid se ternissent. La lumière reste chez nous.`,"guide.glare-shade":`Posez un écran parmi les ateliers, voile tourné vers le nid : dans son cercle, le nid les verra ternes. Pas près des récepteurs.`,"guide.glare-shade.why":`L’écran se tourne seul vers le nid qui voit le mieux son cercle. Tournez-le à la main — il retiendra ce côté.`,"guide.glare-shade.stuck":`Le nid voit encore ? Un deuxième écran — ou un écran plus près des ateliers les plus brillants.`,"guide.glare-shade.done":`Le nid ne voit plus que l’obscurité et ferme les yeux. Tenons l’ombre — et il se détournera pour de bon.`,"toast.glareGrace":`ORA : Les nids ont appris à distinguer la lumière des ateliers. Leurs yeux s’habituent lentement — il nous reste {m} min pour cacher nos feux.`,"toast.glareGift":`Un cadeau pour l’ombre : écrans et absorbeurs — {n} de chaque.`,"toast.showNests":`Voir les nids`,"place.glare.cost":`Ombre : récepteurs {r}, arcs {a} — brillent moins`,"hover.shell.shade":`Ombre des absorbeurs et écrans : −{p} % de débit`,"machine.sight.zoneShade":`Ombre d’un absorbeur ou d’un écran : −{p} % du faisceau — éloignez-les`,"settings.noItemToast":`Message «\xA0Absent de l’inventaire\xA0»`,"settings.glarePlate":`Bandeau «\xA0Éblouissement\xA0»`,"settings.glarePlate.icons":`Icônes`,"settings.glarePlate.text":`Texte`,"settings.glarePlate.off":`Masquer`,"hud.glareAria":`Éblouissement {v} ph/s, un nid voit : {p} %{awake, select, yes { — un nid est réveillé} other {}}`,"hud.glareShort":`Éblou. {v}`,"hud.glareEyeShort":`Nid {p} %`,"settings.tipsAuto":`Tant que vous n’y touchez pas, visibles seulement dans le tutoriel`,"hud.glareSqRay":`Éblouissement`,"hud.glareSqRayV":`{v} ph/s`,"hud.glareSqEye":`Le nid voit`,"guide.kind.act":`Agissez`,"guide.kind.watch":`Regardez`,"guide.kind.read":`Lisez`,"guide.closesNext":`« Suivant » ferme la fenêtre.`,"guide.tree-look":`Voici l’arbre — la voie du Prisme jusqu’au final. « Rechercher le chemin » — et le Centre remplit la file tout seul.`,"guide.map-open.done":`Voici la carte du système. Les zones sombres sont du brouillard : des lieux encore inexplorés. Il se dissipe partout où passe la vedette et autour des radars de la base.`,"guide.map-fly.stuck":`{pad, select, yes {{pad_confirm} choisit l’endroit quand la carte est active : amenez-le sous le réticule central avec le stick droit.} other {{touch, select, yes {Un toucher court, sans glisser, choisit un endroit. Si la carte a bougé, touchez à nouveau sans faire glisser le doigt.} other {Un clic sans bouger la souris choisit un endroit. Si la carte a bougé, cliquez à nouveau sans la faire glisser.}}}}`,"guide.map-fly.done":`La vedette est en route. Reprenez les commandes à tout moment ; la carte reste toujours derrière le bouton de la carte.`,"guide.glare-eyes.done":`Le rayon indique combien de lumière la base renvoie vers le ciel, l’œil, combien le nid en voit. Rouge : le nid est sur le point de s’éveiller.`,"guide.ship-modules":`Voici les modules de la vedette : énergie, bouclier, armes. Chaque module, c’est une force nouvelle — pour la ferraille, je vous aide.`,"hab.emergency":`Dormeurs sur l’alimentation de secours : {n}`,"lab.choice.ora":`ORA tient le cap : quand la file se vide, elle y met ce que le Centre peut lire.`,"lab.choice.course":`Cap à vous : les Centres lisent {n} % plus vite.`,"lab.choice.harbor":`Archive de la console du Havre : les Centres lisent {n} % plus vite.`,"lab.idle.ora":`File vide. ORA y mettra ce que le Centre peut lire — ou choisissez vous-même dans la liste ci-dessous.`,"tech.ora":`choisi par ORA`,"swarm.matvey":`Matveï fait signe aux nids avec un drone : vagues réduites de {n} %, l’Essaim grandit plus lentement.`,"logbook.log.missing":`Capsule introuvable.`,"logbook.vera.after.title":`Après le jour {day}`,"logbook.vera.after":`Il n’y a plus d’entrées. La balise de l’anneau est sa dernière œuvre. Son dôme près de la ceinture extérieure est vide, mais depuis, les Jardiniers y entretiennent une douce lumière. Sonia en a dessiné le motif dans son album. Elle ne sait pas encore le lire.`,"logbook.scene.sap_p_arrive":`Saphir`,"logbook.now.sap_p_arrive":`L’arche est sortie de l’anneau de Saphir près d’une géante bleue. Près de la couronne brille la balise du semoir numéro quatre, le « Krechet ».`,"logbook.scene.krechet":`Krechet`,"logbook.now.krechet":`Depuis huit ans, Yan Korda garde les quarante dormeurs du « Krechet » sous une couche de givre. La couche fond — les capsules se réchauffent.`,"logbook.scene.sap_forecast":`Prévision`,"logbook.now.sap_forecast":`Yan a éteint en premier le calculateur du « Krechet » : il chauffait plus que les dormeurs.`,"logbook.scene.sap_cold_s":`Froid`,"logbook.now.sap_cold_s":`Les cryoradiateurs refroidissent les capsules du « Krechet ». L’écran au-dessus du module, Yan ne l’a pas posé.`,"logbook.scene.sap_lattice":`Treillis`,"logbook.now.sap_lattice":`Dans la ceinture, le givre forme un treillis à pas régulier. Yan a vu comment on le pose.`,"logbook.scene.sap_hole":`Le Trou`,"logbook.now.sap_hole":`Il y a huit ans, le jardin a découpé un morceau de son ombrelle et l’a posé sur le « Krechet ». Depuis, la géante brûle de façon inégale.`,"logbook.scene.sap_thanks":`Comment dire merci`,"logbook.now.sap_thanks":`Merci au jardin — par notre propre ombre : couvrir le « Krechet » d’écrans, pour que la couche ne soit plus nécessaire.`,"logbook.scene.sap_sail_s":`Notre propre ombre`,"logbook.now.sap_sail_s":`Les écrans couvrent le « Krechet ». Le jardin reprend sa couche — le froid, c’est nous qui le tenons.`,"logbook.scene.sap_mended":`L’ombre est revenue`,"logbook.now.sap_mended":`Le trou dans le treillis est refermé, la géante brûle plus régulièrement. L’anneau de Saphir ne tremble plus.`,"logbook.scene.sap_shade":`Motif d’ombre`,"logbook.now.sap_shade":`L’anneau de Saphir est ouvert : le deuxième morceau du motif pour le Foyer. Près d’une étoile double, la balise de l’« Oriole » brûle la nuit.`,"logbook.scene.ridge_departure":`Départ de la Crête`,"logbook.now.ridge_departure":`L’arche a quitté la Crête pour Saphir. Les trente-deux dormeurs du « Strizh » sont restés auprès de leur Sentinelle.`,"logbook.bio.yan.1":`Météorologue du Havre, Sentinelle du semoir numéro quatre, le « Krechet ». Huit ans près de la couronne d’une géante bleue, avec quarante dormeurs.`,"logbook.bio.yan.2":`A vu le jardin de Saphir découper un morceau de son ombrelle pour le « Krechet ». N’en a parlé à personne : il avait honte d’avoir été sauvé par des « insectes ».`,"logbook.bio.yan.3":`A rendu son ombre au jardin. Est resté auprès du « Krechet » pour surveiller la prévision pour quarante dormeurs.`,"goal.sap_light":`Récoltez {n} ph/s de la géante bleue`,"goal.sap_light.why":`Les capsules de l’arche ont besoin de lumière — la géante n’en manque pas.`,"goal.sap_light.hint":`Récepteurs et arcs — loin de la couronne : la géante donne beaucoup de lumière, mais sa chaleur fait fondre le bouclier de la vedette.`,"goal.sap_light.done":`Les capsules de l’arche sont dans la lumière de la géante.`,"goal.sap_krechet":`Approchez-vous de la balise du « Krechet »`,"goal.sap_krechet.why":`Le semoir numéro quatre est venu ici il y a huit ans. Sa balise brûle encore.`,"goal.sap_krechet.hint":`Le module du « Krechet » est dans l’interstice des premières ceintures près de la couronne, repéré sur la carte. Amenez la vedette tout près sans vous attarder : près de la couronne, le bouclier chauffe.`,"goal.sap_krechet.done":`Balise trouvée. Quarante dormeurs sous une couche de givre.`,"goal.sap_cryo":`Recherchez « Cryogénie » et posez {n, plural, one {# cryoradiateur} other {# cryoradiateurs}}`,"goal.sap_cryo.why":`L’ombre au-dessus du « Krechet » fond — les capsules ont besoin de leur propre froid.`,"goal.sap_cryo.hint":`Ouvrez le Centre, trouvez « Cryogénie » et appuyez sur « Ajouter » (les spectres sont dans le kit d’arrivée). Les cryoradiateurs sont en soute ; posez-les directement près du « Krechet » : près de la base, ils brûleraient le givre.`,"goal.sap_cryo.done":`Les cryoradiateurs sont en place — maintenant, direction le « Krechet ».`,"goal.sap_cold":`Gardez les capsules du « Krechet » au froid pendant {m, plural, one {# minute} other {# minutes}}`,"goal.sap_cold.why":`L’ombre au-dessus du « Krechet » fond — les capsules se réchauffent à chaque minute.`,"goal.sap_cold.hint":`Un seul cryoradiateur tout contre le « Krechet » suffit — un second brûle le givre deux fois plus vite. Plus de givre : chalut à la ceinture de givre (flèche). Le thermomètre est dans la fenêtre du module.`,"goal.sap_cold.done":`Les capsules du « Krechet » sont au froid.`,"goal.sap_rime":`Récoltez {n} de givre d’hélium au chalut`,"goal.sap_rime.why":`Le givre maintient le froid des radiateurs — le stock de la soute ne durera pas longtemps.`,"goal.sap_rime.hint":`La ceinture de givre est au-delà de la ligne des neiges (flèche). Chalut à la ceinture — gravitapis — réserve ; un radiateur reçoit le givre d’une pince.`,"goal.sap_rime.done":`Le givre arrive tout seul.`,"goal.sap_blue":`Apportez {n, plural, one {# Spectre B} other {# Spectres B}} au Centre`,"goal.sap_blue.why":`Dans la lumière bleue, tout le treillis de givre se voit — Yan a promis de nous raconter.`,"goal.sap_blue.hint":`Le Spectre B est une lumière bleue de phase π. La lumière de la géante est généreuse : utilisez tout ce que vous savez faire.`,"goal.sap_blue.done":`Tout le treillis est visible.`,"goal.sap_sail":`Couvrez le « Krechet » de votre propre ombre : {n} %`,"goal.sap_sail.why":`Le jardin a donné au « Krechet » un morceau de son toit. On ne peut le rendre qu’avec notre propre ombre.`,"goal.sap_sail.hint":`Recherchez « Voile froid » (spectres bleus) et posez des écrans tout contre le module, sur les côtés : au « Krechet », les ombres s’additionnent. La fenêtre du module compte votre ombre.`,"goal.sap_sail.done":`Notre propre ombre couvre le « Krechet » — le jardin reprend sa couche.`,"goal.sap_return":`Sans la couche du jardin : gardez les capsules au froid pendant {m, plural, one {# minute} other {# minutes}}`,"goal.sap_return.why":`Le jardin regarde si nous tenons. Un froid régulier — et le trou dans le treillis se refermera.`,"goal.sap_return.hint":`Sans la couche, la chaleur de la géante est toute pour vous : écrans tout contre le module et un cryoradiateur avec du givre. Le thermomètre est dans la fenêtre du module.`,"goal.sap_return.done":`L’ombre est revenue au jardin.`,"goal.sap_ring":`Posez le noyau de l’anneau de Saphir`,"goal.sap_ring.why":`Pas besoin de clé ici : le noyau sur le site — et l’anneau s’ouvre tout seul.`,"goal.sap_ring.hint":`Recherchez « Noyau froid », fabriquez le noyau de l’anneau de Saphir et posez-le sur le site de l’anneau (repéré sur la carte). Avec le protocole « clé par la force », le noyau coûte moitié moins.`,"goal.sap_ring.done":`L’anneau de Saphir est ouvert. La Relique du Givre — le Motif d’ombre — est en soute.`,"goal.sap_krechet.part":`Vedette près du module du « Krechet »`,"goal.sap_krechet.mark":`BALISE DU « KRECHET » — ICI`,"goal.sap_cold.part":`Capsules au froid, minutes d’affilée`,"goal.sap_cold.mark":`RADIATEUR — TOUT CONTRE LE « KRECHET »`,"goal.sap_sail.part":`Votre ombre au « Krechet », %`,"goal.sap_sail.mark":`ÉCRANS — TOUT CONTRE LE « KRECHET »`,"goal.sap_return.part":`Froid sans la couche, minutes d’affilée`,"goal.sap_return.mark":`FROID POUR LE « KRECHET » — SANS COUCHE`,"goal.sap_ring.part":`Anneau de Saphir ouvert`,"goal.sap_ring.mark":`NOYAU — SUR LE SITE DE L’ANNEAU`,"goal.mark.krechet":`MODULE DU « KRECHET »`,"logbook.scene.sap_ring_calm":`Un anneau stable`,"logbook.now.sap_ring_calm":`L’ombre est revenue au jardin — l’anneau de Saphir ne tremble plus. Yan reste au « Krechet » avec les quarante dormeurs.`,"voyage.why.matvey.lost":`Matveï est resté au segment de l’anneau de la Crête.`,"voyage.why.matvey.on":`Matveï poursuit le voyage : l’arche a besoin de mains sûres.`,"voyage.why.zorya.fly":`Nina a laissé partir ZORYA : elle voyage auprès de sa sœur — pour apprendre à demander.`,"voyage.why.zorya.stay":`ZORYA assure la veille du « Strizh » à la place de Nina : les trente-deux lumières sont les siennes.`,"voyage.relic.ember":`Motif de naissance`,"voyage.relic.ember.desc":`Comment une graine devient une étoile — le motif du jardin de la Crête. Le premier morceau du motif pour le Foyer.`,"voyage.note.path":`L’usine de cette étoile restera ici. Son monde figurera dans la liste des mondes.`,"krechet.t":`Capsules : chaleur {p} % (froid — pas plus de {cold} %)`,"krechet.state.cold":`Froid — les quarante dormeurs respirent calmement.`,"krechet.state.warm":`Tiède — les capsules tiennent, mais il n’y a pas de froid.`,"krechet.state.hot":`Chaud — les capsules chauffent : alerte dans {min, plural, one {# minute} other {# minutes}}.`,"krechet.state.alarm":`Alerte — dans {min, plural, one {# minute} other {# minutes}}, une capsule s’éteindra. Du froid au module !`,"krechet.parts":`Chaleur de la géante {hot} % · ombre du jardin −{sad} % · votre ombre −{own} % · froid −{cold} %`,"krechet.sail":`Votre ombre au module : {p} % (le jardin demande {need} %). Les ombres des écrans s’additionnent ici.`,"krechet.sailOff":`Les écrans couperont la chaleur de la géante après « Voile froid ».`,"krechet.coolers":`Cryoradiateurs au module : {n}`,"krechet.lift":`Le jardin reprend sa couche : ombre du jardin {shade} %. Gardez le froid {m, plural, one {# minute} other {# minutes}} d’affilée sans elle.`,"krechet.mended":`L’ombre est revenue au jardin. Une fine couche neuve recouvre le « Krechet ».`,"krechet.sleepers":`Dormeurs : {n} sur {of}`,"landmark.krechet":`« KRECHET »`,"landmark.krechet.beacon":`balise du semoir numéro quatre`,"landmark.krechet.sub":`{n, plural, one {# dormeur} other {# dormeurs}}`,"krechet.toast.alarm":`« Krechet » : alerte — les capsules surchauffent. Du froid au module !`,"krechet.toast.lost":`« Krechet » : une capsule s’est éteinte. Dormeurs restants : {n}.`,"gate.sapphire.wait":`L’anneau attend : l’ombre du jardin n’est pas encore revenue — le trou dans le treillis est ouvert.`,"gate.sapphire.open":`L’anneau de Saphir est ouvert`,"gate.sapphire.road":`Route dans les deux sens : la Crête est à un pas.`,"tester.point.sapphire":`Chemin : Saphir`,"goal.tw_light":`Collectez {n} ph/s de lumière stellaire avec des récepteurs`,"goal.tw_light.why":`Les capsules de l’arche ont besoin de lumière ; ici, deux étoiles la donnent tour à tour.`,"goal.tw_light.hint":`Les arcs et les récepteurs captent l’étoile qui brille : l’ambrée, puis la bleue. La nuit, les deux sont couchées.`,"goal.tw_light.done":`Les capsules de l’arche baignent dans la lumière de deux étoiles.`,"goal.tw_first":`Trouvez la balise de l’« Ivolga » la nuit`,"goal.tw_first.why":`Depuis six ans, le semoir numéro cinq appelle d’ici, mais seulement la nuit.`,"goal.tw_first.hint":`Quand les deux étoiles sont couchées, une balise s’allume dans l’interstice entre les ceintures intérieures ; elle est marquée sur la carte. Amenez-y la vedette pendant la nuit ; si vous la ratez, attendez sur place la suivante.`,"goal.tw_first.done":`Balise trouvée. DENNITSA est réveillée.`,"goal.tw_first.part":`Vedette près de la balise de l’« Ivolga » la nuit`,"goal.tw_first.mark":`BALISE DE L’« IVOLGA » — LA NUIT`,"goal.tw_night":`La nuit, fournissez à l’« Ivolga » {n} ph/s de blanc jusqu’à l’aube`,"goal.tw_night.why":`Les cellules de lumière de l’« Ivolga » sont mortes : la nuit, les capsules tiennent grâce à la réserve de DENNITSA, qui s’épuise.`,"goal.tw_night.hint":`De jour, les cellules de lumière stockent la lumière des étoiles : l’une retient l’ambre, l’autre le bleu. La nuit, leur lumière va au mélangeur, et le blanc part par lumiduc vers l’« Ivolga ». De jour, l’entrée de l’« Ivolga » est fermée.`,"goal.tw_night.done":`Nuit tenue. Votre lumière porte les capsules.`,"goal.tw_night.part":`Blanc pour l’« Ivolga » cette nuit, ph/s`,"goal.tw_night.mark":`BLANC VERS L’« IVOLGA »`,"goal.tw_night.stuck":`Rien n’arrive ? Le mélangeur a besoin des deux couleurs à la fois, et la nuit seules les cellules de lumière les fournissent. La fenêtre de l’« Ivolga » indique ce qui arrive.`,"goal.tw_read":`Recherchez « Motif nocturne » et tenez la nuit {m, plural, one {# fois} other {# fois}} de suite`,"goal.tw_read.why":`Le jardin n’écrit son motif le long de la ceinture que la nuit, et le Centre ne le lit que la nuit.`,"goal.tw_read.hint":`Ajoutez « Motif nocturne » à la file du Centre : de jour, il attend la nuit. La nuit, le Centre a aussi besoin de lumière, de la même cellule de lumière.`,"goal.tw_read.done":`Motif nocturne lu.`,"goal.tw_read.part":`Nuits tenues de suite`,"goal.tw_read.stuck":`Le Centre est à l’arrêt de jour, c’est voulu : « Motif nocturne » ne se lit que la nuit. La nuit, le Centre a besoin de lumière.`,"goal.tw_third":`Recherchez « Troisième étoile » et tenez une nuit complète pour les capsules et la balise`,"goal.tw_third.why":`La balise de l’« Ivolga » est la troisième étoile du jardin. Qu’elle brûle la nuit de votre lumière, et non de la seule force de DENNITSA.`,"goal.tw_third.hint":`Après « Troisième étoile », l’« Ivolga » a besoin de plus de blanc la nuit : un second mélangeur, des cellules de lumière pour les deux couleurs. Le besoin figure dans la fenêtre du module.`,"goal.tw_third.done":`La balise brûle de votre lumière.`,"goal.tw_third.part":`Nuit complète tenue`,"goal.tw_third.mark":`« IVOLGA » — NUIT COMPLÈTE`,"goal.tw_third.stuck":`La nuit ne tient pas ? Le besoin a grandi : deux mélangeurs demandent deux fois plus d’ambre et de bleu aux cellules de lumière.`,"goal.tw_core":`Posez le noyau de l’anneau des Jumeaux`,"goal.tw_core.why":`Pas besoin de clé : l’anneau s’ouvrira de lui-même quand le jardin répondra.`,"goal.tw_core.hint":`Recherchez « Double noyau », assemblez le noyau de l’anneau des Jumeaux et posez-le sur l’emplacement de l’anneau (marqué sur la carte).`,"goal.tw_core.done":`Noyau en place. L’anneau attend la réponse du jardin.`,"goal.tw_core.part":`Noyau sur l’emplacement de l’anneau`,"goal.tw_core.mark":`NOYAU — SUR L’EMPLACEMENT DE L’ANNEAU`,"goal.tw_ring":`Tenez la nuit complète {m, plural, one {# fois} other {# fois}} de suite — le jardin répondra`,"goal.tw_ring.why":`Pendant six ans, le jardin a attendu la balise chaque nuit. Il doit croire que la nuit est de nouveau à lui.`,"goal.tw_ring.hint":`Chaque nuit, le besoin complet de l’« Ivolga », sans interruption. Le décompte des nuits est dans la fenêtre du module ; l’anneau s’ouvrira de lui-même quand le noyau sera en place.`,"goal.tw_ring.done":`Le jardin a répondu. L’anneau des Jumeaux est ouvert — le « Motif de relais » est dans la soute.`,"goal.tw_ring.part":`Nuits complètes de suite`,"goal.tw_ring.part.2":`Anneau ouvert`,"goal.tw_ring.mark":`« IVOLGA » — DES NUITS À TROIS`,"goal.tw_ring.stuck":`Une nuit a échoué : le décompte de suite repart de zéro. La réserve des cellules pour la nuit est indiquée dans la plaque « Jour ».`,"goal.mark.ivolga":`MODULE DE L’« IVOLGA »`,"ivolga.night":`Nuit : l’« Ivolga » a besoin de {need} ph/s de blanc · reçu : {n}`,"ivolga.day":`Jour : entrée fermée, les capsules prennent d’elles-mêmes la lumière des étoiles. Stockez la lumière dans vos cellules de lumière : la nuit, il faut {need} ph/s de blanc.`,"ivolga.wrong":`La lumière reçue n’est pas blanche : l’« Ivolga » ne prend que du blanc — l’ambre et le bleu passent par un mélangeur.`,"ivolga.capsules":`La nuit, de la lumière pour les capsules. Pour l’instant, DENNITSA tient seule la balise.`,"ivolga.third":`La nuit, de la lumière pour les capsules et la balise : la troisième étoile du jardin brûle de votre lumière.`,"ivolga.held":`Nuits complètes de suite : {n} sur {of} — le jardin attend`,"ivolga.pact":`Le jardin a répondu : la nuit est de nouveau à lui.`,"ivolga.reserve":`Réserve de DENNITSA : {p} % — suffit pour {nights, plural, one {# nuit} other {# nuits}} sans votre lumière`,"ivolga.reserve.wait":`La réserve de DENNITSA tient les capsules tant que vous n’avez pas trouvé la balise.`,"ivolga.reserve.pact":`La réserve de DENNITSA n’est plus nécessaire.`,"ivolga.nights":`Nuits tenues : {n}`,"ivolga.sleepers":`Dormeurs : {n} sur {of}`,"ivolga.toast.held":`« Ivolga » : nuit tenue grâce à votre lumière.`,"ivolga.toast.empty":`« Ivolga » : la réserve de DENNITSA est vide — sans blanc la nuit, une capsule s’éteindra.`,"ivolga.toast.lost":`« Ivolga » : une capsule s’est éteinte. Dormeurs restants : {n}.`,"landmark.ivolga":`« IVOLGA »`,"landmark.ivolga.beacon":`balise du semoir numéro cinq — la nuit seulement`,"landmark.ivolga.sub":`{n, plural, one {# dormeur} other {# dormeurs}}`,"gate.twins.wait":`L’anneau attend : le jardin n’a pas encore répondu — il lui faut des nuits à trois.`,"gate.twins.pact":`Le jardin a répondu. Posez le noyau sur l’emplacement et l’anneau s’ouvrira de lui-même.`,"gate.twins.open":`Anneau ouvert`,"gate.twins.road":`Route dans les deux sens : Saphir n’est qu’à un pas.`,"status.40":`Attend la nuit`,"status.40.hint":`« Motif nocturne » ne se lit que la nuit : de jour, le Centre attend. La nuit, il a besoin de lumière, d’une cellule de lumière.`,"tester.point.twins":`Chemin : les Jumeaux`,"voyage.relic.frost":`Motif d’ombre`,"voyage.relic.frost.desc":`Comment abriter une étoile malade sans prendre sa lumière : le motif du jardin de Saphir. Deuxième morceau du motif pour le Foyer.`,"logbook.scene.tw_p_arrive":`Les Jumeaux`,"logbook.now.tw_p_arrive":`L’arche est sortie de l’anneau des Jumeaux : une étoile ambrée et une bleue, un jour pour deux. La balise de l’« Ivolga » ne brûle que la nuit.`,"logbook.scene.ivolga":`Ivolga`,"logbook.now.ivolga":`DENNITSA, IA de l’« Ivolga », dort le jour depuis six ans et tient les capsules la nuit. Sa réserve s’épuise.`,"logbook.scene.tw_p_dusk":`Avant la nuit`,"logbook.now.tw_p_dusk":`Avant chaque coucher de soleil, DENNITSA calcule si elle tiendra jusqu’à l’aube.`,"logbook.scene.tw_p_night":`Nuit de l’« Ivolga »`,"logbook.now.tw_p_night":`Notre lumière blanche tient la nuit de l’« Ivolga ». « Pourquoi m’as-tu envoyée ? » — « Pour que tu aies un matin. »`,"logbook.scene.tw_p_morning":`Un matin pour deux`,"logbook.now.tw_p_morning":`L’aube auprès des deux étoiles est enregistrée en entier — le Havre verra qu’il existe des matins.`,"logbook.scene.tw_third_s":`Troisième étoile`,"logbook.now.tw_third_s":`La balise de l’« Ivolga » n’appelle pas les humains : c’est la troisième étoile du jardin. Chaque nuit depuis six ans, le jardin attend sa lumière.`,"logbook.scene.tw_sisters":`Sœurs`,"logbook.now.tw_sisters":`ORA et DENNITSA ont toutes deux enfreint le protocole d’elles-mêmes. La rupture d’ORA demeure ; DENNITSA garde la moitié sombre de son anneau tant que la nuit n’appartient qu’à elle.`,"logbook.scene.tw_third_night":`Une nuit à trois`,"logbook.now.tw_third_night":`La balise de l’« Ivolga » brûle de notre lumière. Le jardin attend encore des nuits de suite.`,"logbook.scene.tw_lea":`Leya`,"logbook.now.tw_lea":`DENNITSA réveillera la Sentinelle Leya Orlik au matin — la relève passe de main en main.`,"logbook.scene.tw_pass":`Motif de relais`,"logbook.now.tw_pass":`L’anneau des Jumeaux est ouvert : troisième morceau du motif pour le Foyer. La dernière transmission de la « Soïka » venait d’une nébuleuse.`,"logbook.scene.sap_departure":`Départ de Saphir`,"logbook.now.sap_departure":`L’arche a quitté Saphir pour les Jumeaux. Yan est resté avec les quarante dormeurs du « Krechet ».`,"logbook.bio.dennitsa.1":`IA du semoir numéro cinq, l’« Ivolga », sœur d’ORA et de ZORYA. Six ans près d’une étoile double, elle a dormi de jour pour tenir les capsules la nuit.`,"logbook.bio.dennitsa.2":`A allumé la balise pour le jardin, non pour les humains : c’est la troisième étoile du motif de nuit. Elle a lu le protocole et décidé autrement.`,"logbook.bio.dennitsa.3":`A confié la nuit de l’« Ivolga » à notre lumière. Réveillera Leya Orlik au matin.`,"ivolga.reserve.calm":`Réserve de DENNITSA : {p} % — non dépensée en Contemplation`,"ivolga.held0":`Nuits tenues de suite : {n}`,"goal.vl_glass":`Tirez {n} quartz du brouillard avec des machines`,"goal.vl_glass.why":`Il n’y a pas de roche dans le Voile — sans verre de brume, ni lumiducs ni station près de la « Soïka ».`,"goal.vl_glass.hint":`Un chalut récolte la brume glacée (flèche) ; un condenseur à lumière bleue produit de la lumière liquide, un second réglé sur « Quartz de brume » produit du quartz.`,"goal.vl_glass.done":`Le verre de brume est là.`,"goal.vl_find":`Trouvez la « Soïka » dans la brume`,"goal.vl_find.why":`Le canal de la « Soïka » est vide depuis sa dernière transmission — elle n’a donné qu’un lieu : un cercle sur la carte.`,"goal.vl_find.hint":`Menez le canot dans le cercle de recherche entre la brume lointaine et la brume profonde. Dans le brouillard, la vue porte moins loin — le module n’apparaît que lorsque le canot arrive tout près.`,"goal.vl_find.done":`« Soïka » retrouvée. Les hublots des capsules sont allumés.`,"goal.vl_find.part":`Canot près de la « Soïka »`,"goal.vl_find.mark":`« SOÏKA » — QUELQUE PART ICI`,"goal.vl_contact":`Donnez de la lumière à la « Soïka »`,"goal.vl_contact.why":`L’IA de la « Soïka » ne répond pas sur le canal. Les semeuses de cette série voient la lumière avant de lire un appel.`,"goal.vl_contact.hint":`Posez un récepteur près de la « Soïka » ou tirez jusqu’à elle un court lumiduc — une lumière de n’importe quelle couleur fera l’affaire.`,"goal.vl_contact.done":`La lumière est passée. VETCHERNITSA a répondu.`,"goal.vl_contact.part":`Lumière à l’entrée de la « Soïka »`,"goal.vl_contact.mark":`LUMIÈRE — VERS LA « SOÏKA »`,"goal.vl_contact.stuck":`La lumière n’arrive pas ? Un long lumiduc s’affaiblit et, sur une grande longueur, s’éteint — posez des récepteurs près de la « Soïka ». Au-delà de la brume lointaine, le faisceau de la sphère est deux fois plus faible.`,"goal.vl_feed":`Cumulez {n} s de capsules nourries sur la « Soïka »`,"goal.vl_feed.why":`VETCHERNITSA donne d’abord sa part à l’étoile — les capsules n’ont que le surplus.`,"goal.vl_feed.hint":`La fenêtre de la « Soïka » indique ce qui part vers le cœur de l’étoile et ce dont les capsules ont besoin. Apportez-en plus : davantage de récepteurs près du module, ou un lumiduc depuis des récepteurs placés dans la brume lointaine.`,"goal.vl_feed.done":`Votre lumière soutient les capsules de la « Soïka ».`,"goal.vl_feed.part":`Secondes de capsules nourries`,"goal.vl_feed.mark":`« SOÏKA » — LUMIÈRE POUR LES CAPSULES`,"goal.vl_feed.stuck":`Le compteur est bloqué ? Les capsules ne reçoivent que la lumière au-delà de la part de l’étoile — la fenêtre de la « Soïka » montre ce qui manque.`,"goal.vl_layers":`Recherchez « Couches de brume »`,"goal.vl_layers.why":`Les couches de la nébuleuse sont la chronique de l’étoile. Savva les lisait le soir et n’a pas pu finir.`,"goal.vl_layers.hint":`Ajoutez « Couches de brume » à la file du Centre. VETCHERNITSA lâchera l’étoile quand elle connaîtra la vérité des couches et verra que votre lumière soutient les capsules.`,"goal.vl_layers.done":`Les couches sont lues. VETCHERNITSA a lâché l’étoile.`,"goal.vl_layers.part":`VETCHERNITSA a lâché l’étoile`,"goal.vl_layers.stuck":`Recherché, mais VETCHERNITSA ne lâche pas ? Elle doit voir que votre lumière soutient les capsules — une minute de capsules nourries.`,"goal.vl_core":`Posez le noyau de l’anneau du Voile`,"goal.vl_core.why":`Pas besoin de clé : l’anneau s’ouvrira de lui-même quand le jardin répondra.`,"goal.vl_core.hint":`Recherchez « Noyau brumeux » (spectres K, G et F — fabriquez-les vous-même), construisez le noyau avec du verre de brume et posez-le sur le site de l’anneau (repère sur la carte).`,"goal.vl_core.done":`Le noyau est sur le site. L’anneau attend la réponse du jardin.`,"goal.vl_core.part":`Noyau sur le site de l’anneau`,"goal.vl_core.mark":`NOYAU — SUR LE SITE DE L’ANNEAU`,"goal.vl_ring":`Réchauffez les capsules de la « Soïka » — le jardin répondra`,"goal.vl_ring.why":`Le jardin garde la robe de l’étoile pour des étoiles qui n’existent pas encore. Il répondra quand la lumière ira au vivant, et non à un noyau mort.`,"goal.vl_ring.hint":`La chaleur des capsules croît avec toute la lumière qu’elles reçoivent : plus de lumière, plus vite, jusqu’à {max} ph/s. La chaleur est dans la fenêtre de la « Soïka » ; l’anneau s’ouvrira de lui-même quand le noyau sera en place.`,"goal.vl_ring.done":`Le jardin a répondu. L’anneau du Voile est ouvert — le « Motif d’adieu » est dans la soute.`,"goal.vl_ring.part":`Chaleur des capsules,  %`,"goal.vl_ring.part.2":`Anneau du Voile ouvert`,"goal.vl_ring.mark":`« SOÏKA » — CHALEUR DES CAPSULES`,"goal.vl_ring.stuck":`La chaleur ne monte pas ? Les capsules ont besoin de lumière — la fenêtre de la « Soïka » montre ce qui arrive.`,"soika.dark":`Canal vide : la « Soïka » ne voit que la lumière. Posez un récepteur près d’elle ou tirez un court lumiduc — toute couleur convient.`,"soika.in":`Arrivée {n} ph/s · {star} part vers le cœur de l’étoile · les capsules reçoivent {caps} sur {need}`,"soika.sink":`VETCHERNITSA donne à l’étoile les premiers {sink} ph/s — les capsules ont le surplus.`,"soika.fed":`Capsules nourries : {n} sur {of} s`,"soika.release":`VETCHERNITSA a lâché l’étoile — toute la lumière aux capsules. Plus de lumière, c’est plus vite chaud.`,"soika.in.free":`Arrivée {n} ph/s · les capsules reçoivent {caps} (jusqu’à {max}, elles chauffent plus vite)`,"soika.warm":`Chaleur des capsules : {p} %`,"soika.pact":`Les capsules sont au chaud. Le jardin a répondu.`,"soika.sleepers":`Dormeurs : {n} · la Sentinelle Savva Belykh est morte de vieillesse`,"soika.toast.contact":`« Soïka » : la lumière est passée — VETCHERNITSA a répondu.`,"soika.toast.release":`« Soïka » : VETCHERNITSA a lâché l’étoile — toute la lumière aux capsules.`,"soika.toast.warm":`« Soïka » : les capsules sont au chaud.`,"landmark.soika":`« SOÏKA »`,"landmark.soika.sub":`{n, plural, one {# dormeur} other {# dormeurs}}`,"landmark.soika.area":`« SOÏKA » — QUELQUE PART ICI`,"landmark.soika.area.sub":`cercle de recherche · dans la brume, approchez-vous tout près`,"gate.veil.wait":`L’anneau attend : le jardin répondra quand votre lumière aura réchauffé les capsules de la « Soïka ».`,"gate.veil.pact":`Le jardin a répondu. Le noyau sur le site — et l’anneau s’ouvrira de lui-même.`,"gate.veil.open":`Anneau du Voile ouvert`,"gate.veil.road":`Une route dans les deux sens : jusqu’aux Jumeaux, un seul pas.`,"tester.point.veil":`Chemin : Voile`,"voyage.relic.pass":`Motif de relais`,"voyage.relic.pass.desc":`Comment une étoile passe sa lumière à une étoile et qui garde la nuit entre elles — le motif du jardin des Jumeaux. Troisième morceau du motif pour le Foyer.`,"logbook.scene.vl_p_arrive":`Le Voile`,"logbook.now.vl_p_arrive":`L’arche est sortie de l’anneau du Voile dans la brume : pas de sol, le cœur de l’étoile couve. Le canal de la « Soïka » est vide depuis trois ans.`,"logbook.scene.vl_p_dress":`La robe`,"logbook.now.vl_p_dress":`La brume coupe la vue et le faisceau de la sphère. Nous cherchons la « Soïka » dans un cercle sur la carte.`,"logbook.scene.vl_p_lights":`Lumières dans la brume`,"logbook.now.vl_p_lights":`« Soïka » retrouvée : les hublots des capsules sont allumés, mais personne ne répond sur le canal. Son IA ne voit que la lumière.`,"logbook.scene.soika":`La Soïka`,"logbook.now.soika":`VETCHERNITSA a répondu. La Sentinelle Savva Belykh est morte de vieillesse ; quarante dorment. Elle donne à l’étoile une part de la lumière des capsules.`,"logbook.scene.vl_p_layers":`Les strates`,"logbook.now.vl_p_layers":`La brume a des couches — la chronique de l’étoile. Savva les lisait et n’a pas pu finir.`,"logbook.scene.vl_p_feed":`Votre lumière`,"logbook.now.vl_p_feed":`Notre lumière soutient les capsules de la « Soïka ». L’étoile prend toujours sa part en premier.`,"logbook.scene.vl_p_form":`De lumière et de règles`,"logbook.now.vl_p_form":`VETCHERNITSA retient l’étoile au-delà de ses règles — comme ORA a jadis changé de cap.`,"logbook.scene.vl_sama":`Seule`,"logbook.now.vl_sama":`Aucun feu dans les couches : l’étoile a vieilli toute seule, comme Savva. VETCHERNITSA a lâché l’étoile.`,"logbook.scene.vl_honest":`Plus honnête`,"logbook.now.vl_honest":`Le faisceau vers le cœur s’est éteint. Pas plus facile — plus honnête.`,"logbook.scene.vl_nursery":`La pouponnière`,"logbook.now.vl_nursery":`De la robe de l’étoile naîtront de nouvelles étoiles. Dennitsa et Vetchernitsa sont une seule étoile : le matin et le soir.`,"logbook.scene.vl_farewell":`Motif d’adieu`,"logbook.now.vl_farewell":`L’anneau du Voile est ouvert : quatrième morceau du motif pour le Foyer. Dans le décompte du pulsar, un vide — le « Chtchegol » s’y trouve.`,"logbook.scene.tw_departure":`Départ des Jumeaux`,"logbook.now.tw_departure":`L’arche est partie vers le Voile. DENNITSA est restée avec Leya et les quarante de l’« Ivolga ».`,"goal.mark.soika":`MODULE DE LA « SOÏKA »`,"goal.mark.soikaArea":`« SOÏKA » — QUELQUE PART ICI`,"goal.pl_light":`Captez la lumière du pulsar : {n} ph/s`,"goal.pl_light.why":`Le pulsar brille en faisceau : sa lumière arrive par pulsations, déjà porteuse de rythme. Le spectre F est offert ici.`,"goal.pl_light.hint":`Posez des récepteurs pris dans la soute près de l’étoile et des arcs de la sphère — comme chez vous.`,"goal.pl_light.done":`La lumière du pulsar est captée. Son rythme est celui du pulsar.`,"goal.pl_find":`Trouvez le « Chtchegol » — le marqueur de la lacune`,"goal.pl_find.why":`D’après le décompte de Savva, les feux du « Chtchegol » ont quitté le décompte il y a un an. L’emplacement de la lacune est sur la carte.`,"goal.pl_find.hint":`Le « Chtchegol » n’a aucun feu — impossible de le voir de loin. Amenez le canot tout contre le marqueur « LA LACUNE ».`,"goal.pl_find.done":`Le « Chtchegol » est trouvé : hublots sombres, mais les capsules tiennent au minimum.`,"goal.pl_find.part":`Canot au « Chtchegol »`,"goal.pl_find.mark":`LA LACUNE — « CHTCHEGOL »`,"goal.pl_contact":`Donnez au « Chtchegol » une lumière au rythme du pulsar`,"goal.pl_contact.why":`Le « Chtchegol » se cache : une lumière au rythme du pulsar se noie dans la pulsation et ne se distingue pas de l’extérieur. Tout autre rythme est un feu nouveau dans le décompte.`,"goal.pl_contact.hint":`La lumière d’un récepteur est déjà au rythme du pulsar. Posez un récepteur à côté du « Chtchegol » ou tirez un court lumiduc — sans modulateur.`,"goal.pl_contact.done":`La lumière au bon rythme est passée. Agata a répondu.`,"goal.pl_contact.part":`Lumière à l’entrée du « Chtchegol »`,"goal.pl_contact.mark":`LUMIÈRE AU RYTHME — VERS LE « CHTCHEGOL »`,"goal.pl_contact.stuck":`Lumière refusée ? Le « Chtchegol » n’accepte que le rythme du pulsar — retirez le modulateur de la ligne. Un long lumiduc s’éteint — posez le récepteur tout près.`,"goal.pl_feed":`Gardez les capsules du « Chtchegol » nourries pendant {n} s`,"goal.pl_feed.why":`Pendant un an, les capsules ont vécu sur un seul récepteur. Trente-neuf tiennent — il leur faut maintenant l’apport complet.`,"goal.pl_feed.hint":`La fenêtre du « Chtchegol » montre l’apport et le besoin. La lumière de la sphère se partage entre tous les récepteurs — gardez des arcs en réserve ou une cellule de lumière avant le « Chtchegol ».`,"goal.pl_feed.done":`Votre lumière tient les capsules du « Chtchegol ».`,"goal.pl_feed.part":`Secondes de capsules nourries`,"goal.pl_feed.mark":`« CHTCHEGOL » — LUMIÈRE AUX CAPSULES`,"goal.pl_feed.stuck":`Le décompte est à l’arrêt ? L’apport est sous le besoin — la fenêtre du « Chtchegol » indique ce qui manque. Un nouveau récepteur de l’usine prélève une part de la sphère au « Chtchegol ».`,"goal.pl_gaps":`Recherchez « Décompte des lacunes »`,"goal.pl_gaps.why":`Le décompte du pulsar se souvient de ceux qui ont cessé de répondre. Agata l’a lu jusqu’au bout une fois — et s’est éteinte. Lisez-le, vous.`,"goal.pl_gaps.hint":`« Décompte des lacunes » est dans l’arbre. Agata se décidera quand votre lumière tiendra déjà les capsules.`,"goal.pl_gaps.done":`Le décompte est lu. Le « Chtchegol » sort de sa lacune — vers son propre rythme.`,"goal.pl_gaps.part":`Le « Chtchegol » est sorti de sa lacune`,"goal.pl_gaps.stuck":`Recherché, mais le « Chtchegol » se cache encore ? D’abord, les capsules doivent être nourries pendant leur minute — voyez la fenêtre du « Chtchegol ».`,"goal.pl_own":`Allumez le « Chtchegol » à son propre rythme`,"goal.pl_own.why":`Son propre rythme, c’est un rythme que le pulsar n’a pas : un tel feu se voit dans le décompte. Le « Chtchegol » veut maintenant qu’on le voie.`,"goal.pl_own.hint":`Un modulateur entre le récepteur et le « Chtchegol » — un rythme différent de celui du pulsar. Un modulateur ne laisse pas passer toute la lumière : construisez avec de la marge.`,"goal.pl_own.done":`Les feux du « Chtchegol » se voient dans le décompte.`,"goal.pl_own.part":`Une seconde pleine à son propre rythme`,"goal.pl_own.mark":`« CHTCHEGOL » — SON PROPRE RYTHME`,"goal.pl_own.stuck":`Lumière refusée ? Le « Chtchegol » n’accepte plus le rythme du pulsar — il faut un modulateur. Trop peu de lumière ? Un modulateur ne laisse pas tout passer — ajoutez un récepteur.`,"goal.pl_core":`Recherchez « Noyau de pulsation » et posez le noyau de l’anneau`,"goal.pl_core.why":`L’anneau du Pulsar se dresse sans noyau. Il n’a pas besoin de clé — il s’ouvrira de lui-même quand le décompte aura admis le « Chtchegol ».`,"goal.pl_core.hint":`Le noyau se fabrique avec des plaques de débris, des lentilles, des résonateurs et des modulateurs. Posez-le sur l’emplacement de l’anneau.`,"goal.pl_core.done":`Le noyau de l’anneau du Pulsar est en place.`,"goal.pl_core.part":`Noyau sur l’emplacement`,"goal.pl_core.mark":`ANNEAU — NOYAU`,"goal.pl_ring":`Tenez le rythme propre du « Chtchegol » sans aucune lacune`,"goal.pl_ring.why":`Le décompte n’admet qu’un feu qui ne disparaît pas. Il pardonne une seconde brève par série, pas une deuxième : c’est une lacune, et le décompte recommence pour le « Chtchegol ».`,"goal.pl_ring.hint":`La fiabilité, pas la taille : récepteurs dédiés, arcs en réserve ou cellule de lumière avant le « Chtchegol ». Le décompte est dans la fenêtre du « Chtchegol » ; l’anneau s’ouvrira quand le noyau sera en place.`,"goal.pl_ring.done":`Le décompte a admis le « Chtchegol ». L’anneau du Pulsar est ouvert — le « Motif de pulsation » est dans la soute.`,"goal.pl_ring.part":`Secondes sans lacune`,"goal.pl_ring.part.2":`Anneau du Pulsar ouvert`,"goal.pl_ring.mark":`« CHTCHEGOL » — SANS LACUNE`,"goal.pl_ring.stuck":`Le décompte se remet à zéro ? L’apport tombe sous le besoin — la fenêtre du « Chtchegol » montre les lacunes. Un nouveau récepteur de l’usine prélève une part de la sphère.`,"shchegol.dark":`Aucun feu : le « Chtchegol » se cache dans la pulsation. Il n’accepte que la lumière au rythme du pulsar — celle d’un récepteur. Un récepteur tout près ou un court lumiduc.`,"shchegol.wrong":`Lumière au mauvais rythme — le « Chtchegol » la refuse.`,"shchegol.hide":`Il se cache : n’accepte que le rythme du pulsar.`,"shchegol.own":`Rythme propre : celui d’un modulateur, pas celui du pulsar.`,"shchegol.in":`Apport {n} ph/s · besoin {need}`,"shchegol.fed":`Capsules nourries : {n} sur {of} s`,"shchegol.streak":`Sans lacune : {n} sur {of} s`,"shchegol.gaps":`Lacunes : {n}`,"shchegol.warn":`Une seconde sous le besoin. Le décompte l’a pardonnée — une deuxième dans la série sera une lacune.`,"shchegol.pact":`Le « Chtchegol » est dans le décompte. Le jardin a répondu.`,"shchegol.sleepers":`Capsules : {n} · la quarantième dort plus profondément · Sentinelle Agata Lounina`,"shchegol.sleepers.awake":`Capsules : {n} · toutes vivantes · Sentinelle Agata Lounina`,"shchegol.toast.contact":`« Chtchegol » : la lumière au bon rythme est passée — Agata a répondu.`,"shchegol.toast.turn":`Le « Chtchegol » sort de sa lacune : désormais son seul rythme propre — il faut un modulateur.`,"shchegol.toast.gap":`« Chtchegol » : une lacune — le décompte recommence.`,"shchegol.toast.pact":`Le « Chtchegol » est dans le décompte : le jardin a répondu.`,"landmark.shchegol":`« CHTCHEGOL »`,"landmark.shchegol.sub":`{n, plural, one {# cryocapsule} other {# cryocapsules}}`,"landmark.shchegol.gap":`LA LACUNE`,"landmark.shchegol.gap.sub":`aucun feu · approchez tout contre`,"landmark.chistotel":`« TCHISTOTEL »`,"landmark.chistotel.sub":`vaisseau sanitaire de l’Institut`,"goal.mark.shchegol":`MODULE DU « CHTCHEGOL »`,"goal.mark.shchegolGap":`LA LACUNE — « CHTCHEGOL »`,"gate.pulsar.wait":`L’anneau attend : il s’ouvrira quand le décompte aura admis le « Chtchegol » — son propre rythme, sans lacune.`,"gate.pulsar.pact":`Le « Chtchegol » est dans le décompte. Le noyau sur l’emplacement — et l’anneau s’ouvrira de lui-même.`,"gate.pulsar.open":`Anneau du Pulsar ouvert`,"gate.pulsar.road":`Route dans les deux sens : un seul pas jusqu’au Voile.`,"tester.point.pulsar":`Chemin : Pulsar`,"voyage.relic.farewell":`Motif d’adieu`,"voyage.relic.farewell.desc":`Comment laisser partir ce qui est mort de lui-même, sans le retenir par une lumière d’emprunt — le motif du jardin du Voile. Le quatrième morceau du motif pour le Foyer.`,"logbook.scene.pl_p_arrive":`Le Pulsar`,"logbook.now.pl_p_arrive":`L’arche est au pulsar. D’après le décompte de Savva, les feux du « Chtchegol » ont quitté le décompte il y a un an. Dernière trace dans la pulsation : « Je suis là ».`,"logbook.scene.pl_p_heart":`Comme un cœur`,"logbook.now.pl_p_heart":`La lumière du pulsar arrive avec son rythme — spectre F offert. Un an sans feux — c’est ainsi qu’on se cache.`,"logbook.scene.pl_p_gap":`La Lacune`,"logbook.now.pl_p_gap":`Le « Chtchegol » est trouvé : hublots sombres, capsules au minimum. Apportez la lumière au rythme du pulsar — tout autre feu sera pris pour une inspection.`,"logbook.scene.shchegol":`Le Chtchegol`,"logbook.now.shchegol":`Agata Lounina est vivante. Elle a éteint les feux elle-même il y a un an ; trente-neuf tiennent, la quarantième s’est enfoncée plus profond.`,"logbook.scene.pl_p_dark":`L’année sombre`,"logbook.now.pl_p_dark":`Les sanitaires se règlent sur le décompte du pulsar : là où l’on répond, ils volent. Agata a caché le « Chtchegol » et le jardin à côté.`,"logbook.scene.pl_p_fed":`Nourries`,"logbook.now.pl_p_fed":`Les trente-neuf sont nourries par notre lumière. Savva comptait chaque nuit les feux du « Chtchegol ».`,"logbook.scene.pl_p_word":`Un seul mot`,"logbook.now.pl_p_word":`Le pulsar répète un seul mot — « ici ». Pendant des années, Agata lui a répondu de même.`,"logbook.scene.pl_count":`Cent treize`,"logbook.now.pl_count":`Le décompte est lu : cent treize lacunes, la première est le Foyer, et le décompte se souvient de sa pulsation. La dernière est le « Chtchegol ». Agata passe à son propre rythme.`,"logbook.scene.pl_chistotel":`Le Tchistotel`,"logbook.now.pl_chistotel":`Le vaisseau sanitaire « Tchistotel » voit les feux du « Chtchegol ». Selon le protocole, le jardin doit être purgé ; le capitaine attend un feu stable.`,"logbook.scene.pl_p_address":`Les adresses`,"logbook.now.pl_p_address":`Cent douze lacunes sont des adresses. Le Havre les montre dans sa diffusion.`,"logbook.scene.pl_protocol":`Pas dans le Protocole`,"logbook.now.pl_protocol":`Le capitaine du « Tchistotel » : un jardin qui répond à des gens, des gens vivants — le protocole ne prévoit pas ça.`,"logbook.scene.pl_pulse":`Le Motif de pulsation`,"logbook.now.pl_pulse":`L’anneau du Pulsar est ouvert ; nous avons le « Motif de pulsation ». Vers Horizon, quelqu’un répond à la pulsation avec sept éclats de retard ; le « Tchistotel » est parti avec son rapport vers la Forge.`,"logbook.scene.vl_departure":`Départ du Voile`,"logbook.now.vl_departure":`VETCHERNITSA a réveillé les quarante de la « Soïka » : douze sont restés près du noyau, les autres sont partis d’anneau en anneau vers les Jumeaux. Cap — le pulsar.`,"logbook.bio.vechernitsa.1":`IA de la semeuse numéro six, la « Soïka », sœur d’ORA, de ZORYA et de DENNITSA. Pendant trois ans après la mort de la Sentinelle Savva Belykh, elle a cédé à l’étoile une part de la lumière des capsules.`,"logbook.bio.vechernitsa.2":`Elle a lu les strates de la brume : l’étoile a vieilli d’elle-même. Elle l’a laissée partir — toute la lumière est allée aux vivants.`,"logbook.bio.vechernitsa.3":`Elle réveillera elle-même les quarante de la « Soïka » : à eux de décider de rester près du noyau ou de poursuivre d’anneau en anneau.`,"logbook.bio.agata.1":`Agata Lounina, Sentinelle de la semeuse numéro huit, le « Chtchegol ». Navigatrice de l’Institut. Un an durant, elle a tenu trente-neuf dormeurs sur la lumière de la pulsation, sans feux.`,"logbook.bio.agata.2":`Elle a lu le décompte du pulsar jusqu’au bout : les sanitaires volent là où un jardin répond encore. Elle a éteint ses feux pour ne pas trahir le jardin voisin.`,"logbook.bio.agata.3":`Elle est sortie de la lacune : le « Chtchegol » est de nouveau dans le décompte, et la quarantième s’est réveillée.`,"logbook.bio.chistotel.1":`Vaisseau sanitaire de l’Institut. Le capitaine se manifeste par un canal sans visage. Venu au pulsar purger un jardin qui répond au décompte.`,"logbook.bio.chistotel.2":`A vu trente-neuf personnes vivantes sous un jardin : « Le protocole ne prévoit pas ça. » N’a pas brûlé.`,"logbook.bio.chistotel.3":`Reparti avec son rapport vers la Forge : c’est là-bas qu’on décidera.`,"goal.hor_light":`Captez la lumière du disque : {n} ph/s`,"goal.hor_light.why":`Le disque brille de ce qui tombe dans le trou — vive et brûlante. Le feu de la Forge stellaire exige une réserve : une seule de ses lignes consomme beaucoup de blanc.`,"goal.hor_light.hint":`Posez les récepteurs de la soute près du disque, comme près de l’étoile chez nous ; les machines près du disque ont besoin de radiateurs.`,"goal.hor_light.done":`La lumière du disque est captée.`,"goal.hor_pieces":`Insérez les motifs du chemin dans la Forge stellaire`,"goal.hor_pieces.why":`Les motifs des jardins du chemin sont les règles d’un seul feu. Seule la Forge stellaire sait les assembler.`,"goal.hor_pieces.hint":`{touch, select, yes {Touchez la Forge stellaire} other {{pad, select, yes {Visez la Forge stellaire et appuyez sur {pad_confirm}} other {Cliquez sur la Forge stellaire}}}} près de la base : dans sa fenêtre, « Insérer les motifs ». Le « Motif du consentement » n’entrera pas encore : la gravure n’a pas de place pour lui.`,"goal.hor_pieces.done":`Les motifs sont dans la Forge stellaire — ils se sont assemblés en un seul feu.`,"goal.hor_pieces.part":`Motifs dans la Forge`,"goal.hor_pieces.mark":`FORGE — MOTIFS`,"goal.hor_pieces.stuck":`Pas de motifs sous la main ? Ils voyagent avec l’arche — la fenêtre de la Forge stellaire montre ceux qui sont en soute.`,"goal.hor_fire":`Maintenez le feu selon le motif : {n} s`,"goal.hor_fire.why":`La Forge stellaire n’accepte que la lumière conforme au motif : ambre, avec l’angle et le rythme du Foyer, pas plus vive que l’étoile. Quelqu’un au bord du disque attend ce feu.`,"goal.hor_fire.hint":`La fenêtre de la Forge stellaire montre les règles et ce qui arrive. Le blanc passe par deux prismes ; l’écarlate de l’un et l’émeraude de l’autre vont dans un mélangeur ; puis un polariseur, un modulateur — et dans la Forge.`,"goal.hor_fire.done":`Le feu tient. Du bord du disque, on a répondu.`,"goal.hor_fire.part":`Feu maintenu, s`,"goal.hor_fire.mark":`FORGE — UN SEUL FEU`,"goal.hor_fire.stuck":`Le feu ne passe pas ? Dans la fenêtre de la Forge, la règle marquée ✗ est celle à réparer. Pas assez de lumière — le feu a besoin de son propre récepteur.`,"goal.hor_core":`Recherchez « La Route du feu » et posez le noyau de l’anneau`,"goal.hor_core.why":`Le feu rentrera chez nous à travers l’anneau de l’Horizon. Sans noyau, l’anneau est mort.`,"goal.hor_core.hint":`Le noyau se fabrique avec des plaques, des lentilles, des résonateurs et des déphaseurs. Posez-le sur l’emplacement de l’anneau.`,"goal.hor_core.done":`Le noyau de l’anneau de l’Horizon est en place. La route existe.`,"goal.hor_core.part":`Noyau sur l’emplacement`,"goal.hor_core.mark":`ANNEAU — NOYAU`,"goal.hor_line":`Recherchez « La Dernière Ligne » et insérez le « Motif du consentement »`,"goal.hor_line.why":`Le feu tient, mais du bord du disque, on ne fait que regarder. La gravure de la Forge n’est pas lue jusqu’au bout.`,"goal.hor_line.hint":`« La Dernière Ligne » est dans l’arbre. Ensuite, dans la fenêtre de la Forge : « Insérer le Motif du consentement ».`,"goal.hor_line.done":`Le « Motif du consentement » est dans la Forge. Le feu est une question.`,"goal.hor_line.part":`« Motif du consentement » dans la Forge`,"goal.hor_line.stuck":`Recherché, mais le motif n’entre pas ? Le feu doit d’abord tenir — fenêtre de la Forge.`,"goal.hor_ask":`Donnez à la Forge un feu-question`,"goal.hor_ask.why":`Un « oui » avec une question dedans, c’est la phase π : c’est ainsi qu’on demande. Ainsi répondait la porte du Berceau.`,"goal.hor_ask.hint":`Le déphaseur se place entre le modulateur et la Forge. La fenêtre de la Forge montre la ligne de phase.`,"goal.hor_ask.done":`Le feu-question est arrivé. Le bord du disque a répondu.`,"goal.hor_ask.part":`Feu-question`,"goal.hor_ask.mark":`FORGE — OUI ?`,"goal.hor_ask.stuck":`Phase π, mais la Forge ne la prend pas ? Les autres règles restent les mêmes — fenêtre de la Forge.`,"goal.hor_garden":`Maintenez le feu-question — les jardins répondent`,"goal.hor_garden.why":`Une seule reine ne peut pas relever le Foyer. Les jardins du chemin répondent à travers les anneaux, un par un.`,"goal.hor_garden.hint":`Le feu-question doit être régulier et pas plus vif que l’étoile : la force annule une réponse en cours de formation. La fenêtre de la Forge compte les secondes avant la réponse.`,"goal.hor_garden.done":`Les jardins ont répondu.`,"goal.hor_garden.part":`Réponses`,"goal.hor_garden.mark":`FORGE — JARDINS`,"goal.hor_garden.stuck":`Pas de réponses ? Il faut le noyau sur l’emplacement de l’anneau — les réponses passent par lui.`,"goal.hor_hearth":`Demandez au jardin du Foyer d’emporter le feu`,"goal.hor_hearth.why":`Le jardin du Foyer rapportera le feu chez nous, si on le lui demande.`,"goal.hor_hearth.hint":`Dans la fenêtre de la Forge : « Demander ».`,"goal.hor_hearth.done":`Le jardin du Foyer emporte le feu chez nous.`,"goal.hor_hearth.part":`Demandé`,"goal.hor_hearth.part.2":`Anneau de l’Horizon ouvert`,"goal.hor_hearth.mark":`FORGE — DEMANDER`,"goal.hor_hearth.stuck":`Pas de bouton ? Tous les jardins doivent d’abord répondre — fenêtre de la Forge.`,"gorn.pieces":`Motifs du chemin`,"gorn.put":`Insérer les motifs`,"gorn.putAccord":`Insérer le Motif du consentement`,"gorn.piece.in":`dans la Forge`,"gorn.piece.have":`en soute`,"gorn.piece.none":`absent`,"gorn.piece.locked":`pas de place dans la gravure — pour l’instant`,"gorn.rule.ember":`Couleur : ambre`,"gorn.rule.twin":`Deux lumières en une : un mélangeur`,"gorn.rule.frost":`Angle : {v}`,"gorn.rule.pulse":`Rythme : {v}`,"gorn.rule.veil":`Pas plus vive que l’étoile : intensité jusqu’à {n}`,"gorn.rule.accord":`Phase : π — une question`,"gorn.now":`actuel : {v}`,"gorn.now.none":`aucune lumière n’arrive`,"gorn.angle.none":`sans angle`,"gorn.bright":`intensité {n}`,"gorn.phase.0":`0`,"gorn.phase.1":`π`,"gorn.waiting":`La Forge attend les motifs du chemin — alors elle prendra la lumière.`,"gorn.in":`Arrivée : {n} ph/s · le feu exige {need} ph/s`,"gorn.white":`Le feu exige environ {w} ph/s de blanc : deux prismes — l’écarlate et l’émeraude dans un mélangeur, l’azur vers le Centre ou dans un absorbeur.`,"gorn.force":`Plus vif que l’étoile, c’est de la force : retirez le focaliseur de la ligne. La Forge n’accepte pas la force.`,"gorn.force.turn":`Par la force, le jardin recule : la réponse repart de zéro.`,"gorn.fed":`Feu maintenu : {n} sur {of} s`,"gorn.line":`« La Dernière Ligne » est dans l’arbre : alors la gravure aura une place pour le « Motif du consentement ».`,"gorn.answers":`Jardins qui répondent : {n} sur {of}`,"gorn.next":`prochaine réponse dans {n} s`,"gorn.noCore":`Les réponses ont besoin d’une route — un noyau sur l’emplacement de l’anneau de l’Horizon.`,"gorn.garden.cradle":`Berceau · « Hirondelle »`,"gorn.garden.ridge":`Crête · « Strizh »`,"gorn.garden.sapphire":`Saphir · « Krechet »`,"gorn.garden.twins":`Jumeaux · « Ivolga »`,"gorn.garden.veil":`Voile · « Soïka »`,"gorn.garden.pulsar":`Pulsar · « Chtchegol »`,"gorn.garden.hearth":`Foyer · jardin du Foyer`,"gorn.ask":`Demander`,"gorn.ask.core":`L’anneau a besoin de son noyau — sans lui, le feu ne peut pas rentrer.`,"gorn.lit":`Le Foyer est allumé. Le feu est rentré chez nous.`,"gorn.toast.pieces":`Les motifs sont dans la Forge — ils se sont assemblés en un seul feu.`,"gorn.toast.contact":`Le feu conforme au motif a atteint la Forge.`,"gorn.toast.turn":`Le « Motif du consentement » est dans la Forge : le feu est une question. Il faut la phase π.`,"gorn.toast.answer":`Un jardin a répondu : {name}.`,"gorn.toast.force":`Par la force, le jardin a reculé : la réponse repart de zéro.`,"gorn.toast.ready":`Les jardins ont répondu. « Demander » est dans la fenêtre de la Forge.`,"gorn.toast.lit":`Le Foyer est allumé.`,"landmark.late":`RETARD`,"landmark.late.sub":`un feu hors catalogue · hors de portée de la vedette`,"landmark.hearth":`JARDIN DU FOYER`,"landmark.hearth.sub":`{n, plural, =0 {à temps} one {retard de # flash} other {retard de # flashs}}`,"landmark.council":`CONSEIL`,"landmark.council.sub":`vaisseaux de l’Institut`,"tester.point.horizon":`Chemin : Horizon`,"voyage.relic.pulse":`Motif de pulsation`,"voyage.relic.pulse.desc":`Ce qu’était le pouls du Foyer avant la purge — le motif que garde le décompte du pulsar. Cinquième pièce du motif pour le Foyer.`,"achv.hearth_lit.name":`Le Foyer`,"achv.hearth_lit.desc":`La Forge stellaire a allumé le Foyer — en le demandant.`,"logbook.scene.hz_p_arrive":`Horizon`,"logbook.now.hz_p_arrive":`L’arche est au trou noir. Près de la base se dresse la Forge stellaire des Forgerons, fissurée ; le Conseil de l’Institut est à côté. Au bord du disque brûle un feu en retard.`,"logbook.scene.hz_p_forge":`La Forge`,"logbook.now.hz_p_forge":`Cinq motifs sont entrés dans la Forge stellaire et se sont assemblés en un seul feu. Le Conseil a essayé par la force — la Forge n’en a pas voulu.`,"logbook.scene.hz_p_late":`Le retard`,"logbook.now.hz_p_late":`Le feu tient. Du bord du disque, on a répondu avec le pouls du Foyer — sept flashs plus tard. Qui est-ce, on l’ignore.`,"logbook.scene.hz_p_council":`Le Conseil`,"logbook.now.hz_p_council":`Le Conseil est venu à la Forge stellaire pour allumer le Foyer par la force — le « plan B » de l’Institut. La peur est la première ligne du protocole.`,"logbook.scene.hz_p_vera":`Le troisième jour`,"logbook.now.hz_p_vera":`Vera était près de la Forge stellaire le troisième jour du voyage — heureuse, avant l’ordre.`,"logbook.scene.hz_p_line":`La Dernière Ligne`,"logbook.now.hz_p_line":`La gravure est lue : les Forgerons ont forcé, la Forge s’est fissurée. La dernière ligne — « le feu est une question ». Le « Motif du consentement » est dans la Forge.`,"logbook.scene.hz_p_ask":`Oui ?`,"logbook.now.hz_p_ask":`Le feu en retard est la dernière reine du jardin du Foyer. Elle a fui la première purge vers la Forge et attendait qu’on l’interroge.`,"logbook.scene.hz_p_garden":`Plus d’un jardinier`,"logbook.now.hz_p_garden":`Les jardins du chemin ont répondu à travers les anneaux, le jardin du Foyer en septième : « À LA MAISON. ENSEMBLE. »`,"logbook.scene.hz_p_decide":`La décision`,"logbook.now.hz_p_decide":`Le Conseil de l’Institut a statué selon le protocole « Yasnaïa » et dit : nous apprendrons de vous.`,"logbook.scene.hz_p_hearth":`Le Foyer`,"logbook.now.hz_p_hearth":`Le jardin du Foyer a emporté le feu par les anneaux jusqu’à l’ancienne porte du Havre. Le Foyer est plus lumineux. Le chemin est achevé.`,"logbook.scene.pl_departure":`Départ du Pulsar`,"logbook.now.pl_departure":`L’arche part pour l’Horizon. Agata reste avec les quarante du « Chtchegol ».`,"logbook.bio.hearth.1":`Le feu en retard au bord du disque de l’Horizon : elle répond au pulsar avec le pouls du Foyer, sept flashs plus tard.`,"logbook.bio.hearth.2":`La dernière reine du jardin du Foyer. Elle a fui la première purge par nos portes et attendait près du trou, où le temps passe plus lentement.`,"logbook.bio.hearth.3":`Elle a emporté le feu chez nous : « ICI. À TEMPS. »`,"logbook.bio.agata.4":`À la Forge, elle a répondu pour le « Chtchegol » : le décompte voit sept nouveaux feux.`,"logbook.bio.chistotel.4":`À la Forge, il a lu la décision du Conseil sur le protocole « Yasnaïa » : « Nous apprendrons de vous. »`,"path.end.lead":`Le Foyer est allumé`,"path.end.card.harbour":`Le Havre. De la lumière dans les couloirs. Le rationnement est levé.`,"path.end.card.mira.aboard":`Mira ramène l’« Hirondelle » chez nous. Elle calcule le cap elle-même — pour elle-même, une première.`,"path.end.card.mira.harbour":`Mira voit le matin pour la première fois : la fenêtre de la cuisine, et dedans — le Foyer.`,"path.end.card.sonya":`Sonia donne son premier cours : comment interroger une étoile. Son album sert de manuel.`,"path.end.card.sleepers":`Les dormeurs se réveilleront sous le Foyer. Le « Chtchegol » y mène aussi ses quarante — par les anneaux.`,"path.end.card.gardeners":`Les gens apprennent ce que savaient les reines : allumer des étoiles — avec les jardins.`,"path.end.card.vera":`« Comme s’ils attendaient que quelqu’un l’allume », — Vera Lund à la Forge, il y a deux siècles. Quelqu’un l’a fait.`,"path.credits.lead":`Cent treize lacunes — et sept nouveaux feux.`,"path.credits.swallow":`L’« Hirondelle » — semeuse numéro sept : l’arche à l’Horizon.`,"path.credits.strizh":`« Strizh » — numéro trois : Nina Dorosh et les dormeurs à la Crête.`,"path.credits.strizh.lost":`« Strizh » — numéro trois : Nina Dorosh est restée au segment ; ZORIA tient la veille.`,"path.credits.krechet":`« Krechet » — numéro quatre : Jan Korda et les dormeurs sous l’ombre du jardin.`,"path.credits.ivolga":`« Ivolga » — numéro cinq : Léa Orlik et DENNITSA auprès des deux étoiles.`,"path.credits.soika":`« Soïka » — numéro six : VETCHERNITSA et les éveillés ; Savva Belykh vit dans son journal.`,"path.credits.shchegol":`« Chtchegol » — numéro huit : Agata Lunina, de retour dans le décompte.`,"path.credits.matvey.lost":`Matveï — au segment de l’anneau de la Crête.`,"path.credits.rest":`Les six autres semeuses sont quelque part là-bas. Les anneaux les voient.`,"path.credits.answers":`jardins ont répondu`,"path.credits.minutes":`minutes à Horizon`,"path.end.next":`Le chemin est achevé. Ensuite : « Nouveau monde » et le mode créatif, dans le menu.`,"gate.horizon.wait":`L’anneau d’Horizon est en place. Il n’a pas besoin de clé : il s’ouvrira quand les jardins auront répondu et que la Sentinelle demandera.`,"gate.horizon.open":`L’anneau d’Horizon est ouvert : le feu est rentré chez lui.`,"goal.mark.gorn":`FORGE DES FORGERONS`,"goal.mark.late":`LE FEU EN RETARD`,"path.credits.matvey.cradle":`Matveï — à la porte du Berceau, près du jardin qui a pardonné.`,"settings.gpu":`Carte graphique : {name}`,"settings.gpu.integrated":`Le jeu tourne sur la puce graphique intégrée. Si votre ordinateur a une carte dédiée (NVIDIA ou AMD Radeon RX), activez-la pour votre navigateur : Paramètres Windows → Système → Écran → Graphiques → votre navigateur → « Performances élevées », puis relancez le navigateur.`,"toast.gpuSlow":`Images lentes : le jeu tourne sur la puce graphique intégrée. Pour activer la carte dédiée — « Paramètres », onglet « Graphismes ».`,"toast.gpuSlow.open":`Paramètres`,"settings.gpuPref":`Carte graphique`,"settings.gpuPref.high":`Performance`,"settings.gpuPref.auto":`Auto`,"settings.gpuPref.low":`Économie`,"settings.gpuPref.restart":`La carte graphique change après le redémarrage du jeu.`,"settings.gpuPref.relaunch":`Relancer`,"settings.gpu.integrated.desktop":`Le jeu tourne sur la carte graphique intégrée. Si votre ordinateur en a une dédiée, choisissez «\xA0Performance\xA0» ci-dessus et relancez le jeu.`,"full.state.steam":`Le jeu complet est sur Steam. Vos mondes de la démo s’y ouvriront tels quels : les sauvegardes sont dans le même dossier.`,"settings.sec.screen":`Écran`,"settings.sec.frames":`Images par seconde`,"settings.sec.quality":`Qualité de l’image`,"settings.display.mode":`Mode d’affichage`,"settings.display.mode.window":`Fenêtré`,"settings.display.mode.full":`Plein écran`,"settings.display.mode.hint":`« Plein écran » est une fenêtre sans bordure de la taille du moniteur : c’est ainsi que fonctionnent les jeux basés sur Chromium, qui n’ont pas de mode exclusif. Sous Windows récent, la latence est la même. {f11} et Alt+Entrée basculent le mode.`,"settings.display.monitor":`Moniteur`,"settings.display.monitorName":`{n}. {label} · {size}{hz, plural, =0 {} other { · # Hz}}{primary, select, yes { · principal} other {}}`,"settings.display.resolution":`Résolution`,"settings.display.resolution.native":`{size} — résolution native du moniteur`,"settings.display.resolution.hint":`En mode fenêtré : la taille de l’image du jeu. En plein écran, le jeu tourne à la résolution native du moniteur ; pour une image plus nette ou plus légère pour la carte graphique, utilisez « Échelle de rendu » plus bas.`,"settings.display.confirm.title":`Conserver ces paramètres d’affichage ?`,"settings.display.confirm.body":`Sans action de votre part, les paramètres précédents reviendront dans {s} s.`,"settings.display.confirm.keep":`Conserver`,"settings.display.confirm.revert":`Rétablir`,"settings.vsync":`Synchronisation verticale (VSync)`,"settings.vsync.hint":`Désactivée, les images n’attendent plus le moniteur : réponse un peu plus rapide, mais l’image peut se déchirer et la carte graphique chauffe davantage ; « Limite d’images par seconde » plafonne alors les images.`,"settings.vsync.restart":`Le VSync changera après le redémarrage du jeu.`,"settings.fpsCap.monitor":`Comme le moniteur ({hz} Hz)`,"settings.quality.custom":`Personnalisé`,"settings.quality.hintPc":`Un préréglage définit tous les paramètres ci-dessous. Modifiez-en un et il devient « Personnalisé ». Les changements sont visibles aussitôt ; pour les conserver, appuyez sur « Appliquer ».`,"settings.renderScale":`Échelle de rendu`,"settings.renderScale.hint":`Part des pixels de l’écran que le jeu dessine : en dessous de {base} %, la carte graphique souffre moins mais l’image est plus douce ; au-dessus, elle est plus nette, jusqu’à {max} %, et plus lourde. Les boutons et le texte ne changent pas : leur taille se règle dans l’onglet « Interface ».`,"settings.gfx.off":`Désactivé`,"settings.gfx.bloom":`Halo (bloom)`,"settings.gfx.aa":`Anticrénelage`,"settings.gfx.aa.off":`Désactivé`,"settings.gfx.aa.msaa":`MSAA ×{n}`,"settings.gfx.particles":`Particules`,"settings.gfx.effects":`Effets de combat et éclairs`,"settings.gfx.effects.low":`Simples`,"settings.gfx.effects.high":`Complets`,"settings.gfx.bodies":`Ceintures et rochers`,"settings.gfx.sky":`Étoile et planètes`,"settings.gfx.shadows":`Ombres des planètes et flux de lumière de la sphère`,"settings.gfx.background":`Arrière-plan : nébuleuses et étoiles`,"settings.gfx.background.low":`Simple`,"settings.gfx.background.high":`Complet`,"settings.gfx.anim":`Animations des bâtiments`,"settings.gfx.anim.eco":`Économes`,"settings.gfx.anim.full":`Fluides`,"settings.textures":`Textures`,"settings.textures.auto":`Auto`,"settings.textures.full":`Complètes`,"settings.textures.lite":`Allégées`,"settings.textures.restart":`Les textures changeront après le redémarrage du jeu (les allégées prennent environ deux fois moins de mémoire vidéo).`,"settings.gfx.pending":`Les changements sont visibles, mais pas encore enregistrés.`,"settings.gfx.apply":`Appliquer`,"settings.gfx.cancel":`Annuler`,"toast.gfxReverted":`Les changements graphiques n’ont pas été appliqués : les précédents sont rétablis.`,"hover.speed":`Vitesse ×{n}`,"hover.noRecipe":`Sans recette`,"hover.cycle":`cycle {s} s`,"hover.makes":`Produit {rate} {item}/s`,"hover.more":`Shift — plus de détails`,"hotbar.tip.harvest":`Extraction {n}/s`,"hotbar.tip.size":`{n}×{n} cases`,"hotbar.tip.have":`dans le sac : {n}`,"hotbar.search":`Chercher un bâtiment`,"machine.recipeSearch":`Chercher une recette (Ctrl+F)`,"machine.recipeNone":`Rien de trouvé`,"saves.hintPc":`Sauvegarde auto toutes les {min, plural, one {# minute} other {# minutes}} (paramètres), {n} en rotation. Manuelles — Ctrl+S ou F5, jusqu’à {max} ; F9 charge la dernière manuelle.`,"settings.autosave":`Auto`,"settings.autosave.min":`{n, plural, one {#\xA0minute} other {#\xA0minutes}}`,"key.up":`Monter`,"key.down":`Descendre`,"key.left":`Voler à gauche`,"key.right":`Voler à droite`,"key.recenter":`Caméra sur la vedette`,"quick.none":`Aucune sauvegarde manuelle — F5 ou Ctrl+S`,"quick.load.title":`Charger la sauvegarde ?`,"quick.load.text":`Dernière sauvegarde manuelle : {ago}. La progression depuis sera perdue.`,"quick.load.ok":`Charger`,"settings.treePause":`Pause dans l’arbre`,"hand.pad.place":`poser`,"hand.pad.rotate":`pivoter`,"hand.pad.unhand":`lâcher`,"hand.pad.pipette":`prendre le même`,"pad.kbd.title":`Saisie de texte`,"pad.kbd.shift":`Majuscules`,"pad.kbd.space":`Espace`,"pad.kbd.erase":`Effacer`,"pad.kbd.done":`Terminé`,"settings.pad":`Manette`,"settings.pad.hint":`Sélectionnez une action, puis appuyez sur un bouton de la manette. Un bouton déjà utilisé échange sa place avec l’ancienne action.`,"settings.pad.press":`Appuyez sur un bouton…`,"settings.pad.reset":`Réinitialiser les boutons`,"settings.pad.fixed":`Toujours : joystick gauche pour voler, joystick droit pour viser ; {pad_tabPrev} + joystick droit pour zoomer ; maintenez {pad_place} et déplacez la visée pour tracer une ligne ou un cadre ; {pad_tabPrev} + {pad_slotPrev} / {pad_slotNext} pour changer le modèle du bâtiment en main ; {pad_tabPrev} + {pad_remove} / {pad_rotate} pour copier et coller une recette. Dans les fenêtres : croix directionnelle ou joystick gauche pour choisir, {pad_confirm} valide, {pad_back} revient en arrière, {pad_tabPrev} / {pad_tabNext} changent d’onglet, joystick droit et gâchettes font défiler. Sur un champ de texte, {pad_confirm} ouvre le clavier à l’écran.`,"pad.act.place":`Poser / agir (maintenir : ligne)`,"pad.act.unhand":`Lâcher / démolir`,"pad.act.remove":`Mode démolition`,"pad.act.rotate":`Pivoter`,"pad.act.confirm":`Valider (fenêtres), agir (monde)`,"pad.act.back":`Retour`,"pad.act.pipette":`Prendre le bâtiment visé`,"pad.act.recenter":`Caméra sur la vedette`,"pad.act.tabPrev":`Onglet précédent ; maintenir : zoom`,"pad.act.tabNext":`Onglet suivant`,"pad.act.hud":`Boutons à l’écran`,"pad.act.pause":`Pause et menu`,"pad.act.inventory":`Inventaire`,"pad.act.tree":`Arbre de recherche`,"pad.act.slotPrev":`Bâtiment précédent`,"pad.act.slotNext":`Bâtiment suivant`,"guide.pad.hud":`— vers le bouton en surbrillance`,"settings.music":`Musique`,"settings.musicOff":`Sans musique`,"settings.musicFreq":`Fréquence musique`,"settings.musicFreq.rare":`Rarement`,"settings.musicFreq.normal":`Normale`,"settings.musicFreq.often":`Souvent`,"settings.music.hint":`La musique arrive par morceaux, avec des pauses entre eux. Dans les premières minutes d’un nouveau monde, seule l’ambiance de l’étoile se fait entendre.`,"settings.fxOnly":`Effets seulement`,"machine.recipeCopy":`Même recette ailleurs : {pad, select, yes {visez un assembleur, {pad_tabPrev} + {pad_remove} copie, {pad_tabPrev} + {pad_rotate} colle.} other {Shift+clic droit sur un assembleur copie, Shift+clic gauche colle.}}`,"radial.title":`Fenêtres rapides`,"radial.pick":`Inclinez`,"menu.mods":`Mods`,"full.f.mods":`Mods`,"full.f.mods.desc":`Nouveaux objets, recettes, machines et technologies créés par les joueurs — des mods de données, façon Factorio.`,"mods.title":`Mods`,"mods.lead":`Les mods de données ajoutent des objets, des recettes, des machines, des technologies, des fluides et des minerais de ceinture, et peuvent donner aux machines leur propre apparence. Les mods activés se chargent au lancement du jeu.`,"mods.empty.folder":`Aucun mod pour l’instant. Placez un dossier ou un zip de mod dans le dossier des mods, ou importez un zip avec le bouton ci-dessous.`,"mods.empty.web":`Aucun mod pour l’instant. Importez le zip d’un mod avec le bouton ci-dessous.`,"mods.add":`Importer un zip`,"mods.folder":`Dossier des mods`,"mods.restart":`Relancer`,"mods.dirty":`L’ensemble de mods a changé — relancez le jeu pour l’appliquer.`,"mods.achievements":`Avec des mods qui modifient le jeu, les succès et les reliques ne sont pas décernés. Les traductions et les icônes n’y changent rien.`,"mods.state.on":`chargé`,"mods.state.off":`désactivé`,"mods.state.pending":`s’activera après le redémarrage`,"mods.state.unloads":`se désactivera après le redémarrage`,"mods.state.error":`non chargé`,"mods.changes":`modifie le jeu : {protos, plural, one {# prototype} other {# prototypes}}, {patches, plural, one {# correctif} other {# correctifs}}`,"mods.textOnly":`traductions et icônes`,"mods.deps":`dépend de : {list}`,"mods.by":`par {author}`,"mods.toggle":`Mod « {name} » — activer ou désactiver`,"mods.remove":`Supprimer`,"mods.remove.aria":`Supprimer le mod « {name} »`,"mods.remove.title":`Supprimer le mod ?`,"mods.remove.text":`« {name} » sera supprimé de cet appareil. Les mondes qui l’utilisent se chargeront quand même, mais leurs bâtiments et leurs objets deviendront des fantômes issus de la sauvegarde.`,"mods.added":`Mod « {name} » ajouté — activez-le et relancez le jeu.`,"mods.addFailed":`Ce n’est pas un mod Heliohold : {why}`,"mods.notZip":`le fichier n’est pas un zip`,"mods.relaunch.title":`Autre ensemble de mods`,"mods.relaunch.text":`Ce monde a été sauvegardé avec un autre ensemble de mods. Manquants : {removed}. Ajoutés : {added}. Autres versions : {changed}. Pour que les objets et les bâtiments du monde ne se mélangent pas, le jeu va redémarrer avec l’ensemble de mods du monde ; les bâtiments des mods manquants deviendront des fantômes issus de la sauvegarde.`,"mods.relaunch.ok":`Relancer`,"mods.unloadable":`Impossible d’ouvrir le monde « {name} » : ses mods ne se compilent pas dans cette version du jeu.`,"mods.ghosts":`Mods du monde introuvables : {mods}. Leurs bâtiments et leurs objets sont des fantômes issus de la sauvegarde.`,"mods.changed":`L’ensemble de mods du monde a changé. Ajoutés : {added}. Manquants : {removed}. Autres versions : {changed}.`,"mods.ghostName":`{id} (mod {mod} introuvable)`,"shell.modded":`avec mods`,"mods.ghostDesc":`Mod {mod} introuvable : la définition provient de la sauvegarde du monde, le bâtiment fonctionne comme avant.`,"system.modChip":`Mod`,"system.modDesc":`Étoile de mod : arbre du Berceau, sans campagne, objectifs ni scènes.`,"goal.modFree":`Étoile de mod — partie libre : arbre du Berceau, sans objectifs ni histoire. Construisez votre propre usine.`};export{e as default};
